var __index = {"config":{"lang":["zh"],"separator":"[\\s\\u200b\\u3000\\-\u3001\u3002\uff0c\uff0e\uff1f\uff01\uff1b]+","pipeline":["stemmer"],"fields":{"title":{"boost":1000.0},"text":{"boost":1.0},"tags":{"boost":1000000.0}}},"docs":[{"location":"index.html","title":"tkdeft","text":"<p>\u610f\u4e3a <code>\u7075\u5de7</code>\uff0c\u7075\u6d3b\u8f7b\u5de7\u597d\u7528\u3002</p> <p>\u7ee7 <code>tkadw</code> \u4e4b\u540e\u7684 <code>tkinter</code> \u73b0\u4ee3\u5316\u754c\u9762\u5e93\u3002</p> <p>\u5f00\u53d1\u4e2d</p>"},{"location":"index.html#_1","title":"\u6ce8\u610f","text":"<p>\u8fd9\u91cc\u5df2\u7ecf\u6210\u4e3a tkfluent \u7684\u57fa\u7840\u5e93\uff0c \u672c\u8eab\u4e0d\u542b tkfluent \u7684\u7ec4\u4ef6\u3002</p> <p>\u5982\u679c\u4f60\u60f3\u4f53\u9a8c\u6269\u5c55\u754c\u9762\u5e93\u7684\u6548\u679c\uff0c\u8bf7\u53bb tkfluent \u67e5\u9605\u3002</p>"},{"location":"index.html#_2","title":"\u539f\u7406","text":"<p>\u4e00\u53e5\u8bdd\uff1a\u5148\u7528\u77e2\u91cf\u7ed8\u56fe\u751f\u6210\u56fe\u7247\uff0c\u518d\u4ea4\u7ed9 <code>Canvas</code> / <code>Label</code> \u663e\u793a\u51fa\u6765\u3002</p> <p>\u5177\u4f53\u8d70\u54ea\u6761\u8def\u662f\u53ef\u5207\u6362\u7684\uff1a</p> \u65b9\u5f0f \u8fc7\u7a0b SVG \u5f15\u64ce\uff08\u9ed8\u8ba4 <code>tksvg</code>\uff09 <code>svgwrite</code> \u751f\u6210 SVG \u2192 \u5199\u4e34\u65f6\u6587\u4ef6 \u2192 <code>tksvg</code> \u8bfb\u56de\u6765\u6805\u683c\u5316 \u6805\u683c\u5f15\u64ce\uff08<code>skia</code> / <code>pillow</code> / <code>cairo</code>\uff09 \u8fdb\u7a0b\u5185\u76f4\u63a5\u753b\u5230\u4f4d\u56fe\uff0c\u5b8c\u5168\u4e0d\u78b0\u78c1\u76d8 <p>\u6805\u683c\u5f15\u64ce\u914d\u5408\u56fe\u7247\u7f13\u5b58\u540e\uff0c\u76f8\u540c\u89c4\u683c\u7684\u7ed8\u5236\u7ed3\u679c\u4f1a\u88ab\u590d\u7528\u2014\u2014\u5728 tkfluent \u91cc\u5b9e\u6d4b\u6309\u94ae\u91cd\u7ed8\u5feb\u4e86\u7ea6 39 \u500d\u3002</p> <p>\u7ec6\u8282\u89c1 \u7ed8\u5236\u5f15\u64ce\u3002</p> <p>\u8fd9\u5176\u4e2d\u8fd8\u662f\u6709\u4e9b\u5751\u7684\uff0c\u6bd4\u5982\u56fe\u7247\u4e0d\u663e\u793a\u2014\u2014\u90a3\u5176\u5b9e\u662f <code>PhotoImage</code> \u88ab\u5783\u573e\u56de\u6536 \u5bfc\u81f4\u7684\uff0c\u89c1 \u81ea\u5b9a\u4e49\u7ec4\u4ef6\u3002</p>"},{"location":"index.html#_3","title":"\u5feb\u901f\u4e0a\u624b","text":"<pre><code>pip install -U tkdeft\n</code></pre> <pre><code>from tkdeft.engines import RoundRectSpec, render_roundrect, set_engine\n\nset_engine(\"skia\")                       # \u6362\u6210\u8fdb\u7a0b\u5185\u6805\u683c\u5f15\u64ce\uff08\u53ef\u9009\uff09\n\nspec = RoundRectSpec(width=120, height=32, rx=6,\n                     fill=\"#ffffff\", outline=\"#000000\",\n                     outline_opacity=0.2, outline_width=1)\n\nphoto = render_roundrect(spec, master=my_canvas)   # -&gt; PhotoImage\n</code></pre> <p>\u60f3\u642d\u81ea\u5df1\u7684\u7ec4\u4ef6\uff0c\u8bf7\u770b \u81ea\u5b9a\u4e49\u7ec4\u4ef6\u3002</p>"},{"location":"index.html#_4","title":"\u76ee\u5f55","text":"<ul> <li>\u5b89\u88c5\u4e0e\u4f7f\u7528</li> <li>\u7ed8\u5236\u5f15\u64ce</li> <li>\u81ea\u5b9a\u4e49\u7ec4\u4ef6</li> <li>API \u6587\u6863</li> <li>\u4ec0\u4e48\u662f\u6a21\u677f</li> </ul>"},{"location":"index.html#_5","title":"\u8ba1\u5212","text":"<p>\u672a\u6765\u6211\u6253\u7b97\u5148\u5236\u4f5c\u51fa <code>SunValley</code> \u8bbe\u8ba1\u7684\u5e93\u7136\u540e\u5c31\u53bb\u505a\u522b\u7684\u9879\u76ee\uff0c tkfluent\u3002</p> <p>\u81f3\u4e8e\u5b8c\u6574\u6587\u6863\uff0c\u6211\u540e\u9762\u4f1a\u52a0\u7d27\u5236\u4f5c\u7684\u3002</p>"},{"location":"index.html#_6","title":"\u8bbe\u8ba1\u6765\u6e90","text":"<p>https://pixso.cn/community/file/ItC5JH1TOwj15EeOPcY7LQ?from_share</p>"},{"location":"index.html#tkadw","title":"\u4e3a\u4ec0\u4e48\u4e0d\u50cf tkadw \u4e00\u6837\u505a\u8ddf\u6613\u7528\u7684\u4e3b\u9898\uff1f","text":"<p>\u56e0\u4e3a <code>svg</code> \u80fd\u5b9e\u73b0\u5f88\u591a\u6f02\u4eae\u7684\u7ec4\u4ef6\uff0c\u800c\u6211\u5957\u7684\u6a21\u677f\u53ef\u80fd\u4e0d\u5bf9\u5176\u5b83\u8bbe\u8ba1\u8d77\u592a\u5927\u7684\u4f5c\u7528\u3002</p> <p>\u6240\u4ee5\u6211\u5c06\u8fd9\u4e2a\u8bbe\u8ba1\u5e93\u653e\u5728\u8fd9\u91cc\u5f53\u505a\u6a21\u677f\uff0c\u4f9b\u5176\u5b83\u8bbe\u8ba1\u8005\u53c2\u8003\u4f7f\u7528\u3002</p>"},{"location":"index.html#_7","title":"\u66f4\u65b0\u65e5\u5fd7","text":""},{"location":"index.html#2024-01-22","title":"2024-01-22","text":"<p>\u53d1\u5e03<code>0.0.1</code>\u7248\u672c\uff0c\u6a21\u677f\u7ec4\u4ef6\u5305\u62ec<code>DButton</code></p>"},{"location":"index.html#2023-01-23","title":"2023-01-23","text":"<p>\u53d1\u5e03<code>0.0.2</code>\u7248\u672c\uff0c\u8865\u5145\u6a21\u677f\u7ec4\u4ef6<code>DEntry</code>\u3001<code>DFrame</code>\u3001<code>DText</code>, <code>DBadge</code></p>"},{"location":"index.html#2023-01-25","title":"2023-01-25","text":"<p>\u53d1\u5e03<code>0.0.3</code> <code>0.0.4</code>\u7248\u672c\uff0c\u7c97\u5fc3\u4e86\uff0c\u4e24\u6b21\u8865\u5145\u4f9d\u8d56 \u53d1\u5e03<code>0.0.5</code>\u7248\u672c\uff0c\u6a21\u677f\u7ec4\u4ef6\u4e3b\u9898\u7531<code>theme(mode=..., style=...)</code>\u8bbe\u7f6e\uff0c\u4e0d\u518d\u4f7f\u7528\u5982<code>DDarkButton</code>\u8fd9\u6837\u7684\uff0c\u6dfb\u52a0<code>DWindow.wincustom</code>\u81ea\u5b9a\u4e49\u7a97\u53e3\uff08\u4ec5\u9650Windows\uff09 \u53d1\u5e03<code>0.0.6</code>\u7248\u672c\uff0c\u6a21\u677f\u7ec4\u4ef6<code>DBadge</code>\u8865\u5145\u6837\u5f0f<code>style=accent</code>\uff0c\u5e76\u5bf9\u81ea\u5b9a\u4e49\u7a97\u53e3\u8fdb\u884c\u7a0d\u5fae\u8c03\u6574</p>"},{"location":"index.html#2023-01-26","title":"2023-01-26","text":"<p>\u53d1\u5e03<code>0.0.7</code>\u7248\u672c\uff0c\u6a21\u677f\u5e93<code>Fluent</code>\u5df2\u79fb\u81f3<code>tkfluent</code>\u5e93</p>"},{"location":"index.html#2024-09-16","title":"2024-09-16","text":"<p>\u53d1\u5e03<code>0.0.9</code>\u7248\u672c\uff0c\u4e00\u4e9b\u5c0f\u4fee\u6539</p>"},{"location":"index.html#2025-06-26","title":"2025-06-26","text":"<p>\u53d1\u5e03<code>0.1.0</code>\u7248\u672c\uff0c\u5b8c\u5584\u529f\u80fd</p>"},{"location":"index.html#2026-09-12","title":"2026-09-12","text":"<p>\u53d1\u5e03<code>0.2.0</code>\u7248\u672c\uff1a</p> <ul> <li>\u65b0\u589e <code>tkdeft.engines</code> \u7ed8\u5236\u5f15\u64ce\u5c42\uff0c\u53ef\u63d2\u62d4\u5207\u6362 <code>tksvg</code> / <code>wand</code> / <code>skia</code> / <code>pillow</code> / <code>cairo</code></li> <li>\u65b0\u589e\u8fdb\u7a0b\u5185\u6805\u683c\u5f15\u64ce\uff08skia-python / Pillow / pycairo\uff09\uff0c\u5b8c\u5168\u4e0d\u843d\u76d8</li> <li>\u65b0\u589e\u6309\u89c4\u683c\u7f13\u5b58\u7684\u56fe\u7247\u7f13\u5b58\uff0c\u53c2\u6570\u76f8\u540c\u7684\u7ed8\u5236\u7ed3\u679c\u76f4\u63a5\u590d\u7528</li> <li>\u65b0\u589e SVG \u5f62\u72b6\u52a9\u624b <code>tkdeft.svg</code>\uff0c\u7edf\u4e00\u5e76\u4fee\u6b63\u5706\u89d2\u77e9\u5f62\u51e0\u4f55</li> <li>\u4fee\u590d\u4e34\u65f6\u6587\u4ef6 / fd \u6cc4\u6f0f\u3001<code>PhotoImage</code> \u88ab GC \u5bfc\u81f4\u753b\u9762\u7a7a\u767d\u3001   <code>RenderManager</code> \u7684 <code>winfo_zorder</code> \u5d29\u6e83\u7b49\u95ee\u9898</li> <li>\u6587\u6863\u8865\u9f50\uff1a\u7ed8\u5236\u5f15\u64ce\u3001\u81ea\u5b9a\u4e49\u7ec4\u4ef6\u3001   API \u6587\u6863</li> </ul>"},{"location":"api/index.html","title":"API \u6587\u6863","text":"<p>\u672c\u9879\u76ee\u7684 API \u6587\u6863\u7531 <code>mkdocstrings</code> \u4ece\u6e90\u7801 \u81ea\u52a8\u751f\u6210\u2014\u2014\u9875\u9762\u4e0a\u770b\u5230\u7684\u5c31\u662f\u4ee3\u7801\u91cc\u7684\u6587\u6863\u5b57\u7b26\u4e32\u3002</p>"},{"location":"api/index.html#_1","title":"\u600e\u4e48\u8bfb","text":"<ul> <li>\u6807\u9898\u5f62\u5982 <code>tkdeft.engines \u00b7 \u7ed8\u5236\u5f15\u64ce\u5c42\u5165\u53e3</code>\uff0c\u6b63\u6587\u6309 \u6a21\u5757 \u2192 \u7c7b \u2192 \u65b9\u6cd5 \u5c55\u5f00\uff1b</li> <li>\u53f3\u4e0a\u89d2\u7684\u641c\u7d22\u6846\u652f\u6301\u8de8\u9875\u641c\u7d22\uff1b</li> <li>\u60f3\u76f4\u63a5\u770b\u5b9e\u73b0\u70b9\u5f00 <code>\u6e90\u7801</code> \u6298\u53e0\u5757\u3002</li> </ul>"},{"location":"api/index.html#_2","title":"\u5206\u7ec4","text":"\u5206\u7ec4 \u5185\u5bb9 \u7ed8\u5236\u5f15\u64ce \u5f15\u64ce\u6ce8\u518c\u8868\u3001\u89c4\u683c\u5bf9\u8c61\u3001\u7f13\u5b58\uff0c\u4ee5\u53ca\u4e09\u4e2a\u6805\u683c\u5f15\u64ce \u56fe\u5f62\u4e0e\u753b\u5e03 SVG \u5f62\u72b6\u52a9\u624b\u3001\u753b\u5e03\u3001\u7ed8\u5236\u540e\u7aef\u3001\u4ea4\u4e92\u63a7\u4ef6\u57fa\u7c7b \u57fa\u7840 <code>DObject</code> \u914d\u7f6e\u5bb9\u5668\u3001\u5b57\u4f53\u7b49\u5de5\u5177"},{"location":"api/index.html#_3","title":"\u76f8\u5173\u9605\u8bfb","text":"<ul> <li>\u7ed8\u5236\u5f15\u64ce \u2014\u2014 \u6982\u5ff5\u3001\u5207\u6362\u65b9\u5f0f\u3001\u7f13\u5b58\u7b56\u7565\u3001\u81ea\u5df1\u5199\u5f15\u64ce</li> <li>\u81ea\u5b9a\u4e49\u7ec4\u4ef6 \u2014\u2014 \u7528\u8fd9\u4e9b\u96f6\u4ef6\u642d\u4e00\u4e2a\u81ea\u5df1\u7684\u63a7\u4ef6</li> </ul>"},{"location":"api/tkdeft.engines.base.html","title":"engines.base \u00b7 \u5f15\u64ce\u57fa\u7c7b\u4e0e\u89c4\u683c","text":"<p>tkdeft \u7ed8\u5236\u5f15\u64ce\u62bd\u8c61\u5c42\u3002</p>"},{"location":"api/tkdeft.engines.base.html#tkdeft.engines.base--_1","title":"\u8bbe\u8ba1\u76ee\u6807","text":"<p>\u628a\"\u753b\u4ec0\u4e48\"\uff08\u58f0\u660e\u5f0f spec\uff09\u4e0e\"\u7528\u4ec0\u4e48\u753b\"\uff08\u5f15\u64ce\uff09\u5f7b\u5e95\u89e3\u8026\uff1a</p> <ul> <li>\u8fc7\u53bb\uff1a\u6bcf\u4e2a\u7ec4\u4ef6\u5728 <code>Flu*Draw</code> \u91cc\u5404\u81ea\u62fc svgwrite \u5bf9\u8c61 \u2192 \u843d\u76d8 \u2192 tksvg \u89e3\u6790\u6587\u4ef6\uff0c   \u5bfc\u81f4\u6bcf\u6b21 hover/\u6309\u538b\u90fd\u8981\u8d70\u4e00\u904d\u78c1\u76d8 I/O + XML \u89e3\u6790\uff0c\u5355\u5e27 ~5ms\u3002</li> <li>\u73b0\u5728\uff1a\u7ec4\u4ef6\u6784\u9020\u4e00\u4e2a\u4e0d\u53ef\u53d8\u7684 :class:<code>RoundRectSpec</code>\uff0c\u4ea4\u7ed9\u5f53\u524d\u5f15\u64ce\u3002   \u6805\u683c\u5f15\u64ce\uff08skia / pillow / cairo\uff09\u8fdb\u7a0b\u5185\u76f4\u63a5\u51fa\u4f4d\u56fe\uff0c\u4e0d\u78b0\u78c1\u76d8\uff1b   SVG \u5f15\u64ce\uff08tksvg / wand\uff09\u4fdd\u6301\u539f\u6709\u884c\u4e3a\uff0c\u5411\u540e\u517c\u5bb9\u3002</li> </ul> <p>\u5bf9\u5916\u53ea\u66b4\u9732\u4e09\u4e2a\u6e32\u67d3\u51fd\u6570\uff1a:func:<code>render_roundrect</code>\u3001:func:<code>render_track</code>\u3001 :func:<code>render_thumb</code>\uff0c\u5b83\u4eec\u7edf\u4e00\u8fd4\u56de <code>PhotoImage</code> \u6216 <code>None</code> \uff08<code>None</code> \u8868\u793a\"\u5f53\u524d\u5f15\u64ce\u4e0d\u652f\u6301\uff0c\u8bf7\u56de\u9000\u5230\u65e2\u6709 SVG \u8def\u5f84\"\uff09\u3002</p>"},{"location":"api/tkdeft.engines.base.html#tkdeft.engines.base.DrawEngine","title":"<code>DrawEngine</code>","text":"<p>\u7ed8\u5236\u5f15\u64ce\u57fa\u7c7b\u3002</p> <p>\u5b50\u7c7b\u9700\u8981\u58f0\u660e :attr:<code>name</code>\u3001:attr:<code>kind</code>\uff0c\u5e76\u5b9e\u73b0 :meth:<code>render_roundrect</code> \u7b49\u6e32\u67d3\u65b9\u6cd5\u3002<code>kind == \"raster\"</code> \u7684\u5f15\u64ce\u4f1a\u88ab tkfluent \u7528\u4f5c\u5feb\u901f\u8def\u5f84\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>class DrawEngine:\n    \"\"\"\u7ed8\u5236\u5f15\u64ce\u57fa\u7c7b\u3002\n\n    \u5b50\u7c7b\u9700\u8981\u58f0\u660e :attr:`name`\u3001:attr:`kind`\uff0c\u5e76\u5b9e\u73b0 :meth:`render_roundrect`\n    \u7b49\u6e32\u67d3\u65b9\u6cd5\u3002``kind == \"raster\"`` \u7684\u5f15\u64ce\u4f1a\u88ab tkfluent \u7528\u4f5c\u5feb\u901f\u8def\u5f84\u3002\n    \"\"\"\n\n    name: str = \"base\"\n    kind: str = \"svg\"  # \"svg\" | \"raster\"\n    #: \u4f9d\u8d56\u7684 Python \u6a21\u5757\u540d\uff0c\u4f9b :meth:`available` \u505a\u60f0\u6027\u63a2\u6d4b\n    requires: Tuple[str, ...] = ()\n    #: \u4eba\u7c7b\u53ef\u8bfb\u63cf\u8ff0\n    description: str = \"\"\n\n    # -- \u80fd\u529b\u63a2\u6d4b ---------------------------------------------------------\n    def available(self) -&gt; bool:\n        \"\"\"\u4f9d\u8d56\u662f\u5426\u53ef\u5bfc\u5165\u3002\"\"\"\n        import importlib.util\n\n        for mod in self.requires:\n            if importlib.util.find_spec(mod) is None:\n                return False\n        return True\n\n    @property\n    def is_raster(self) -&gt; bool:\n        return self.kind == \"raster\"\n\n    # -- \u6e32\u67d3\u63a5\u53e3\uff08\u6805\u683c\u5f15\u64ce\u5b9e\u73b0\uff09------------------------------------------\n    def render_roundrect(self, spec: RoundRectSpec):\n        \"\"\"\u8fd4\u56de ``PIL.Image.Image``\uff08RGBA\uff09\u3002\u4e0d\u652f\u6301\u65f6\u629b :class:`NotImplementedError`\u3002\"\"\"\n        raise NotImplementedError\n\n    def render_track(self, spec: TrackSpec):\n        raise NotImplementedError\n\n    def render_thumb(self, spec: ThumbSpec):\n        raise NotImplementedError\n\n    def close(self) -&gt; None:\n        \"\"\"\u91ca\u653e\u5f15\u64ce\u6301\u6709\u7684\u8d44\u6e90\uff08\u53ef\u9009\uff09\u3002\"\"\"\n\n    def __repr__(self) -&gt; str:  # pragma: no cover - \u8c03\u8bd5\u53cb\u597d\n        return f\"&lt;{type(self).__name__} name={self.name!r} kind={self.kind!r}&gt;\"\n</code></pre>"},{"location":"api/tkdeft.engines.base.html#tkdeft.engines.base.DrawEngine.available","title":"<code>available()</code>","text":"<p>\u4f9d\u8d56\u662f\u5426\u53ef\u5bfc\u5165\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>def available(self) -&gt; bool:\n    \"\"\"\u4f9d\u8d56\u662f\u5426\u53ef\u5bfc\u5165\u3002\"\"\"\n    import importlib.util\n\n    for mod in self.requires:\n        if importlib.util.find_spec(mod) is None:\n            return False\n    return True\n</code></pre>"},{"location":"api/tkdeft.engines.base.html#tkdeft.engines.base.DrawEngine.close","title":"<code>close()</code>","text":"<p>\u91ca\u653e\u5f15\u64ce\u6301\u6709\u7684\u8d44\u6e90\uff08\u53ef\u9009\uff09\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>def close(self) -&gt; None:\n    \"\"\"\u91ca\u653e\u5f15\u64ce\u6301\u6709\u7684\u8d44\u6e90\uff08\u53ef\u9009\uff09\u3002\"\"\"\n</code></pre>"},{"location":"api/tkdeft.engines.base.html#tkdeft.engines.base.DrawEngine.render_roundrect","title":"<code>render_roundrect(spec)</code>","text":"<p>\u8fd4\u56de <code>PIL.Image.Image</code>\uff08RGBA\uff09\u3002\u4e0d\u652f\u6301\u65f6\u629b :class:<code>NotImplementedError</code>\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>def render_roundrect(self, spec: RoundRectSpec):\n    \"\"\"\u8fd4\u56de ``PIL.Image.Image``\uff08RGBA\uff09\u3002\u4e0d\u652f\u6301\u65f6\u629b :class:`NotImplementedError`\u3002\"\"\"\n    raise NotImplementedError\n</code></pre>"},{"location":"api/tkdeft.engines.base.html#tkdeft.engines.base.RoundRectSpec","title":"<code>RoundRectSpec</code>  <code>dataclass</code>","text":"<p>\u4e00\u4e2a\u5706\u89d2\u77e9\u5f62\uff08\u53ef\u5e26\u7eaf\u8272/\u6e10\u53d8\u63cf\u8fb9\uff09\u7684\u5b8c\u6574\u63cf\u8ff0\u3002</p> <p>\u5750\u6807\u4e00\u5f8b\u4ee5\u81ea\u8eab\u5de6\u4e0a\u89d2\u4e3a <code>(0, 0)</code>\u2014\u2014\u8fd9\u6b63\u662f tkfluent \u5404\u7ec4\u4ef6 <code>create_round_rectangle</code> \u7684\u5b9e\u9645\u7528\u6cd5\uff0c\u56e0\u6b64\u53ef\u4f5c\u4e3a\u7f13\u5b58\u952e\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>@dataclass(frozen=True)\nclass RoundRectSpec:\n    \"\"\"\u4e00\u4e2a\u5706\u89d2\u77e9\u5f62\uff08\u53ef\u5e26\u7eaf\u8272/\u6e10\u53d8\u63cf\u8fb9\uff09\u7684\u5b8c\u6574\u63cf\u8ff0\u3002\n\n    \u5750\u6807\u4e00\u5f8b\u4ee5\u81ea\u8eab\u5de6\u4e0a\u89d2\u4e3a ``(0, 0)``\u2014\u2014\u8fd9\u6b63\u662f tkfluent \u5404\u7ec4\u4ef6\n    ``create_round_rectangle`` \u7684\u5b9e\u9645\u7528\u6cd5\uff0c\u56e0\u6b64\u53ef\u4f5c\u4e3a\u7f13\u5b58\u952e\u3002\n    \"\"\"\n\n    width: int\n    height: int\n    rx: float = 0.0\n    ry: Optional[float] = None\n    fill: Optional[str] = None\n    fill_opacity: float = 1.0\n    outline: Optional[str] = None\n    outline_opacity: float = 1.0\n    outline2: Optional[str] = None\n    outline2_opacity: float = 1.0\n    outline_width: float = 1.0\n    # \u6e10\u53d8\u63cf\u8fb9\u7684\u4e24\u4e2a stop \u4f4d\u7f6e\uff08\u4e0e\u65e2\u6709 svgwrite \u5b9e\u73b0\u4e00\u81f4\uff1a0.9 / 1.0\uff09\n    gradient_stop1: float = 0.9\n    gradient_stop2: float = 1.0\n\n    @property\n    def effective_ry(self) -&gt; float:\n        return self.rx if self.ry is None else self.ry\n</code></pre>"},{"location":"api/tkdeft.engines.base.html#tkdeft.engines.base.SvgEngine","title":"<code>SvgEngine</code>","text":"<p>               Bases: <code>DrawEngine</code></p> <p>SVG \u7cfb\u5f15\u64ce\u7684\u5360\u4f4d\u5b9e\u73b0\u3002</p> <p>\u5b83\u4eec\u4e0d\u53c2\u4e0e\u6805\u683c\u5feb\u901f\u8def\u5f84\u2014\u2014\u771f\u6b63\u7684\u7ed8\u5236\u4ecd\u7531 tkfluent \u5404\u7ec4\u4ef6\u91cc\u65e2\u6709\u7684 <code>Flu*Draw</code> \u4ee3\u7801\u5b8c\u6210\uff0c\u8fd9\u91cc\u53ea\u7528\u4e8e\u5728\u6ce8\u518c\u8868\u91cc\u8868\u8fbe\"\u5f53\u524d\u9009\u4e2d\u7684\u662f\u54ea\u4e2a\u5f15\u64ce\"\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>class SvgEngine(DrawEngine):\n    \"\"\"SVG \u7cfb\u5f15\u64ce\u7684\u5360\u4f4d\u5b9e\u73b0\u3002\n\n    \u5b83\u4eec\u4e0d\u53c2\u4e0e\u6805\u683c\u5feb\u901f\u8def\u5f84\u2014\u2014\u771f\u6b63\u7684\u7ed8\u5236\u4ecd\u7531 tkfluent \u5404\u7ec4\u4ef6\u91cc\u65e2\u6709\u7684\n    ``Flu*Draw`` \u4ee3\u7801\u5b8c\u6210\uff0c\u8fd9\u91cc\u53ea\u7528\u4e8e\u5728\u6ce8\u518c\u8868\u91cc\u8868\u8fbe\"\u5f53\u524d\u9009\u4e2d\u7684\u662f\u54ea\u4e2a\u5f15\u64ce\"\u3002\n    \"\"\"\n\n    kind = \"svg\"\n\n    def render_roundrect(self, spec):  # pragma: no cover - \u6709\u610f\u4e0d\u652f\u6301\n        raise NotImplementedError(\n            f\"{self.name} \u662f SVG \u5f15\u64ce\uff0c\u8bf7\u8d70\u65e2\u6709\u7684 svgwrite + tksvg \u8def\u5f84\"\n        )\n\n    render_track = render_roundrect\n    render_thumb = render_roundrect\n</code></pre>"},{"location":"api/tkdeft.engines.base.html#tkdeft.engines.base.ThumbSpec","title":"<code>ThumbSpec</code>  <code>dataclass</code>","text":"<p>\u6ed1\u5757\u7684\u5706\u5f62\u628a\u624b\uff1a\u5916\u5708\u6e10\u53d8\u4f2a\u9634\u5f71 + \u5916\u586b\u5145 + \u5185\u586b\u5145\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>@dataclass(frozen=True)\nclass ThumbSpec:\n    \"\"\"\u6ed1\u5757\u7684\u5706\u5f62\u628a\u624b\uff1a\u5916\u5708\u6e10\u53d8\u4f2a\u9634\u5f71 + \u5916\u586b\u5145 + \u5185\u586b\u5145\u3002\"\"\"\n\n    width: int\n    height: int\n    r1: float\n    r2: float\n    fill: Optional[str] = None\n    fill_opacity: float = 1.0\n    outline: Optional[str] = None\n    outline_opacity: float = 1.0\n    outline2: Optional[str] = None\n    outline2_opacity: float = 1.0\n    inner_fill: Optional[str] = None\n    inner_fill_opacity: float = 1.0\n</code></pre>"},{"location":"api/tkdeft.engines.base.html#tkdeft.engines.base.TrackSpec","title":"<code>TrackSpec</code>  <code>dataclass</code>","text":"<p>\u6ed1\u5757\u7684\u8fdb\u5ea6\u6761\u69fd\uff1a\u5de6\u534a\u6bb5\uff08\u5df2\u9009\u4e2d\uff09+ \u53f3\u534a\u6bb5\uff08\u672a\u9009\u4e2d\uff09\u4e24\u4e2a\u5706\u89d2\u77e9\u5f62\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>@dataclass(frozen=True)\nclass TrackSpec:\n    \"\"\"\u6ed1\u5757\u7684\u8fdb\u5ea6\u6761\u69fd\uff1a\u5de6\u534a\u6bb5\uff08\u5df2\u9009\u4e2d\uff09+ \u53f3\u534a\u6bb5\uff08\u672a\u9009\u4e2d\uff09\u4e24\u4e2a\u5706\u89d2\u77e9\u5f62\u3002\"\"\"\n\n    width: int\n    height: int\n    width2: float\n    radius: float = 3.0\n    track_fill: Optional[str] = None\n    track_opacity: float = 1.0\n    rail_fill: Optional[str] = None\n    rail_opacity: float = 1.0\n</code></pre>"},{"location":"api/tkdeft.engines.base.html#tkdeft.engines.base.get_engine","title":"<code>get_engine(name=None)</code>","text":"<p>\u6309\u540d\u5b57\u53d6\u5f15\u64ce\uff1b<code>None</code> \u8868\u793a\u5f53\u524d\u5f15\u64ce\u3002\u540d\u5b57\u672a\u77e5\u65f6\u56de\u9000\u5230\u5f53\u524d/\u9ed8\u8ba4\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>def get_engine(name: Optional[str] = None) -&gt; DrawEngine:\n    \"\"\"\u6309\u540d\u5b57\u53d6\u5f15\u64ce\uff1b``None`` \u8868\u793a\u5f53\u524d\u5f15\u64ce\u3002\u540d\u5b57\u672a\u77e5\u65f6\u56de\u9000\u5230\u5f53\u524d/\u9ed8\u8ba4\u3002\"\"\"\n    if name is None:\n        name = _CURRENT[\"name\"]\n    engine = _ENGINES.get(str(name).lower())\n    if engine is None:\n        engine = _ENGINES.get(_CURRENT[\"name\"])\n    if engine is None:  # \u7406\u8bba\u4e0a\u4e0d\u4f1a\u53d1\u751f\uff1a\u6ce8\u518c\u8868\u81f3\u5c11\u6709\u4e00\u4e2a\u9ed8\u8ba4\u5f15\u64ce\n        raise RuntimeError(\"tkdeft \u5f15\u64ce\u6ce8\u518c\u8868\u4e3a\u7a7a\uff0c\u65e0\u6cd5\u89e3\u6790\u7ed8\u5236\u5f15\u64ce\")\n    return engine\n</code></pre>"},{"location":"api/tkdeft.engines.base.html#tkdeft.engines.base.list_engines","title":"<code>list_engines()</code>","text":"<p>\u8fd4\u56de <code>{\u5f15\u64ce\u540d: \u662f\u5426\u53ef\u7528}</code>\uff08\u53ea\u5217\u4e3b\u540d\uff0c\u4e0d\u542b\u522b\u540d\uff09\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>def list_engines() -&gt; \"dict[str, bool]\":\n    \"\"\"\u8fd4\u56de ``{\u5f15\u64ce\u540d: \u662f\u5426\u53ef\u7528}``\uff08\u53ea\u5217\u4e3b\u540d\uff0c\u4e0d\u542b\u522b\u540d\uff09\u3002\"\"\"\n    seen = {}\n    for name, engine in _ENGINES.items():\n        if engine.name == name:\n            seen[name] = engine.available()\n    return seen\n</code></pre>"},{"location":"api/tkdeft.engines.base.html#tkdeft.engines.base.register_engine","title":"<code>register_engine(engine, *, aliases=(), default=False)</code>","text":"<p>\u628a\u4e00\u4e2a\u5f15\u64ce\u5b9e\u4f8b\u767b\u8bb0\u8fdb\u6ce8\u518c\u8868\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>def register_engine(engine: DrawEngine, *, aliases: Tuple[str, ...] = (),\n                    default: bool = False) -&gt; DrawEngine:\n    \"\"\"\u628a\u4e00\u4e2a\u5f15\u64ce\u5b9e\u4f8b\u767b\u8bb0\u8fdb\u6ce8\u518c\u8868\u3002\"\"\"\n    _ENGINES[engine.name] = engine\n    for alias in aliases:\n        _ENGINES[alias] = engine\n    if default or not _ENGINES:\n        _CURRENT[\"name\"] = engine.name\n    return engine\n</code></pre>"},{"location":"api/tkdeft.engines.base.html#tkdeft.engines.base.set_engine","title":"<code>set_engine(name)</code>","text":"<p>\u5207\u6362\u5f53\u524d\u5f15\u64ce\u3002</p> <p><code>name</code> \u53ef\u4ee5\u662f\u5f15\u64ce\u540d\uff08<code>\"skia\"</code> / <code>\"pillow\"</code> / <code>\"tksvg\"</code> / <code>\"cairo\"</code> / <code>\"wand\"</code>\uff09\uff0c\u4e5f\u53ef\u4ee5\u662f\u517c\u5bb9\u65e7 API \u7684\u6574\u6570\u7f16\u53f7\uff1a</p> <p>===== ========== \u7f16\u53f7   \u5f15\u64ce ===== ========== 0     tksvg\uff08\u9ed8\u8ba4\uff0cSVG \u6587\u4ef6\uff09 1     wand\uff08SVG \u2192 PNG\uff09 2     skia\uff08\u8fdb\u7a0b\u5185\u6805\u683c\uff09 3     pillow\uff08\u8fdb\u7a0b\u5185\u6805\u683c\uff0c\u65e0\u989d\u5916\u4f9d\u8d56\uff09 4     cairo\uff08\u8fdb\u7a0b\u5185\u6805\u683c\uff09 ===== ==========</p> <p>\u975e\u6cd5\u6216\u4e0d\u53ef\u7528\u7684\u5f15\u64ce\u4f1a\u629b\u51fa :class:<code>ValueError</code>\uff0c\u907f\u514d\u9759\u9ed8\u964d\u7ea7\u5bfc\u81f4 \"\u4ee5\u4e3a\u5f00\u4e86 skia \u5176\u5b9e\u8fd8\u5728\u8d70\u6162\u8def\u5f84\"\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>def set_engine(name) -&gt; DrawEngine:\n    \"\"\"\u5207\u6362\u5f53\u524d\u5f15\u64ce\u3002\n\n    ``name`` \u53ef\u4ee5\u662f\u5f15\u64ce\u540d\uff08``\"skia\"`` / ``\"pillow\"`` / ``\"tksvg\"`` / ``\"cairo\"``\n    / ``\"wand\"``\uff09\uff0c\u4e5f\u53ef\u4ee5\u662f\u517c\u5bb9\u65e7 API \u7684\u6574\u6570\u7f16\u53f7\uff1a\n\n    ===== ==========\n    \u7f16\u53f7   \u5f15\u64ce\n    ===== ==========\n    0     tksvg\uff08\u9ed8\u8ba4\uff0cSVG \u6587\u4ef6\uff09\n    1     wand\uff08SVG \u2192 PNG\uff09\n    2     skia\uff08\u8fdb\u7a0b\u5185\u6805\u683c\uff09\n    3     pillow\uff08\u8fdb\u7a0b\u5185\u6805\u683c\uff0c\u65e0\u989d\u5916\u4f9d\u8d56\uff09\n    4     cairo\uff08\u8fdb\u7a0b\u5185\u6805\u683c\uff09\n    ===== ==========\n\n    \u975e\u6cd5\u6216\u4e0d\u53ef\u7528\u7684\u5f15\u64ce\u4f1a\u629b\u51fa :class:`ValueError`\uff0c\u907f\u514d\u9759\u9ed8\u964d\u7ea7\u5bfc\u81f4\n    \"\u4ee5\u4e3a\u5f00\u4e86 skia \u5176\u5b9e\u8fd8\u5728\u8d70\u6162\u8def\u5f84\"\u3002\n    \"\"\"\n    engine = _ENGINES.get(str(name).lower())\n    if engine is None:\n        raise ValueError(\n            f\"\u672a\u77e5\u7684\u7ed8\u5236\u5f15\u64ce {name!r}\uff1b\u53ef\u7528\uff1a{sorted(list_engines())}\"\n        )\n    if not engine.available():\n        raise ValueError(\n            f\"\u7ed8\u5236\u5f15\u64ce {engine.name!r} \u4e0d\u53ef\u7528\uff0c\u7f3a\u5c11\u4f9d\u8d56\uff1a{engine.requires}\"\n        )\n    _CURRENT[\"name\"] = engine.name\n    return engine\n</code></pre>"},{"location":"api/tkdeft.engines.cache.html","title":"engines.cache \u00b7 \u56fe\u7247\u7f13\u5b58","text":"<p>\u7ed8\u5236\u7ed3\u679c\u7f13\u5b58\u3002</p>"},{"location":"api/tkdeft.engines.cache.html#tkdeft.engines.cache--_1","title":"\u4e3a\u4ec0\u4e48\u9700\u8981","text":"<p>tkfluent \u7684\u4e00\u6b21 hover \u4f1a\u8ba9\u540c\u4e00\u4e2a <code>RoundRectSpec</code> \u88ab\u53cd\u590d\u7ed8\u5236\uff08rest\u2192hover \u7684 \u6e10\u53d8\u52a8\u753b\u6700\u591a\u51e0\u5341\u5e27\uff0c\u591a\u4e2a\u540c\u5c3a\u5bf8\u6309\u94ae\u66f4\u662f\u5b8c\u5168\u540c\u53c2\uff09\u3002\u6ca1\u6709\u7f13\u5b58\u65f6\u6bcf\u6b21\u90fd\u8981\u91cd\u65b0 \u5149\u6805\u5316\u5e76\u65b0\u5efa <code>PhotoImage</code>\u2014\u2014\u5b9e\u6d4b\u8fd9\u6b63\u662f\u7aef\u5230\u7aef\u8017\u65f6\u7684\u5927\u5934\u3002</p>"},{"location":"api/tkdeft.engines.cache.html#tkdeft.engines.cache--_2","title":"\u7f13\u5b58\u952e","text":"<p><code>(\u5f15\u64ce\u540d, spec)</code>\u3002spec \u662f <code>frozen dataclass</code>\uff0c\u5929\u7136\u53ef\u54c8\u5e0c\u3002</p>"},{"location":"api/tkdeft.engines.cache.html#tkdeft.engines.cache--_3","title":"\u751f\u547d\u5468\u671f\u4e0e\"\u7a7a\u56fe\"\u9677\u9631","text":"<p><code>PhotoImage</code> \u7ed1\u5b9a\u5728\u5177\u4f53\u7684 Tk \u89e3\u91ca\u5668\u4e0a\uff0c\u4e14 \u4e00\u65e6\u88ab\u5783\u573e\u56de\u6536\uff0c\u5f15\u7528\u5b83\u7684 canvas item \u4f1a\u53d8\u6210\u7a7a\u767d\u3002\u56e0\u6b64\u8fd9\u91cc\u523b\u610f \u4e0d\u505a LRU \u6dd8\u6c70\uff0c\u800c\u662f\u91c7\u7528 \"\u50cf\u7d20\u9884\u7b97 + \u6ee1\u4e86\u5c31\u4e0d\u518d\u5199\u5165\"\u7684\u7b56\u7565\uff1a\u5df2\u7ecf\u53d1\u51fa\u53bb\u7684\u56fe\u7247\u6c38\u8fdc\u4fdd\u6301\u5b58\u6d3b\uff0c \u65b0\u7684\u3001\u7f13\u5b58\u4e0d\u4e0b\u7684\u89c4\u683c\u5c31\u9000\u5316\u4e3a\"\u6bcf\u6b21\u90fd\u91cd\u65b0\u6e32\u67d3\"\u2014\u2014\u53ea\u635f\u5931\u901f\u5ea6\uff0c\u7edd\u4e0d\u635f\u574f\u753b\u9762\u3002</p> <p>\u89e3\u91ca\u5668\u7528 <code>id()</code> \u4f5c\u952e\uff08<code>_tkinter.tkapp</code> \u4e0d\u652f\u6301 weakref\uff09\uff0c\u5e76\u7528\u5bf9\u8c61\u540c\u4e00\u6027 \u6821\u9a8c\uff0c\u907f\u514d id \u590d\u7528\u5bfc\u81f4\u7684\u4e32\u53f0\u3002</p>"},{"location":"api/tkdeft.engines.cache.html#tkdeft.engines.cache.ImageCache","title":"<code>ImageCache</code>","text":"<p>\u5355\u4e2a Tk \u89e3\u91ca\u5668\u5bf9\u5e94\u7684\u7ed8\u5236\u7ed3\u679c\u7f13\u5b58\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\cache.py</code> <pre><code>class ImageCache:\n    \"\"\"\u5355\u4e2a Tk \u89e3\u91ca\u5668\u5bf9\u5e94\u7684\u7ed8\u5236\u7ed3\u679c\u7f13\u5b58\u3002\"\"\"\n\n    __slots__ = (\"_entries\", \"_pixels\", \"_budget\", \"_hits\", \"_misses\", \"_overflow\")\n\n    def __init__(self, budget: int = DEFAULT_PIXEL_BUDGET) -&gt; None:\n        self._entries: \"OrderedDict[Any, Tuple[Any, int]]\" = OrderedDict()\n        self._pixels = 0\n        self._budget = budget\n        self._hits = 0\n        self._misses = 0\n        self._overflow = 0\n\n    # -- \u67e5\u8be2 -------------------------------------------------------------\n    def get(self, key: Any):\n        item = self._entries.get(key)\n        if item is None:\n            self._misses += 1\n            return None\n        self._hits += 1\n        self._entries.move_to_end(key)\n        return item[0]\n\n    # -- \u5199\u5165 -------------------------------------------------------------\n    def put(self, key: Any, photo, pixels: int) -&gt; bool:\n        \"\"\"\u5199\u5165\u7f13\u5b58\uff1b\u8d85\u51fa\u9884\u7b97\u65f6 **\u9759\u9ed8\u653e\u5f03**\uff08\u5df2\u53d1\u51fa\u7684\u56fe\u7247\u4fdd\u6301\u6709\u6548\uff09\u3002\n\n        \u8fd4\u56de\u662f\u5426\u771f\u7684\u5199\u5165\u4e86\u7f13\u5b58\u3002\n        \"\"\"\n        if key in self._entries:\n            return True\n        if self._pixels + pixels &gt; self._budget:\n            self._overflow += 1\n            return False\n        self._entries[key] = (photo, pixels)\n        self._pixels += pixels\n        return True\n\n    # -- \u7ef4\u62a4 -------------------------------------------------------------\n    def clear(self) -&gt; int:\n        count = len(self._entries)\n        self._entries.clear()\n        self._pixels = 0\n        return count\n\n    @property\n    def budget(self) -&gt; int:\n        return self._budget\n\n    @budget.setter\n    def budget(self, value: int) -&gt; None:\n        self._budget = max(0, int(value))\n\n    def stats(self) -&gt; Dict[str, Any]:\n        total = self._hits + self._misses\n        return {\n            \"entries\": len(self._entries),\n            \"pixels\": self._pixels,\n            \"budget\": self._budget,\n            \"hits\": self._hits,\n            \"misses\": self._misses,\n            \"hit_rate\": (self._hits / total) if total else 0.0,\n            \"overflow\": self._overflow,\n        }\n\n    def reset_stats(self) -&gt; None:\n        self._hits = self._misses = self._overflow = 0\n</code></pre>"},{"location":"api/tkdeft.engines.cache.html#tkdeft.engines.cache.ImageCache.put","title":"<code>put(key, photo, pixels)</code>","text":"<p>\u5199\u5165\u7f13\u5b58\uff1b\u8d85\u51fa\u9884\u7b97\u65f6 \u9759\u9ed8\u653e\u5f03\uff08\u5df2\u53d1\u51fa\u7684\u56fe\u7247\u4fdd\u6301\u6709\u6548\uff09\u3002</p> <p>\u8fd4\u56de\u662f\u5426\u771f\u7684\u5199\u5165\u4e86\u7f13\u5b58\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\cache.py</code> <pre><code>def put(self, key: Any, photo, pixels: int) -&gt; bool:\n    \"\"\"\u5199\u5165\u7f13\u5b58\uff1b\u8d85\u51fa\u9884\u7b97\u65f6 **\u9759\u9ed8\u653e\u5f03**\uff08\u5df2\u53d1\u51fa\u7684\u56fe\u7247\u4fdd\u6301\u6709\u6548\uff09\u3002\n\n    \u8fd4\u56de\u662f\u5426\u771f\u7684\u5199\u5165\u4e86\u7f13\u5b58\u3002\n    \"\"\"\n    if key in self._entries:\n        return True\n    if self._pixels + pixels &gt; self._budget:\n        self._overflow += 1\n        return False\n    self._entries[key] = (photo, pixels)\n    self._pixels += pixels\n    return True\n</code></pre>"},{"location":"api/tkdeft.engines.cache.html#tkdeft.engines.cache.cache_stats","title":"<code>cache_stats(master=None)</code>","text":"<p>\u7f13\u5b58\u7edf\u8ba1\uff0c\u4fbf\u4e8e\u6027\u80fd\u8bca\u65ad\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\cache.py</code> <pre><code>def cache_stats(master=None) -&gt; Dict[str, Any]:\n    \"\"\"\u7f13\u5b58\u7edf\u8ba1\uff0c\u4fbf\u4e8e\u6027\u80fd\u8bca\u65ad\u3002\"\"\"\n    with _LOCK:\n        if master is not None:\n            return _cache_for(master).stats()\n        merged: Dict[str, Any] = {\n            \"interpreters\": len(_CACHES),\n            \"entries\": 0,\n            \"pixels\": 0,\n            \"budget\": _PIXEL_BUDGET,\n            \"hits\": 0,\n            \"misses\": 0,\n            \"overflow\": 0,\n        }\n        for _, cache in _CACHES.values():\n            stats = cache.stats()\n            for field in (\"entries\", \"pixels\", \"hits\", \"misses\", \"overflow\"):\n                merged[field] += stats[field]\n        total = merged[\"hits\"] + merged[\"misses\"]\n        merged[\"hit_rate\"] = (merged[\"hits\"] / total) if total else 0.0\n        return merged\n</code></pre>"},{"location":"api/tkdeft.engines.cache.html#tkdeft.engines.cache.clear_cache","title":"<code>clear_cache(master=None)</code>","text":"<p>\u6e05\u7a7a\u7f13\u5b58\u3002<code>master=None</code> \u65f6\u6e05\u7a7a\u5168\u90e8\u89e3\u91ca\u5668\u3002</p> <p>.. warning::    \u6e05\u7a7a\u540e\uff0c\u4ecd\u7136\u5b58\u5728\u4e8e\u753b\u5e03\u4e0a\u7684 item \u4f1a\u56e0\u4e3a\u56fe\u7247\u88ab\u56de\u6536\u800c\u53d8\u7a7a\u767d\u3002    \u4ec5\u5728\u786e\u5b9e\u8981\u91cd\u5efa\u6574\u4e2a\u754c\u9762\u65f6\u8c03\u7528\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\cache.py</code> <pre><code>def clear_cache(master=None) -&gt; int:\n    \"\"\"\u6e05\u7a7a\u7f13\u5b58\u3002``master=None`` \u65f6\u6e05\u7a7a\u5168\u90e8\u89e3\u91ca\u5668\u3002\n\n    .. warning::\n       \u6e05\u7a7a\u540e\uff0c\u4ecd\u7136\u5b58\u5728\u4e8e\u753b\u5e03\u4e0a\u7684 item \u4f1a\u56e0\u4e3a\u56fe\u7247\u88ab\u56de\u6536\u800c\u53d8\u7a7a\u767d\u3002\n       \u4ec5\u5728\u786e\u5b9e\u8981\u91cd\u5efa\u6574\u4e2a\u754c\u9762\u65f6\u8c03\u7528\u3002\n    \"\"\"\n    with _LOCK:\n        if master is None:\n            total = sum(cache.clear() for _, cache in _CACHES.values())\n            _CACHES.clear()\n            return total\n        return _cache_for(master).clear()\n</code></pre>"},{"location":"api/tkdeft.engines.cache.html#tkdeft.engines.cache.get_cache","title":"<code>get_cache(master)</code>","text":"<p>\u53d6\uff08\u5fc5\u8981\u65f6\u521b\u5efa\uff09\u67d0\u4e2a Tk \u89e3\u91ca\u5668\u5bf9\u5e94\u7684\u7f13\u5b58\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\cache.py</code> <pre><code>def get_cache(master) -&gt; ImageCache:\n    \"\"\"\u53d6\uff08\u5fc5\u8981\u65f6\u521b\u5efa\uff09\u67d0\u4e2a Tk \u89e3\u91ca\u5668\u5bf9\u5e94\u7684\u7f13\u5b58\u3002\"\"\"\n    return _cache_for(master)\n</code></pre>"},{"location":"api/tkdeft.engines.cache.html#tkdeft.engines.cache.set_cache_budget","title":"<code>set_cache_budget(pixels)</code>","text":"<p>\u8bbe\u7f6e\u50cf\u7d20\u9884\u7b97\uff08<code>None</code> \u8868\u793a\u4e0d\u9650\u5236\uff09\u3002\u5e94\u7528\u4e8e\u6240\u6709\u89e3\u91ca\u5668\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\cache.py</code> <pre><code>def set_cache_budget(pixels: Optional[int]) -&gt; None:\n    \"\"\"\u8bbe\u7f6e\u50cf\u7d20\u9884\u7b97\uff08``None`` \u8868\u793a\u4e0d\u9650\u5236\uff09\u3002\u5e94\u7528\u4e8e\u6240\u6709\u89e3\u91ca\u5668\u3002\"\"\"\n    global _PIXEL_BUDGET\n    with _LOCK:\n        _PIXEL_BUDGET = DEFAULT_PIXEL_BUDGET if pixels is None else max(0, int(pixels))\n        for _, cache in _CACHES.values():\n            cache.budget = _PIXEL_BUDGET\n</code></pre>"},{"location":"api/tkdeft.engines.cairo_engine.html","title":"engines.cairo \u00b7 Cairo \u5f15\u64ce","text":"<p>Cairo \u7ed8\u5236\u5f15\u64ce\uff08pycairo\uff0c\u8fdb\u7a0b\u5185\u6805\u683c\u5316\uff09\u3002</p> <p>\u7b2c\u4e09\u4e2a\u6805\u683c\u540e\u7aef\uff0c\u7528\u4e8e\u9a8c\u8bc1\u5f15\u64ce\u5c42\u7684\u53ef\u63d2\u62d4\u6027\uff1a\u6362\u6210 pycairo \u65f6\u4e0a\u5c42\u7ec4\u4ef6\u4ee3\u7801 \u4e00\u884c\u90fd\u4e0d\u7528\u6539\u3002cairo \u7684 <code>ImageSurface(FORMAT_ARGB32)</code> \u5728\u5c0f\u7aef\u673a\u5668\u4e0a\u5185\u5b58\u5e03\u5c40 \u662f \u9884\u4e58\u7684 BGRA\uff0c\u56e0\u6b64\u8fd9\u91cc\u9700\u8981\u8fd8\u539f\u9884\u4e58\u518d\u4ea4\u7ed9 Pillow\u3002</p> <p>cairo \u6ca1\u6709\u539f\u751f\u7684\u5706\u89d2\u77e9\u5f62\uff0c\u8fd9\u91cc\u7528\u56db\u6bb5\u4e09\u6b21\u8d1d\u585e\u5c14\u6784\u9020\u692d\u5706\u5706\u89d2 \uff08<code>kappa = 0.5522847498</code>\uff09\uff0c\u4e0e SVG \u7684 <code>rx</code> / <code>ry</code> \u8bed\u4e49\u4e00\u81f4\u3002</p>"},{"location":"api/tkdeft.engines.cairo_engine.html#tkdeft.engines.cairo_engine.CairoEngine","title":"<code>CairoEngine</code>","text":"<p>               Bases: <code>DrawEngine</code></p> <p>\u57fa\u4e8e pycairo \u7684\u8fdb\u7a0b\u5185\u6805\u683c\u5f15\u64ce\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\cairo_engine.py</code> <pre><code>class CairoEngine(DrawEngine):\n    \"\"\"\u57fa\u4e8e pycairo \u7684\u8fdb\u7a0b\u5185\u6805\u683c\u5f15\u64ce\u3002\"\"\"\n\n    name = \"cairo\"\n    kind = \"raster\"\n    requires = (\"cairo\", \"numpy\", \"PIL\")\n    description = \"pycairo \u8fdb\u7a0b\u5185\u6805\u683c\u5316\uff08\u539f\u751f\u6297\u952f\u9f7f\uff09\"\n\n    # ------------------------------------------------------------------\n    @staticmethod\n    def _new_surface(width: int, height: int):\n        import cairo\n\n        surface = cairo.ImageSurface(cairo.FORMAT_ARGB32, width, height)\n        ctx = cairo.Context(surface)\n        ctx.set_operator(cairo.OPERATOR_SOURCE)\n        ctx.set_source_rgba(0, 0, 0, 0)\n        ctx.paint()\n        ctx.set_operator(cairo.OPERATOR_OVER)\n        ctx.set_antialias(cairo.ANTIALIAS_DEFAULT)\n        return surface, ctx\n\n    @staticmethod\n    def _to_pil(surface, width: int, height: int):\n        \"\"\"ARGB32\uff08\u9884\u4e58 BGRA\uff09\u2192 \u975e\u9884\u4e58 RGBA \u7684 ``PIL.Image``\u3002\"\"\"\n        import numpy as np\n        from PIL import Image\n\n        surface.flush()\n        stride = surface.get_stride()\n        raw = np.frombuffer(\n            surface.get_data(), dtype=np.uint8, count=stride * height\n        ).reshape(height, stride)\n        arr = raw[:, : width * 4].reshape(height, width, 4)\n\n        alpha = arr[:, :, 3].astype(np.float64)\n        with np.errstate(divide=\"ignore\", invalid=\"ignore\"):\n            scale = np.where(alpha &gt; 0, 255.0 / np.maximum(alpha, 1.0), 0.0)\n        # \u4e09\u4e2a\u901a\u9053\u90fd\u5fc5\u987b\u4e58\u4e0a scale \u624d\u80fd\u8fd8\u539f\u9884\u4e58\uff1b\u6f0f\u6389\u4efb\u4f55\u4e00\u4e2a\u90fd\u4f1a\u8ba9\u534a\u900f\u660e\u5f69\u8272\n        # \u50cf\u7d20\u504f\u8272\uff08\u66fe\u7ecf\u6f0f\u6389 G\uff0c\u5bfc\u81f4\u9ed1\u8272 20% \u63cf\u8fb9\u6e32\u67d3\u6210\u6d0b\u7ea2\u8272\uff09\u3002\n        out = np.empty((height, width, 4), dtype=np.uint8)\n        out[:, :, 0] = np.clip(arr[:, :, 2] * scale, 0, 255)  # R \u2190 B\n        out[:, :, 1] = np.clip(arr[:, :, 1] * scale, 0, 255)  # G\n        out[:, :, 2] = np.clip(arr[:, :, 0] * scale, 0, 255)  # B \u2190 R\n        out[:, :, 3] = arr[:, :, 3]\n        return Image.fromarray(out, \"RGBA\")\n\n    @staticmethod\n    def _set_color(ctx, rgba):\n        ctx.set_source_rgba(\n            rgba[0] / 255.0, rgba[1] / 255.0, rgba[2] / 255.0, rgba[3] / 255.0\n        )\n\n    # ------------------------------------------------------------------\n    def render_roundrect(self, spec: RoundRectSpec):\n        width = max(1, int(round(spec.width)))\n        height = max(1, int(round(spec.height)))\n        surface, ctx = self._new_surface(width, height)\n\n        stroke_width = float(spec.outline_width or 0.0)\n        inset = stroke_width / 2.0 if stroke_width &gt; 0 else 0.0\n        rx = max(0.0, float(spec.rx) - inset)\n        ry = max(0.0, float(spec.effective_ry) - inset)\n        x0, y0 = inset, inset\n        w = max(1.0, width - 2 * inset)\n        h = max(1.0, height - 2 * inset)\n\n        fill = parse_color(spec.fill, spec.fill_opacity)\n        if fill:\n            _rounded_rect_path(ctx, x0, y0, w, h, rx, ry)\n            self._set_color(ctx, fill)\n            ctx.fill()\n\n        if stroke_width &gt; 0:\n            outline = parse_color(spec.outline, spec.outline_opacity)\n            outline2 = (\n                parse_color(spec.outline2, spec.outline2_opacity)\n                if spec.outline2\n                else None\n            )\n            if outline:\n                if outline2 and outline2 != outline:\n                    import cairo\n\n                    gradient = cairo.LinearGradient(x0, y0, x0, y0 + h)\n                    gradient.add_color_stop_rgba(\n                        float(spec.gradient_stop1),\n                        outline[0] / 255.0, outline[1] / 255.0,\n                        outline[2] / 255.0, outline[3] / 255.0,\n                    )\n                    gradient.add_color_stop_rgba(\n                        float(spec.gradient_stop2),\n                        outline2[0] / 255.0, outline2[1] / 255.0,\n                        outline2[2] / 255.0, outline2[3] / 255.0,\n                    )\n                    ctx.set_source(gradient)\n                else:\n                    self._set_color(ctx, outline)\n                _rounded_rect_path(ctx, x0, y0, w, h, rx, ry)\n                ctx.set_line_width(stroke_width)\n                ctx.stroke()\n\n        return self._to_pil(surface, width, height)\n\n    # ------------------------------------------------------------------\n    def render_track(self, spec: TrackSpec):\n        width = max(1, int(round(spec.width)))\n        height = max(1, int(round(spec.height)))\n        surface, ctx = self._new_surface(width, height)\n        radius = max(0.0, float(spec.radius))\n        left = max(0.0, min(float(spec.width2), float(width)))\n\n        track = parse_color(spec.track_fill, spec.track_opacity)\n        if track and left &gt; 0:\n            _rounded_rect_path(ctx, 0, 0, left, height, radius, radius)\n            self._set_color(ctx, track)\n            ctx.fill()\n\n        rail = parse_color(spec.rail_fill, spec.rail_opacity)\n        if rail and width - left &gt; 0:\n            _rounded_rect_path(ctx, left, 0, width - left, height, radius, radius)\n            self._set_color(ctx, rail)\n            ctx.fill()\n\n        return self._to_pil(surface, width, height)\n\n    # ------------------------------------------------------------------\n    def render_thumb(self, spec: ThumbSpec):\n        width = max(1, int(round(spec.width)))\n        height = max(1, int(round(spec.height)))\n        surface, ctx = self._new_surface(width, height)\n        cx, cy = width / 2.0, height / 2.0\n        r1, r2 = float(spec.r1), float(spec.r2)\n\n        outline = parse_color(spec.outline, spec.outline_opacity)\n        outline2 = (\n            parse_color(spec.outline2, spec.outline2_opacity)\n            if spec.outline2\n            else None\n        )\n        if outline:\n            import cairo\n\n            if outline2 and outline2 != outline:\n                gradient = cairo.LinearGradient(\n                    r1, 1.0, r1, max(1.0, r1 * 2.0 - 1.0)\n                )\n                gradient.add_color_stop_rgba(\n                    0.500208,\n                    outline[0] / 255.0, outline[1] / 255.0,\n                    outline[2] / 255.0, outline[3] / 255.0,\n                )\n                gradient.add_color_stop_rgba(\n                    0.954545,\n                    outline2[0] / 255.0, outline2[1] / 255.0,\n                    outline2[2] / 255.0, outline2[3] / 255.0,\n                )\n                ctx.set_source(gradient)\n            else:\n                self._set_color(ctx, outline)\n            ctx.arc(cx, cy, r1, 0, 2 * math.pi)\n            ctx.fill()\n\n        fill = parse_color(spec.fill, spec.fill_opacity)\n        if fill:\n            self._set_color(ctx, fill)\n            ctx.arc(cx, cy, max(0.0, r1 - 1.0), 0, 2 * math.pi)\n            ctx.fill()\n\n        inner = parse_color(spec.inner_fill, spec.inner_fill_opacity)\n        if inner:\n            self._set_color(ctx, inner)\n            ctx.arc(cx, cy, r2, 0, 2 * math.pi)\n            ctx.fill()\n\n        return self._to_pil(surface, width, height)\n</code></pre>"},{"location":"api/tkdeft.engines.html","title":"engines \u00b7 \u7ed8\u5236\u5f15\u64ce\u5c42\u5165\u53e3","text":"<p>tkdeft \u7ed8\u5236\u5f15\u64ce\u5c42\u3002</p>"},{"location":"api/tkdeft.engines.html#tkdeft.engines--_1","title":"\u5bf9\u5916\u4e3b\u8981\u63a5\u53e3","text":"<p>::</p> <pre><code>from tkdeft.engines import set_engine, get_engine, render_roundrect, cache_stats\n\nset_engine(\"skia\")          # \u6216 set_engine(2)\nphoto = render_roundrect(spec, master=canvas)   # -&gt; PhotoImage | None\n</code></pre> <p><code>render_*</code> \u8fd4\u56de <code>None</code> \u8868\u793a\"\u5f53\u524d\u5f15\u64ce\u4e0d\u53c2\u4e0e\u8fd9\u6761\u8def\u5f84\"\uff0c\u8c03\u7528\u65b9\u5e94\u56de\u9000\u5230 \u65e2\u6709\u7684 svgwrite + tksvg \u5b9e\u73b0\u3002\u8fd9\u6837 SVG \u5f15\u64ce\u4e0e\u6805\u683c\u5f15\u64ce\u53ef\u4ee5\u5171\u5b58\u4e8e\u540c\u4e00\u5957\u7ec4\u4ef6\u4ee3\u7801\u3002</p>"},{"location":"api/tkdeft.engines.html#tkdeft.engines--_2","title":"\u5185\u7f6e\u5f15\u64ce","text":"<p>====== ========== ================================================== \u540d\u5b57    \u7c7b\u578b        \u8bf4\u660e ====== ========== ================================================== tksvg  SVG\uff08\u6587\u4ef6\uff09 \u9ed8\u8ba4\uff0c\u4fdd\u6301\u65e2\u6709\u884c\u4e3a\u5b8c\u5168\u4e0d\u53d8 wand   SVG\uff08\u6587\u4ef6\uff09 \u7ecf Wand \u8f6c PNG\uff0c\u517c\u5bb9\u65e7 <code>renderer=1</code> skia   \u6805\u683c        skia-python\uff0c\u8d28\u91cf\u4e0e\u901f\u5ea6\u6700\u597d pillow \u6805\u683c        Pillow \u8d85\u91c7\u6837\uff0c\u96f6\u989d\u5916\u4f9d\u8d56\uff0c\u6c38\u8fdc\u53ef\u7528 cairo  \u6805\u683c        pycairo ====== ========== ==================================================</p>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.DrawEngine","title":"<code>DrawEngine</code>","text":"<p>\u7ed8\u5236\u5f15\u64ce\u57fa\u7c7b\u3002</p> <p>\u5b50\u7c7b\u9700\u8981\u58f0\u660e :attr:<code>name</code>\u3001:attr:<code>kind</code>\uff0c\u5e76\u5b9e\u73b0 :meth:<code>render_roundrect</code> \u7b49\u6e32\u67d3\u65b9\u6cd5\u3002<code>kind == \"raster\"</code> \u7684\u5f15\u64ce\u4f1a\u88ab tkfluent \u7528\u4f5c\u5feb\u901f\u8def\u5f84\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>class DrawEngine:\n    \"\"\"\u7ed8\u5236\u5f15\u64ce\u57fa\u7c7b\u3002\n\n    \u5b50\u7c7b\u9700\u8981\u58f0\u660e :attr:`name`\u3001:attr:`kind`\uff0c\u5e76\u5b9e\u73b0 :meth:`render_roundrect`\n    \u7b49\u6e32\u67d3\u65b9\u6cd5\u3002``kind == \"raster\"`` \u7684\u5f15\u64ce\u4f1a\u88ab tkfluent \u7528\u4f5c\u5feb\u901f\u8def\u5f84\u3002\n    \"\"\"\n\n    name: str = \"base\"\n    kind: str = \"svg\"  # \"svg\" | \"raster\"\n    #: \u4f9d\u8d56\u7684 Python \u6a21\u5757\u540d\uff0c\u4f9b :meth:`available` \u505a\u60f0\u6027\u63a2\u6d4b\n    requires: Tuple[str, ...] = ()\n    #: \u4eba\u7c7b\u53ef\u8bfb\u63cf\u8ff0\n    description: str = \"\"\n\n    # -- \u80fd\u529b\u63a2\u6d4b ---------------------------------------------------------\n    def available(self) -&gt; bool:\n        \"\"\"\u4f9d\u8d56\u662f\u5426\u53ef\u5bfc\u5165\u3002\"\"\"\n        import importlib.util\n\n        for mod in self.requires:\n            if importlib.util.find_spec(mod) is None:\n                return False\n        return True\n\n    @property\n    def is_raster(self) -&gt; bool:\n        return self.kind == \"raster\"\n\n    # -- \u6e32\u67d3\u63a5\u53e3\uff08\u6805\u683c\u5f15\u64ce\u5b9e\u73b0\uff09------------------------------------------\n    def render_roundrect(self, spec: RoundRectSpec):\n        \"\"\"\u8fd4\u56de ``PIL.Image.Image``\uff08RGBA\uff09\u3002\u4e0d\u652f\u6301\u65f6\u629b :class:`NotImplementedError`\u3002\"\"\"\n        raise NotImplementedError\n\n    def render_track(self, spec: TrackSpec):\n        raise NotImplementedError\n\n    def render_thumb(self, spec: ThumbSpec):\n        raise NotImplementedError\n\n    def close(self) -&gt; None:\n        \"\"\"\u91ca\u653e\u5f15\u64ce\u6301\u6709\u7684\u8d44\u6e90\uff08\u53ef\u9009\uff09\u3002\"\"\"\n\n    def __repr__(self) -&gt; str:  # pragma: no cover - \u8c03\u8bd5\u53cb\u597d\n        return f\"&lt;{type(self).__name__} name={self.name!r} kind={self.kind!r}&gt;\"\n</code></pre>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.DrawEngine.available","title":"<code>available()</code>","text":"<p>\u4f9d\u8d56\u662f\u5426\u53ef\u5bfc\u5165\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>def available(self) -&gt; bool:\n    \"\"\"\u4f9d\u8d56\u662f\u5426\u53ef\u5bfc\u5165\u3002\"\"\"\n    import importlib.util\n\n    for mod in self.requires:\n        if importlib.util.find_spec(mod) is None:\n            return False\n    return True\n</code></pre>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.DrawEngine.close","title":"<code>close()</code>","text":"<p>\u91ca\u653e\u5f15\u64ce\u6301\u6709\u7684\u8d44\u6e90\uff08\u53ef\u9009\uff09\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>def close(self) -&gt; None:\n    \"\"\"\u91ca\u653e\u5f15\u64ce\u6301\u6709\u7684\u8d44\u6e90\uff08\u53ef\u9009\uff09\u3002\"\"\"\n</code></pre>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.DrawEngine.render_roundrect","title":"<code>render_roundrect(spec)</code>","text":"<p>\u8fd4\u56de <code>PIL.Image.Image</code>\uff08RGBA\uff09\u3002\u4e0d\u652f\u6301\u65f6\u629b :class:<code>NotImplementedError</code>\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>def render_roundrect(self, spec: RoundRectSpec):\n    \"\"\"\u8fd4\u56de ``PIL.Image.Image``\uff08RGBA\uff09\u3002\u4e0d\u652f\u6301\u65f6\u629b :class:`NotImplementedError`\u3002\"\"\"\n    raise NotImplementedError\n</code></pre>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.RoundRectSpec","title":"<code>RoundRectSpec</code>  <code>dataclass</code>","text":"<p>\u4e00\u4e2a\u5706\u89d2\u77e9\u5f62\uff08\u53ef\u5e26\u7eaf\u8272/\u6e10\u53d8\u63cf\u8fb9\uff09\u7684\u5b8c\u6574\u63cf\u8ff0\u3002</p> <p>\u5750\u6807\u4e00\u5f8b\u4ee5\u81ea\u8eab\u5de6\u4e0a\u89d2\u4e3a <code>(0, 0)</code>\u2014\u2014\u8fd9\u6b63\u662f tkfluent \u5404\u7ec4\u4ef6 <code>create_round_rectangle</code> \u7684\u5b9e\u9645\u7528\u6cd5\uff0c\u56e0\u6b64\u53ef\u4f5c\u4e3a\u7f13\u5b58\u952e\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>@dataclass(frozen=True)\nclass RoundRectSpec:\n    \"\"\"\u4e00\u4e2a\u5706\u89d2\u77e9\u5f62\uff08\u53ef\u5e26\u7eaf\u8272/\u6e10\u53d8\u63cf\u8fb9\uff09\u7684\u5b8c\u6574\u63cf\u8ff0\u3002\n\n    \u5750\u6807\u4e00\u5f8b\u4ee5\u81ea\u8eab\u5de6\u4e0a\u89d2\u4e3a ``(0, 0)``\u2014\u2014\u8fd9\u6b63\u662f tkfluent \u5404\u7ec4\u4ef6\n    ``create_round_rectangle`` \u7684\u5b9e\u9645\u7528\u6cd5\uff0c\u56e0\u6b64\u53ef\u4f5c\u4e3a\u7f13\u5b58\u952e\u3002\n    \"\"\"\n\n    width: int\n    height: int\n    rx: float = 0.0\n    ry: Optional[float] = None\n    fill: Optional[str] = None\n    fill_opacity: float = 1.0\n    outline: Optional[str] = None\n    outline_opacity: float = 1.0\n    outline2: Optional[str] = None\n    outline2_opacity: float = 1.0\n    outline_width: float = 1.0\n    # \u6e10\u53d8\u63cf\u8fb9\u7684\u4e24\u4e2a stop \u4f4d\u7f6e\uff08\u4e0e\u65e2\u6709 svgwrite \u5b9e\u73b0\u4e00\u81f4\uff1a0.9 / 1.0\uff09\n    gradient_stop1: float = 0.9\n    gradient_stop2: float = 1.0\n\n    @property\n    def effective_ry(self) -&gt; float:\n        return self.rx if self.ry is None else self.ry\n</code></pre>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.SvgEngine","title":"<code>SvgEngine</code>","text":"<p>               Bases: <code>DrawEngine</code></p> <p>SVG \u7cfb\u5f15\u64ce\u7684\u5360\u4f4d\u5b9e\u73b0\u3002</p> <p>\u5b83\u4eec\u4e0d\u53c2\u4e0e\u6805\u683c\u5feb\u901f\u8def\u5f84\u2014\u2014\u771f\u6b63\u7684\u7ed8\u5236\u4ecd\u7531 tkfluent \u5404\u7ec4\u4ef6\u91cc\u65e2\u6709\u7684 <code>Flu*Draw</code> \u4ee3\u7801\u5b8c\u6210\uff0c\u8fd9\u91cc\u53ea\u7528\u4e8e\u5728\u6ce8\u518c\u8868\u91cc\u8868\u8fbe\"\u5f53\u524d\u9009\u4e2d\u7684\u662f\u54ea\u4e2a\u5f15\u64ce\"\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>class SvgEngine(DrawEngine):\n    \"\"\"SVG \u7cfb\u5f15\u64ce\u7684\u5360\u4f4d\u5b9e\u73b0\u3002\n\n    \u5b83\u4eec\u4e0d\u53c2\u4e0e\u6805\u683c\u5feb\u901f\u8def\u5f84\u2014\u2014\u771f\u6b63\u7684\u7ed8\u5236\u4ecd\u7531 tkfluent \u5404\u7ec4\u4ef6\u91cc\u65e2\u6709\u7684\n    ``Flu*Draw`` \u4ee3\u7801\u5b8c\u6210\uff0c\u8fd9\u91cc\u53ea\u7528\u4e8e\u5728\u6ce8\u518c\u8868\u91cc\u8868\u8fbe\"\u5f53\u524d\u9009\u4e2d\u7684\u662f\u54ea\u4e2a\u5f15\u64ce\"\u3002\n    \"\"\"\n\n    kind = \"svg\"\n\n    def render_roundrect(self, spec):  # pragma: no cover - \u6709\u610f\u4e0d\u652f\u6301\n        raise NotImplementedError(\n            f\"{self.name} \u662f SVG \u5f15\u64ce\uff0c\u8bf7\u8d70\u65e2\u6709\u7684 svgwrite + tksvg \u8def\u5f84\"\n        )\n\n    render_track = render_roundrect\n    render_thumb = render_roundrect\n</code></pre>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.ThumbSpec","title":"<code>ThumbSpec</code>  <code>dataclass</code>","text":"<p>\u6ed1\u5757\u7684\u5706\u5f62\u628a\u624b\uff1a\u5916\u5708\u6e10\u53d8\u4f2a\u9634\u5f71 + \u5916\u586b\u5145 + \u5185\u586b\u5145\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>@dataclass(frozen=True)\nclass ThumbSpec:\n    \"\"\"\u6ed1\u5757\u7684\u5706\u5f62\u628a\u624b\uff1a\u5916\u5708\u6e10\u53d8\u4f2a\u9634\u5f71 + \u5916\u586b\u5145 + \u5185\u586b\u5145\u3002\"\"\"\n\n    width: int\n    height: int\n    r1: float\n    r2: float\n    fill: Optional[str] = None\n    fill_opacity: float = 1.0\n    outline: Optional[str] = None\n    outline_opacity: float = 1.0\n    outline2: Optional[str] = None\n    outline2_opacity: float = 1.0\n    inner_fill: Optional[str] = None\n    inner_fill_opacity: float = 1.0\n</code></pre>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.TrackSpec","title":"<code>TrackSpec</code>  <code>dataclass</code>","text":"<p>\u6ed1\u5757\u7684\u8fdb\u5ea6\u6761\u69fd\uff1a\u5de6\u534a\u6bb5\uff08\u5df2\u9009\u4e2d\uff09+ \u53f3\u534a\u6bb5\uff08\u672a\u9009\u4e2d\uff09\u4e24\u4e2a\u5706\u89d2\u77e9\u5f62\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>@dataclass(frozen=True)\nclass TrackSpec:\n    \"\"\"\u6ed1\u5757\u7684\u8fdb\u5ea6\u6761\u69fd\uff1a\u5de6\u534a\u6bb5\uff08\u5df2\u9009\u4e2d\uff09+ \u53f3\u534a\u6bb5\uff08\u672a\u9009\u4e2d\uff09\u4e24\u4e2a\u5706\u89d2\u77e9\u5f62\u3002\"\"\"\n\n    width: int\n    height: int\n    width2: float\n    radius: float = 3.0\n    track_fill: Optional[str] = None\n    track_opacity: float = 1.0\n    rail_fill: Optional[str] = None\n    rail_opacity: float = 1.0\n</code></pre>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.cache_stats","title":"<code>cache_stats(master=None)</code>","text":"<p>\u7f13\u5b58\u7edf\u8ba1\uff0c\u4fbf\u4e8e\u6027\u80fd\u8bca\u65ad\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\cache.py</code> <pre><code>def cache_stats(master=None) -&gt; Dict[str, Any]:\n    \"\"\"\u7f13\u5b58\u7edf\u8ba1\uff0c\u4fbf\u4e8e\u6027\u80fd\u8bca\u65ad\u3002\"\"\"\n    with _LOCK:\n        if master is not None:\n            return _cache_for(master).stats()\n        merged: Dict[str, Any] = {\n            \"interpreters\": len(_CACHES),\n            \"entries\": 0,\n            \"pixels\": 0,\n            \"budget\": _PIXEL_BUDGET,\n            \"hits\": 0,\n            \"misses\": 0,\n            \"overflow\": 0,\n        }\n        for _, cache in _CACHES.values():\n            stats = cache.stats()\n            for field in (\"entries\", \"pixels\", \"hits\", \"misses\", \"overflow\"):\n                merged[field] += stats[field]\n        total = merged[\"hits\"] + merged[\"misses\"]\n        merged[\"hit_rate\"] = (merged[\"hits\"] / total) if total else 0.0\n        return merged\n</code></pre>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.clear_cache","title":"<code>clear_cache(master=None)</code>","text":"<p>\u6e05\u7a7a\u7f13\u5b58\u3002<code>master=None</code> \u65f6\u6e05\u7a7a\u5168\u90e8\u89e3\u91ca\u5668\u3002</p> <p>.. warning::    \u6e05\u7a7a\u540e\uff0c\u4ecd\u7136\u5b58\u5728\u4e8e\u753b\u5e03\u4e0a\u7684 item \u4f1a\u56e0\u4e3a\u56fe\u7247\u88ab\u56de\u6536\u800c\u53d8\u7a7a\u767d\u3002    \u4ec5\u5728\u786e\u5b9e\u8981\u91cd\u5efa\u6574\u4e2a\u754c\u9762\u65f6\u8c03\u7528\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\cache.py</code> <pre><code>def clear_cache(master=None) -&gt; int:\n    \"\"\"\u6e05\u7a7a\u7f13\u5b58\u3002``master=None`` \u65f6\u6e05\u7a7a\u5168\u90e8\u89e3\u91ca\u5668\u3002\n\n    .. warning::\n       \u6e05\u7a7a\u540e\uff0c\u4ecd\u7136\u5b58\u5728\u4e8e\u753b\u5e03\u4e0a\u7684 item \u4f1a\u56e0\u4e3a\u56fe\u7247\u88ab\u56de\u6536\u800c\u53d8\u7a7a\u767d\u3002\n       \u4ec5\u5728\u786e\u5b9e\u8981\u91cd\u5efa\u6574\u4e2a\u754c\u9762\u65f6\u8c03\u7528\u3002\n    \"\"\"\n    with _LOCK:\n        if master is None:\n            total = sum(cache.clear() for _, cache in _CACHES.values())\n            _CACHES.clear()\n            return total\n        return _cache_for(master).clear()\n</code></pre>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.get_engine","title":"<code>get_engine(name=None)</code>","text":"<p>\u6309\u540d\u5b57\u53d6\u5f15\u64ce\uff1b<code>None</code> \u8868\u793a\u5f53\u524d\u5f15\u64ce\u3002\u540d\u5b57\u672a\u77e5\u65f6\u56de\u9000\u5230\u5f53\u524d/\u9ed8\u8ba4\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>def get_engine(name: Optional[str] = None) -&gt; DrawEngine:\n    \"\"\"\u6309\u540d\u5b57\u53d6\u5f15\u64ce\uff1b``None`` \u8868\u793a\u5f53\u524d\u5f15\u64ce\u3002\u540d\u5b57\u672a\u77e5\u65f6\u56de\u9000\u5230\u5f53\u524d/\u9ed8\u8ba4\u3002\"\"\"\n    if name is None:\n        name = _CURRENT[\"name\"]\n    engine = _ENGINES.get(str(name).lower())\n    if engine is None:\n        engine = _ENGINES.get(_CURRENT[\"name\"])\n    if engine is None:  # \u7406\u8bba\u4e0a\u4e0d\u4f1a\u53d1\u751f\uff1a\u6ce8\u518c\u8868\u81f3\u5c11\u6709\u4e00\u4e2a\u9ed8\u8ba4\u5f15\u64ce\n        raise RuntimeError(\"tkdeft \u5f15\u64ce\u6ce8\u518c\u8868\u4e3a\u7a7a\uff0c\u65e0\u6cd5\u89e3\u6790\u7ed8\u5236\u5f15\u64ce\")\n    return engine\n</code></pre>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.list_engines","title":"<code>list_engines()</code>","text":"<p>\u8fd4\u56de <code>{\u5f15\u64ce\u540d: \u662f\u5426\u53ef\u7528}</code>\uff08\u53ea\u5217\u4e3b\u540d\uff0c\u4e0d\u542b\u522b\u540d\uff09\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>def list_engines() -&gt; \"dict[str, bool]\":\n    \"\"\"\u8fd4\u56de ``{\u5f15\u64ce\u540d: \u662f\u5426\u53ef\u7528}``\uff08\u53ea\u5217\u4e3b\u540d\uff0c\u4e0d\u542b\u522b\u540d\uff09\u3002\"\"\"\n    seen = {}\n    for name, engine in _ENGINES.items():\n        if engine.name == name:\n            seen[name] = engine.available()\n    return seen\n</code></pre>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.parse_color","title":"<code>parse_color(value, opacity=1.0)</code>","text":"<p>\u89e3\u6790\u989c\u8272 + \u900f\u660e\u5ea6\u3002</p> <p>\u8fd4\u56de <code>(r, g, b, a)</code>\uff1b\u5f53\u989c\u8272\u8868\u793a\"\u4e0d\u7ed8\u5236\"\u6216\u89e3\u6790\u5931\u8d25\u65f6\u8fd4\u56de <code>None</code>\uff0c \u8c03\u7528\u65b9\u636e\u6b64\u5b8c\u5168\u8df3\u8fc7\u8fd9\u4e00\u5c42\u7684\u7ed8\u5236\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\colors.py</code> <pre><code>def parse_color(value, opacity=1.0) -&gt; Optional[RGBA]:\n    \"\"\"\u89e3\u6790\u989c\u8272 + \u900f\u660e\u5ea6\u3002\n\n    \u8fd4\u56de ``(r, g, b, a)``\uff1b\u5f53\u989c\u8272\u8868\u793a\"\u4e0d\u7ed8\u5236\"\u6216\u89e3\u6790\u5931\u8d25\u65f6\u8fd4\u56de ``None``\uff0c\n    \u8c03\u7528\u65b9\u636e\u6b64\u5b8c\u5168\u8df3\u8fc7\u8fd9\u4e00\u5c42\u7684\u7ed8\u5236\u3002\n    \"\"\"\n    alpha = parse_opacity(opacity)\n\n    if value is None:\n        return None\n\n    if isinstance(value, (tuple, list)):\n        parts = list(value)\n        if len(parts) == 3:\n            r, g, b = (int(max(0, min(255, p))) for p in parts)\n            a = int(round(alpha * 255))\n        elif len(parts) &gt;= 4:\n            r, g, b = (int(max(0, min(255, p))) for p in parts[:3])\n            a = int(max(0, min(255, parts[3])))\n            # \u5143\u7ec4\u81ea\u5e26 alpha \u65f6\uff0c\u5916\u5c42 opacity \u89c6\u4e3a\u989d\u5916\u8c03\u5236\n            a = int(round(a * alpha))\n        else:\n            return None\n        return (r, g, b, a) if a &gt; 0 else None\n\n    if not isinstance(value, str):\n        return None\n\n    text = value.strip()\n    if text.lower() in _TRANSPARENT_WORDS:\n        return None\n\n    rgb: Optional[Tuple[int, int, int]] = None\n    embedded_alpha: Optional[int] = None\n\n    if text.startswith(\"#\"):\n        h = text[1:]\n        if len(h) == 3:\n            h = \"\".join(ch * 2 for ch in h)\n        if len(h) == 4:  # #RGBA\n            h = \"\".join(ch * 2 for ch in h)\n        if len(h) == 8:  # #RRGGBBAA\n            try:\n                embedded_alpha = int(h[6:8], 16)\n            except ValueError:\n                return None\n            h = h[:6]\n        if len(h) != 6:\n            return None\n        try:\n            rgb = (int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16))\n        except ValueError:\n            return None\n    else:\n        rgb = _named_to_rgb(text)\n\n    if rgb is None:\n        return None\n\n    a = alpha if embedded_alpha is None else (embedded_alpha / 255.0) * alpha\n    a_int = int(round(a * 255))\n    if a_int &lt;= 0:\n        return None\n    return (rgb[0], rgb[1], rgb[2], a_int)\n</code></pre>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.parse_opacity","title":"<code>parse_opacity(value, default=1.0)</code>","text":"<p>\u628a\u900f\u660e\u5ea6\u7edf\u4e00\u6210 <code>[0, 1]</code> \u7684 float\u3002\u975e\u6cd5\u503c\u56de\u9000\u5230 <code>default</code>\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\colors.py</code> <pre><code>def parse_opacity(value, default: float = 1.0) -&gt; float:\n    \"\"\"\u628a\u900f\u660e\u5ea6\u7edf\u4e00\u6210 ``[0, 1]`` \u7684 float\u3002\u975e\u6cd5\u503c\u56de\u9000\u5230 ``default``\u3002\"\"\"\n    if value is None:\n        return default\n    try:\n        result = float(value)\n    except (TypeError, ValueError):\n        return default\n    if result != result:  # NaN\n        return default\n    if result &lt; 0.0:\n        return 0.0\n    if result &gt; 1.0:\n        return 1.0\n    return result\n</code></pre>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.register_engine","title":"<code>register_engine(engine, *, aliases=(), default=False)</code>","text":"<p>\u628a\u4e00\u4e2a\u5f15\u64ce\u5b9e\u4f8b\u767b\u8bb0\u8fdb\u6ce8\u518c\u8868\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>def register_engine(engine: DrawEngine, *, aliases: Tuple[str, ...] = (),\n                    default: bool = False) -&gt; DrawEngine:\n    \"\"\"\u628a\u4e00\u4e2a\u5f15\u64ce\u5b9e\u4f8b\u767b\u8bb0\u8fdb\u6ce8\u518c\u8868\u3002\"\"\"\n    _ENGINES[engine.name] = engine\n    for alias in aliases:\n        _ENGINES[alias] = engine\n    if default or not _ENGINES:\n        _CURRENT[\"name\"] = engine.name\n    return engine\n</code></pre>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.render_roundrect","title":"<code>render_roundrect(spec, master)</code>","text":"<p>\u6e32\u67d3\u5706\u89d2\u77e9\u5f62\uff1b\u5f53\u524d\u5f15\u64ce\u4e0d\u652f\u6301\u65f6\u8fd4\u56de <code>None</code>\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\__init__.py</code> <pre><code>def render_roundrect(spec: RoundRectSpec, master):\n    \"\"\"\u6e32\u67d3\u5706\u89d2\u77e9\u5f62\uff1b\u5f53\u524d\u5f15\u64ce\u4e0d\u652f\u6301\u65f6\u8fd4\u56de ``None``\u3002\"\"\"\n    return _render(\"roundrect\", spec, master)\n</code></pre>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.render_thumb","title":"<code>render_thumb(spec, master)</code>","text":"<p>\u6e32\u67d3\u6ed1\u5757\u628a\u624b\uff1b\u5f53\u524d\u5f15\u64ce\u4e0d\u652f\u6301\u65f6\u8fd4\u56de <code>None</code>\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\__init__.py</code> <pre><code>def render_thumb(spec: ThumbSpec, master):\n    \"\"\"\u6e32\u67d3\u6ed1\u5757\u628a\u624b\uff1b\u5f53\u524d\u5f15\u64ce\u4e0d\u652f\u6301\u65f6\u8fd4\u56de ``None``\u3002\"\"\"\n    return _render(\"thumb\", spec, master)\n</code></pre>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.render_track","title":"<code>render_track(spec, master)</code>","text":"<p>\u6e32\u67d3\u6ed1\u5757\u8fdb\u5ea6\u6761\u69fd\uff1b\u5f53\u524d\u5f15\u64ce\u4e0d\u652f\u6301\u65f6\u8fd4\u56de <code>None</code>\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\__init__.py</code> <pre><code>def render_track(spec: TrackSpec, master):\n    \"\"\"\u6e32\u67d3\u6ed1\u5757\u8fdb\u5ea6\u6761\u69fd\uff1b\u5f53\u524d\u5f15\u64ce\u4e0d\u652f\u6301\u65f6\u8fd4\u56de ``None``\u3002\"\"\"\n    return _render(\"track\", spec, master)\n</code></pre>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.set_cache_budget","title":"<code>set_cache_budget(pixels)</code>","text":"<p>\u8bbe\u7f6e\u50cf\u7d20\u9884\u7b97\uff08<code>None</code> \u8868\u793a\u4e0d\u9650\u5236\uff09\u3002\u5e94\u7528\u4e8e\u6240\u6709\u89e3\u91ca\u5668\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\cache.py</code> <pre><code>def set_cache_budget(pixels: Optional[int]) -&gt; None:\n    \"\"\"\u8bbe\u7f6e\u50cf\u7d20\u9884\u7b97\uff08``None`` \u8868\u793a\u4e0d\u9650\u5236\uff09\u3002\u5e94\u7528\u4e8e\u6240\u6709\u89e3\u91ca\u5668\u3002\"\"\"\n    global _PIXEL_BUDGET\n    with _LOCK:\n        _PIXEL_BUDGET = DEFAULT_PIXEL_BUDGET if pixels is None else max(0, int(pixels))\n        for _, cache in _CACHES.values():\n            cache.budget = _PIXEL_BUDGET\n</code></pre>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.set_engine","title":"<code>set_engine(name)</code>","text":"<p>\u5207\u6362\u5f53\u524d\u5f15\u64ce\u3002</p> <p><code>name</code> \u53ef\u4ee5\u662f\u5f15\u64ce\u540d\uff08<code>\"skia\"</code> / <code>\"pillow\"</code> / <code>\"tksvg\"</code> / <code>\"cairo\"</code> / <code>\"wand\"</code>\uff09\uff0c\u4e5f\u53ef\u4ee5\u662f\u517c\u5bb9\u65e7 API \u7684\u6574\u6570\u7f16\u53f7\uff1a</p> <p>===== ========== \u7f16\u53f7   \u5f15\u64ce ===== ========== 0     tksvg\uff08\u9ed8\u8ba4\uff0cSVG \u6587\u4ef6\uff09 1     wand\uff08SVG \u2192 PNG\uff09 2     skia\uff08\u8fdb\u7a0b\u5185\u6805\u683c\uff09 3     pillow\uff08\u8fdb\u7a0b\u5185\u6805\u683c\uff0c\u65e0\u989d\u5916\u4f9d\u8d56\uff09 4     cairo\uff08\u8fdb\u7a0b\u5185\u6805\u683c\uff09 ===== ==========</p> <p>\u975e\u6cd5\u6216\u4e0d\u53ef\u7528\u7684\u5f15\u64ce\u4f1a\u629b\u51fa :class:<code>ValueError</code>\uff0c\u907f\u514d\u9759\u9ed8\u964d\u7ea7\u5bfc\u81f4 \"\u4ee5\u4e3a\u5f00\u4e86 skia \u5176\u5b9e\u8fd8\u5728\u8d70\u6162\u8def\u5f84\"\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\base.py</code> <pre><code>def set_engine(name) -&gt; DrawEngine:\n    \"\"\"\u5207\u6362\u5f53\u524d\u5f15\u64ce\u3002\n\n    ``name`` \u53ef\u4ee5\u662f\u5f15\u64ce\u540d\uff08``\"skia\"`` / ``\"pillow\"`` / ``\"tksvg\"`` / ``\"cairo\"``\n    / ``\"wand\"``\uff09\uff0c\u4e5f\u53ef\u4ee5\u662f\u517c\u5bb9\u65e7 API \u7684\u6574\u6570\u7f16\u53f7\uff1a\n\n    ===== ==========\n    \u7f16\u53f7   \u5f15\u64ce\n    ===== ==========\n    0     tksvg\uff08\u9ed8\u8ba4\uff0cSVG \u6587\u4ef6\uff09\n    1     wand\uff08SVG \u2192 PNG\uff09\n    2     skia\uff08\u8fdb\u7a0b\u5185\u6805\u683c\uff09\n    3     pillow\uff08\u8fdb\u7a0b\u5185\u6805\u683c\uff0c\u65e0\u989d\u5916\u4f9d\u8d56\uff09\n    4     cairo\uff08\u8fdb\u7a0b\u5185\u6805\u683c\uff09\n    ===== ==========\n\n    \u975e\u6cd5\u6216\u4e0d\u53ef\u7528\u7684\u5f15\u64ce\u4f1a\u629b\u51fa :class:`ValueError`\uff0c\u907f\u514d\u9759\u9ed8\u964d\u7ea7\u5bfc\u81f4\n    \"\u4ee5\u4e3a\u5f00\u4e86 skia \u5176\u5b9e\u8fd8\u5728\u8d70\u6162\u8def\u5f84\"\u3002\n    \"\"\"\n    engine = _ENGINES.get(str(name).lower())\n    if engine is None:\n        raise ValueError(\n            f\"\u672a\u77e5\u7684\u7ed8\u5236\u5f15\u64ce {name!r}\uff1b\u53ef\u7528\uff1a{sorted(list_engines())}\"\n        )\n    if not engine.available():\n        raise ValueError(\n            f\"\u7ed8\u5236\u5f15\u64ce {engine.name!r} \u4e0d\u53ef\u7528\uff0c\u7f3a\u5c11\u4f9d\u8d56\uff1a{engine.requires}\"\n        )\n    _CURRENT[\"name\"] = engine.name\n    return engine\n</code></pre>"},{"location":"api/tkdeft.engines.html#tkdeft.engines.to_photoimage","title":"<code>to_photoimage(image, master)</code>","text":"<p><code>PIL.Image</code> \u2192 <code>tkinter</code> \u7684 <code>PhotoImage</code>\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\__init__.py</code> <pre><code>def to_photoimage(image, master):\n    \"\"\"``PIL.Image`` \u2192 ``tkinter`` \u7684 ``PhotoImage``\u3002\"\"\"\n    from PIL import ImageTk\n\n    return ImageTk.PhotoImage(image, master=master)\n</code></pre>"},{"location":"api/tkdeft.engines.pillow_engine.html","title":"engines.pillow \u00b7 Pillow \u5f15\u64ce","text":"<p>Pillow \u7ed8\u5236\u5f15\u64ce\uff08\u96f6\u989d\u5916\u4f9d\u8d56\u7684\u8fdb\u7a0b\u5185\u6805\u683c\u5316\uff09\u3002</p> <p>Pillow \u672c\u6765\u5c31\u662f tkdeft \u7684\u786c\u4f9d\u8d56\uff0c\u6240\u4ee5\u8fd9\u4e2a\u5f15\u64ce\u6c38\u8fdc\u53ef\u7528\u2014\u2014\u5373\u4f7f\u76ee\u6807\u673a\u5668\u4e0a \u6ca1\u6709 skia-python / pycairo\uff0c\u4e5f\u80fd\u4eab\u53d7\"\u4e0d\u843d\u76d8\u3001\u4e0d\u89e3\u6790 SVG\"\u7684\u52a0\u901f\u3002</p> <p><code>ImageDraw</code> \u672c\u8eab\u4e0d\u505a\u6297\u952f\u9f7f\uff0c\u56e0\u6b64\u8fd9\u91cc\u91c7\u7528\u8d85\u91c7\u6837\uff1a\u6309 <code>scale</code> \u500d\u5c3a\u5bf8\u7ed8\u5236\uff0c \u518d\u7528 LANCZOS \u7f29\u56de\u76ee\u6807\u5c3a\u5bf8\u3002\u7f29\u653e\u500d\u7387\u968f\u9762\u79ef\u81ea\u9002\u5e94\uff0c\u4fdd\u8bc1\u5927\u5c3a\u5bf8\u5706\u89d2\uff08\u5982 FluFrame\uff09 \u4e0d\u4f1a\u56e0\u4e3a\u8d85\u91c7\u6837\u800c\u53d8\u6162\u3002</p> <p>\u6e10\u53d8\u63cf\u8fb9 / \u6e10\u53d8\u586b\u5145\u7684\u5b9e\u73b0\u65b9\u5f0f\uff1a\u5148\u753b\u4e00\u5f20\u7070\u5ea6\u906e\u7f69\uff0c\u518d\u7528 numpy \u751f\u6210\u4e00\u5217\u7ad6\u76f4\u65b9\u5411\u7684 \u7ebf\u6027\u6e10\u53d8\u8272\uff0c\u6700\u540e\u7528\u906e\u7f69\u8c03\u5236 alpha \u5408\u6210\u3002\u8bed\u4e49\u4e0e\u65e2\u6709\u7684 svgwrite \u5b9e\u73b0\u4fdd\u6301\u4e00\u81f4\u3002</p>"},{"location":"api/tkdeft.engines.pillow_engine.html#tkdeft.engines.pillow_engine.PillowEngine","title":"<code>PillowEngine</code>","text":"<p>               Bases: <code>DrawEngine</code></p> <p>\u57fa\u4e8e Pillow + numpy \u7684\u8fdb\u7a0b\u5185\u6805\u683c\u5f15\u64ce\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\pillow_engine.py</code> <pre><code>class PillowEngine(DrawEngine):\n    \"\"\"\u57fa\u4e8e Pillow + numpy \u7684\u8fdb\u7a0b\u5185\u6805\u683c\u5f15\u64ce\u3002\"\"\"\n\n    name = \"pillow\"\n    kind = \"raster\"\n    requires = (\"PIL\", \"numpy\")\n    description = \"Pillow \u8d85\u91c7\u6837\u6805\u683c\u5316\uff08\u65e0\u989d\u5916\u4f9d\u8d56\uff0c\u6c38\u8fdc\u53ef\u7528\uff09\"\n\n    def __init__(self, supersample: \"int | None\" = None) -&gt; None:\n        #: \u56fa\u5b9a\u8d85\u91c7\u6837\u500d\u7387\uff1b``None`` \u8868\u793a\u6309\u9762\u79ef\u81ea\u9002\u5e94\n        self.supersample = supersample\n\n    # ------------------------------------------------------------------\n    def _scale_for(self, width: int, height: int) -&gt; int:\n        if self.supersample is not None:\n            return max(1, int(self.supersample))\n        return _supersample_for(width, height)\n\n    @staticmethod\n    def _gradient_column(height, y0, y1, c1, c2, stop1, stop2):\n        \"\"\"\u751f\u6210 ``(height, 4)`` \u7684\u7ad6\u76f4\u6e10\u53d8\u5217\uff0cstop \u4e4b\u5916\u6309 SVG \u8bed\u4e49\u5916\u63a8\u3002\"\"\"\n        import numpy as np\n\n        ys = np.arange(height, dtype=np.float64)\n        span = (y1 - y0) or 1.0\n        t = (ys - y0) / span\n        stop_span = (stop2 - stop1) or 1.0\n        u = np.clip((t - stop1) / stop_span, 0.0, 1.0)\n        a = np.asarray(c1, dtype=np.float64)\n        b = np.asarray(c2, dtype=np.float64)\n        return a[None, :] + (b - a)[None, :] * u[:, None]\n\n    def _paint_gradient(self, size, mask, column):\n        \"\"\"\u7528\u6e10\u53d8\u5217 + \u7070\u5ea6\u906e\u7f69\u751f\u6210\u4e00\u5c42 RGBA \u56fe\u50cf\u3002\"\"\"\n        import numpy as np\n        from PIL import Image\n\n        width, height = size\n        rgba = np.repeat(column[:, None, :], width, axis=1)\n        alpha = rgba[:, :, 3] * (np.asarray(mask, dtype=np.float64) / 255.0)\n        rgba[:, :, 3] = alpha\n        return Image.fromarray(np.clip(rgba, 0, 255).astype(np.uint8), \"RGBA\")\n\n    # ------------------------------------------------------------------\n    # \u5706\u89d2\u77e9\u5f62\n    # ------------------------------------------------------------------\n    def render_roundrect(self, spec: RoundRectSpec):\n        from PIL import Image, ImageDraw\n\n        width = max(1, int(round(spec.width)))\n        height = max(1, int(round(spec.height)))\n        s = self._scale_for(width, height)\n        W, H = width * s, height * s\n\n        base = Image.new(\"RGBA\", (W, H), (0, 0, 0, 0))\n\n        stroke_width = float(spec.outline_width or 0.0)\n        inset = stroke_width / 2.0 if stroke_width &gt; 0 else 0.0\n        rx = max(0.0, float(spec.rx) - inset)\n        ry = max(0.0, float(spec.effective_ry) - inset)\n        box = (\n            inset * s,\n            inset * s,\n            W - 1 - inset * s,\n            H - 1 - inset * s,\n        )\n        if box[2] &lt;= box[0]:\n            box = (box[0], box[1], box[0] + 1, box[3])\n        if box[3] &lt;= box[1]:\n            box = (box[0], box[1], box[2], box[1] + 1)\n        radius = min(rx * s, (box[2] - box[0]) / 2.0, (box[3] - box[1]) / 2.0)\n\n        # -- \u586b\u5145 --\n        fill = parse_color(spec.fill, spec.fill_opacity)\n        if fill:\n            layer = Image.new(\"RGBA\", (W, H), (0, 0, 0, 0))\n            ImageDraw.Draw(layer).rounded_rectangle(\n                box, radius=radius, fill=fill\n            )\n            base = Image.alpha_composite(base, layer)\n\n        # -- \u63cf\u8fb9 --\n        if stroke_width &gt; 0:\n            outline = parse_color(spec.outline, spec.outline_opacity)\n            outline2 = (\n                parse_color(spec.outline2, spec.outline2_opacity)\n                if spec.outline2\n                else None\n            )\n            line_width = max(1, int(round(stroke_width * s)))\n            if outline2 and outline2 != outline:\n                mask = Image.new(\"L\", (W, H), 0)\n                ImageDraw.Draw(mask).rounded_rectangle(\n                    box, radius=radius, outline=255, width=line_width\n                )\n                column = self._gradient_column(\n                    H, inset * s, H - inset * s, outline, outline2,\n                    spec.gradient_stop1, spec.gradient_stop2,\n                )\n                base = Image.alpha_composite(\n                    base, self._paint_gradient((W, H), mask, column)\n                )\n            elif outline:\n                layer = Image.new(\"RGBA\", (W, H), (0, 0, 0, 0))\n                ImageDraw.Draw(layer).rounded_rectangle(\n                    box, radius=radius, outline=outline, width=line_width\n                )\n                base = Image.alpha_composite(base, layer)\n\n        if s != 1:\n            base = base.resize((width, height), Image.LANCZOS)\n        return base\n\n    # ------------------------------------------------------------------\n    # \u6ed1\u5757\u8fdb\u5ea6\u6761\u69fd\n    # ------------------------------------------------------------------\n    def render_track(self, spec: TrackSpec):\n        from PIL import Image, ImageDraw\n\n        width = max(1, int(round(spec.width)))\n        height = max(1, int(round(spec.height)))\n        s = self._scale_for(width, height)\n        W, H = width * s, height * s\n        base = Image.new(\"RGBA\", (W, H), (0, 0, 0, 0))\n\n        left = max(0.0, min(float(spec.width2), float(width))) * s\n        radius = max(0.0, float(spec.radius) * s)\n\n        def _block(x0, x1, color):\n            nonlocal base\n            if x1 &lt;= x0 or color is None:\n                return\n            layer = Image.new(\"RGBA\", (W, H), (0, 0, 0, 0))\n            r = min(radius, (x1 - x0) / 2.0, H / 2.0)\n            ImageDraw.Draw(layer).rounded_rectangle(\n                (x0, 0, x1 - 1, H - 1), radius=r, fill=color\n            )\n            base = Image.alpha_composite(base, layer)\n\n        _block(0.0, left, parse_color(spec.track_fill, spec.track_opacity))\n        _block(left, float(W), parse_color(spec.rail_fill, spec.rail_opacity))\n\n        if s != 1:\n            base = base.resize((width, height), Image.LANCZOS)\n        return base\n\n    # ------------------------------------------------------------------\n    # \u6ed1\u5757\u628a\u624b\n    # ------------------------------------------------------------------\n    def render_thumb(self, spec: ThumbSpec):\n        from PIL import Image, ImageDraw\n\n        width = max(1, int(round(spec.width)))\n        height = max(1, int(round(spec.height)))\n        s = self._scale_for(width, height)\n        W, H = width * s, height * s\n        base = Image.new(\"RGBA\", (W, H), (0, 0, 0, 0))\n        r1 = float(spec.r1) * s\n        r2 = float(spec.r2) * s\n        cx, cy = W / 2.0, H / 2.0\n\n        def _circle(radius, color):\n            nonlocal base\n            if color is None or radius &lt;= 0:\n                return\n            layer = Image.new(\"RGBA\", (W, H), (0, 0, 0, 0))\n            ImageDraw.Draw(layer).ellipse(\n                (cx - radius, cy - radius, cx + radius, cy + radius), fill=color\n            )\n            base = Image.alpha_composite(base, layer)\n\n        # \u5916\u5708\u4f2a\u9634\u5f71\uff1a\u7ad6\u76f4\u6e10\u53d8\n        outline = parse_color(spec.outline, spec.outline_opacity)\n        outline2 = (\n            parse_color(spec.outline2, spec.outline2_opacity)\n            if spec.outline2\n            else None\n        )\n        if outline:\n            if outline2 and outline2 != outline:\n                mask = Image.new(\"L\", (W, H), 0)\n                ImageDraw.Draw(mask).ellipse(\n                    (cx - r1, cy - r1, cx + r1, cy + r1), fill=255\n                )\n                column = self._gradient_column(\n                    H, 1.0 * s, (float(spec.r1) * 2.0 - 1.0) * s,\n                    outline, outline2, 0.500208, 0.954545,\n                )\n                base = Image.alpha_composite(\n                    base, self._paint_gradient((W, H), mask, column)\n                )\n            else:\n                _circle(r1, outline)\n\n        _circle(r1 - s, parse_color(spec.fill, spec.fill_opacity))\n        _circle(r2, parse_color(spec.inner_fill, spec.inner_fill_opacity))\n\n        if s != 1:\n            base = base.resize((width, height), Image.LANCZOS)\n        return base\n</code></pre>"},{"location":"api/tkdeft.engines.skia_engine.html","title":"engines.skia \u00b7 Skia \u5f15\u64ce","text":"<p>Skia \u7ed8\u5236\u5f15\u64ce\uff08skia-python\uff0c\u8fdb\u7a0b\u5185\u6805\u683c\u5316\uff09\u3002</p>"},{"location":"api/tkdeft.engines.skia_engine.html#tkdeft.engines.skia_engine--_1","title":"\u4e3a\u4ec0\u4e48\u5feb","text":"<p>\u65e7\u8def\u5f84\uff1asvgwrite \u62fc XML \u2192 \u5199\u4e34\u65f6\u6587\u4ef6 \u2192 tksvg \u8bfb\u6587\u4ef6\u3001\u89e3\u6790 XML\u3001\u5149\u6805\u5316 \u2192 PhotoImage\u3002 \u65b0\u8def\u5f84\uff1a\u76f4\u63a5\u5728\u4e00\u5757 CPU \u4f4d\u56fe\u4e0a\u753b AntiAlias \u7684 RRect \u2192 \u5feb\u7167 \u2192 numpy \u2192 PIL \u2192 PhotoImage\u3002</p> <p>\u5b9e\u6d4b\uff08120\u00d732 \u5706\u89d2\u77e9\u5f62\uff0c\u672c\u673a\uff09::</p> <pre><code>svgwrite + \u843d\u76d8       0.44 ms\ntksvg \u8bfb\u6587\u4ef6 + \u89e3\u6790   1.53 ms\nmkstemp \u4e34\u65f6\u6587\u4ef6       ~3.5 ms   \u2190 \u65e7\u8def\u5f84\u6bcf\u6b21\u7ed8\u5236\u90fd\u65b0\u5efa\u4e00\u4e2a\u4e34\u65f6\u6587\u4ef6\n------------------------------\n\u65e7\u7aef\u5230\u7aef              5.6 ms\nskia \u7aef\u5230\u7aef           0.20 ms   \uff08\u518d\u53e0\u52a0 PhotoImage \u7f13\u5b58\u540e\u53ef\u964d\u5230\u63a5\u8fd1 0\uff09\n</code></pre>"},{"location":"api/tkdeft.engines.skia_engine.html#tkdeft.engines.skia_engine--_2","title":"\u901a\u9053\u5e8f\u81ea\u6821\u51c6","text":"<p><code>skia.Image.toarray()</code> \u8fd4\u56de\u7684\u662f\u56fe\u50cf\u539f\u751f\u901a\u9053\u5e8f\uff08\u5178\u578b\u4e3a BGRA\uff09\u4e14\u5df2\u89e3\u9884\u4e58\uff0c \u4e0d\u540c skia \u6784\u5efa\u4e0b\u672a\u5fc5\u4e00\u81f4\u3002\u8fd9\u91cc\u5728\u9996\u6b21\u4f7f\u7528\u65f6\u753b\u4e00\u4e2a\u4e0d\u5bf9\u79f0\u989c\u8272\u81ea\u68c0\uff0c \u81ea\u52a8\u51b3\u5b9a\u8981\u4e0d\u8981\u4ea4\u6362 R/B \u901a\u9053\uff0c\u907f\u514d\"\u7ea2\u8272\u53d8\u84dd\u8272\"\u8fd9\u7c7b\u9759\u9ed8\u9519\u8bef\u3002</p>"},{"location":"api/tkdeft.engines.skia_engine.html#tkdeft.engines.skia_engine.SkiaEngine","title":"<code>SkiaEngine</code>","text":"<p>               Bases: <code>DrawEngine</code></p> <p>\u57fa\u4e8e skia-python \u7684\u8fdb\u7a0b\u5185\u6805\u683c\u5f15\u64ce\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\engines\\skia_engine.py</code> <pre><code>class SkiaEngine(DrawEngine):\n    \"\"\"\u57fa\u4e8e skia-python \u7684\u8fdb\u7a0b\u5185\u6805\u683c\u5f15\u64ce\u3002\"\"\"\n\n    name = \"skia\"\n    kind = \"raster\"\n    requires = (\"skia\", \"numpy\", \"PIL\")\n    description = \"skia-python \u8fdb\u7a0b\u5185\u6805\u683c\u5316\uff08\u65e0\u78c1\u76d8 I/O\uff0c\u6297\u952f\u9f7f\u8d28\u91cf\u9ad8\uff09\"\n\n    def _new_canvas(self, width: int, height: int):\n        import skia\n\n        surface = skia.Surface(width, height)\n        canvas = surface.getCanvas()\n        canvas.clear(skia.ColorTRANSPARENT)\n        return surface, canvas\n\n    # ------------------------------------------------------------------\n    # \u5706\u89d2\u77e9\u5f62\n    # ------------------------------------------------------------------\n    def render_roundrect(self, spec: RoundRectSpec):\n        import skia\n\n        width = max(1, int(round(spec.width)))\n        height = max(1, int(round(spec.height)))\n        surface, canvas = self._new_canvas(width, height)\n\n        stroke_width = float(spec.outline_width or 0.0)\n        # SVG \u7684\u63cf\u8fb9\u662f\u5c45\u4e2d\u7684\uff1b\u628a\u51e0\u4f55\u5185\u7f29\u534a\u4e2a\u7ebf\u5bbd\uff0c\u63cf\u8fb9\u5916\u6cbf\u624d\u6b63\u597d\u8d34\u5408 0..width\n        inset = stroke_width / 2.0 if stroke_width &gt; 0 else 0.0\n        rx = max(0.0, float(spec.rx) - inset)\n        ry = max(0.0, float(spec.effective_ry) - inset)\n        rect = skia.Rect.MakeXYWH(\n            inset, inset, max(0.0, width - 2 * inset), max(0.0, height - 2 * inset)\n        )\n        rrect = skia.RRect.MakeRectXY(rect, rx, ry)\n\n        fill = parse_color(spec.fill, spec.fill_opacity)\n        if fill:\n            canvas.drawRRect(\n                rrect, skia.Paint(AntiAlias=True, Color=skia.Color(*fill))\n            )\n\n        if stroke_width &gt; 0:\n            paint = self._stroke_paint(spec, stroke_width, inset, height)\n            if paint is not None:\n                canvas.drawRRect(rrect, paint)\n\n        return _to_pil(surface.makeImageSnapshot())\n\n    def _stroke_paint(self, spec, stroke_width, inset, height):\n        import skia\n\n        outline = parse_color(spec.outline, spec.outline_opacity)\n        if not outline:\n            return None\n\n        outline2 = (\n            parse_color(spec.outline2, spec.outline2_opacity)\n            if spec.outline2\n            else None\n        )\n        paint = skia.Paint(\n            AntiAlias=True,\n            Style=skia.Paint.kStroke_Style,\n            StrokeWidth=stroke_width,\n        )\n\n        if outline2 and outline2 != outline:\n            paint.setShader(\n                skia.GradientShader.MakeLinear(\n                    points=[(float(inset), float(inset)),\n                            (float(inset), float(height - inset))],\n                    colors=[skia.Color(*outline), skia.Color(*outline2)],\n                    positions=[float(spec.gradient_stop1), float(spec.gradient_stop2)],\n                )\n            )\n        else:\n            paint.setColor(skia.Color(*outline))\n        return paint\n\n    # ------------------------------------------------------------------\n    # \u6ed1\u5757\u8fdb\u5ea6\u6761\u69fd\n    # ------------------------------------------------------------------\n    def render_track(self, spec: TrackSpec):\n        import skia\n\n        width = max(1, int(round(spec.width)))\n        height = max(1, int(round(spec.height)))\n        surface, canvas = self._new_canvas(width, height)\n        radius = max(0.0, float(spec.radius))\n\n        left_w = max(0.0, min(float(spec.width2), float(width)))\n        track = parse_color(spec.track_fill, spec.track_opacity)\n        if track and left_w &gt; 0:\n            canvas.drawRRect(\n                skia.RRect.MakeRectXY(\n                    skia.Rect.MakeXYWH(0, 0, left_w, height), radius, radius\n                ),\n                skia.Paint(AntiAlias=True, Color=skia.Color(*track)),\n            )\n\n        rail = parse_color(spec.rail_fill, spec.rail_opacity)\n        rail_w = width - left_w\n        if rail and rail_w &gt; 0:\n            canvas.drawRRect(\n                skia.RRect.MakeRectXY(\n                    skia.Rect.MakeXYWH(left_w, 0, rail_w, height), radius, radius\n                ),\n                skia.Paint(AntiAlias=True, Color=skia.Color(*rail)),\n            )\n\n        return _to_pil(surface.makeImageSnapshot())\n\n    # ------------------------------------------------------------------\n    # \u6ed1\u5757\u628a\u624b\n    # ------------------------------------------------------------------\n    def render_thumb(self, spec: ThumbSpec):\n        import skia\n\n        width = max(1, int(round(spec.width)))\n        height = max(1, int(round(spec.height)))\n        surface, canvas = self._new_canvas(width, height)\n        cx, cy = width / 2.0, height / 2.0\n        r1 = float(spec.r1)\n        r2 = float(spec.r2)\n\n        outline = parse_color(spec.outline, spec.outline_opacity)\n        outline2 = (\n            parse_color(spec.outline2, spec.outline2_opacity)\n            if spec.outline2\n            else None\n        )\n        if outline:\n            paint = skia.Paint(AntiAlias=True)\n            if outline2 and outline2 != outline:\n                # \u4e0e\u65e2\u6709 SVG \u5b9e\u73b0\u4e00\u81f4\uff1a\u7ad6\u76f4\u7ebf\u6027\u6e10\u53d8\uff0cstop 0.500208 / 0.954545\n                paint.setShader(\n                    skia.GradientShader.MakeLinear(\n                        points=[(r1, 1.0), (r1, r1 * 2.0 - 1.0)],\n                        colors=[skia.Color(*outline), skia.Color(*outline2)],\n                        positions=[0.500208, 0.954545],\n                    )\n                )\n            else:\n                paint.setColor(skia.Color(*outline))\n            canvas.drawCircle(cx, cy, r1, paint)\n\n        fill = parse_color(spec.fill, spec.fill_opacity)\n        if fill:\n            canvas.drawCircle(\n                cx, cy, max(0.0, r1 - 1.0),\n                skia.Paint(AntiAlias=True, Color=skia.Color(*fill)),\n            )\n\n        inner = parse_color(spec.inner_fill, spec.inner_fill_opacity)\n        if inner:\n            canvas.drawCircle(\n                cx, cy, r2, skia.Paint(AntiAlias=True, Color=skia.Color(*inner))\n            )\n\n        return _to_pil(surface.makeImageSnapshot())\n</code></pre>"},{"location":"api/tkdeft.object.html","title":"object \u00b7 DObject \u914d\u7f6e\u5bb9\u5668","text":""},{"location":"api/tkdeft.object.html#tkdeft.object.DObject","title":"<code>DObject</code>","text":"<p>               Bases: <code>object</code></p> <p>\u57fa\u7840\u5bf9\u8c61</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\object.py</code> <pre><code>class DObject(object):\n    \"\"\"\n    \u57fa\u7840\u5bf9\u8c61\n    \"\"\"\n\n    from easydict import EasyDict\n\n    attributes = EasyDict(\n        {\n            \"class\": \"DObject\"\n        }\n    )\n\n    def dconfigure(self, **kwargs):\n        for attribute in self.attributes:\n            if attribute in kwargs:\n                self.attributes[attribute] = kwargs.pop(attribute)\n\n    dconfig = dconfigure\n\n    def dcget(self, key):\n        if key in self.attributes:\n            return self.attributes[key]\n        else:\n            return None\n</code></pre>"},{"location":"api/tkdeft.svg.html","title":"svg \u00b7 SVG \u5f62\u72b6\u52a9\u624b","text":"<p>svgwrite \u5f62\u72b6\u52a9\u624b\u3002</p>"},{"location":"api/tkdeft.svg.html#tkdeft.svg--_1","title":"\u4e3a\u4ec0\u4e48\u9700\u8981\u5b83","text":"<p>tkfluent \u91cc\u539f\u5148\u6bcf\u4e2a\u7ec4\u4ef6\u90fd\u624b\u5199\u4e00\u904d\u5706\u89d2\u77e9\u5f62\u7684 SVG \u62fc\u88c5\uff0c\u51e0\u4f55\u5199\u6cd5\u5404\u4e0d\u76f8\u540c\uff0c \u5e76\u4e14\u666e\u904d\u8e29\u4e86\u540c\u4e00\u4e2a\u5751\uff1a</p> <p>.. code-block:: python</p> <pre><code>dwg.rect((x1, y1), (x2 - x1, y2 - y1), rx, ry,\n         stroke=\"#000\", stroke_width=1,\n         transform=\"translate(0.500000 0.500000)\")\n</code></pre> <p>SVG \u7684\u63cf\u8fb9\u662f\u4ee5\u8def\u5f84\u4e3a\u4e2d\u5fc3\u7ebf\u5411\u4e24\u4fa7\u5404\u753b\u534a\u4e2a\u7ebf\u5bbd\u3002\u4e0a\u9762\u8fd9\u79cd\u5199\u6cd5\u628a\u77e9\u5f62\u653e\u5230 <code>(0.5, 0.5)</code>\u3001\u5c3a\u5bf8\u4ecd\u7136\u662f\u6574\u5bbd\u6574\u9ad8\uff0c\u4e8e\u662f\u77e9\u5f62\u53f3\u8fb9\u754c\u6b63\u597d\u843d\u5728 <code>x = w + 0.5</code>\uff1a \u53f3\u8fb9\u548c\u4e0b\u8fb9\u7684\u63cf\u8fb9\u88ab\u6574\u4e2a\u63a8\u5230\u753b\u5e03\u4e4b\u5916\uff0c\u5b8c\u5168\u4e0d\u53ef\u89c1\u2014\u2014\u6309\u94ae\u770b\u8d77\u6765\u53ea\u6709\u4e0a\u8fb9\u6846\u548c \u5de6\u8fb9\u6846\u3002frame / listbox \u7528\u7684\u662f\u4e0d\u52a0 translate \u7684\u7248\u672c\uff0c\u56db\u8fb9\u5404\u88ab\u524a\u6389\u4e00\u534a\u539a\u5ea6\u3002</p> <p>\u6b63\u786e\u505a\u6cd5\u662f\u628a\u51e0\u4f55\u5411\u5185\u6536\u7f29\u534a\u4e2a\u7ebf\u5bbd\uff0c\u8ba9\u63cf\u8fb9\u7684\u5916\u6cbf\u6b63\u597d\u8d34\u5408\u753b\u5e03\u8fb9\u7f18\u3002 \u6805\u683c\u5f15\u64ce\uff08skia / pillow / cairo\uff09\u672c\u6765\u5c31\u662f\u8fd9\u4e48\u7b97\u7684\uff0c\u672c\u6a21\u5757\u8ba9 SVG \u5f15\u64ce\u4e0e\u4e4b\u5bf9\u9f50\u3002</p>"},{"location":"api/tkdeft.svg.html#tkdeft.svg.add_roundrect","title":"<code>add_roundrect(dwg, x1, y1, x2, y2, radius, radiusy=None, *, fill='transparent', fill_opacity=1, outline='black', outline2=None, outline_opacity=1, outline2_opacity=1, width=1, gradient=True, gradient_id='DButton.Border', gradient_stop1=0.9, gradient_stop2=1.0, **extra)</code>","text":"<p>\u5f80 svgwrite \u7684 <code>Drawing</code> \u91cc\u52a0\u4e00\u4e2a\u56db\u8fb9\u63cf\u8fb9\u90fd\u5b8c\u6574\u7684\u5706\u89d2\u77e9\u5f62\u3002</p> <p>:param dwg: <code>svgwrite.Drawing</code> \u5185\u90e8\u7684\u753b\u5e03\u5bf9\u8c61\uff08\u901a\u5e38\u662f <code>drawing[1]</code>\uff09 :param fill: \u586b\u5145\u8272\uff0c<code>\"transparent\"</code> \u8868\u793a\u4e0d\u586b\u5145 :param fill_opacity: \u586b\u5145\u900f\u660e\u5ea6 :param outline: \u63cf\u8fb9\u8272 :param outline2: \u6e10\u53d8\u63cf\u8fb9\u7684\u7b2c\u4e8c\u4e2a\u989c\u8272\uff1b\u4e3a\u7a7a\u5219\u7528\u7eaf\u8272\u63cf\u8fb9 :param outline_opacity: \u63cf\u8fb9\u900f\u660e\u5ea6 :param outline2_opacity: \u6e10\u53d8\u63cf\u8fb9\u7b2c\u4e8c\u4e2a\u989c\u8272\u7684\u900f\u660e\u5ea6 :param width: \u63cf\u8fb9\u5bbd\u5ea6\uff08\u63cf\u8fb9\u4ee5\u8def\u5f84\u4e3a\u4e2d\u5fc3\u7ebf\uff0c\u51e0\u4f55\u4f1a\u81ea\u52a8\u5185\u7f29\u534a\u4e2a\u7ebf\u5bbd\uff09 :param gradient: \u5141\u8bb8\u4f7f\u7528\u6e10\u53d8\u63cf\u8fb9\uff1b\u7f6e <code>False</code> \u53ef\u5f3a\u5236\u7eaf\u8272 :param gradient_id: \u6e10\u53d8\u5b9a\u4e49\u7684 id :param gradient_stop1: \u7b2c\u4e00\u4e2a stop \u7684\u4f4d\u7f6e\uff080-1\uff09 :param gradient_stop2: \u7b2c\u4e8c\u4e2a stop \u7684\u4f4d\u7f6e\uff080-1\uff09 :param extra: \u5176\u4f59\u5173\u952e\u5b57\u76f4\u63a5\u900f\u4f20\u7ed9 <code>rect()</code>\uff08\u4f8b\u5982 <code>id=\".Badge\"</code>\uff09</p> <p>:returns: <code>(insert, size, rx, ry)</code></p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\svg.py</code> <pre><code>def add_roundrect(\n    dwg,\n    x1,\n    y1,\n    x2,\n    y2,\n    radius,\n    radiusy=None,\n    *,\n    fill=\"transparent\",\n    fill_opacity=1,\n    outline=\"black\",\n    outline2=None,\n    outline_opacity=1,\n    outline2_opacity=1,\n    width=1,\n    gradient=True,\n    gradient_id=\"DButton.Border\",\n    gradient_stop1=0.9,\n    gradient_stop2=1.0,\n    **extra,\n) -&gt; Geometry:\n    \"\"\"\u5f80 svgwrite \u7684 ``Drawing`` \u91cc\u52a0\u4e00\u4e2a\u56db\u8fb9\u63cf\u8fb9\u90fd\u5b8c\u6574\u7684\u5706\u89d2\u77e9\u5f62\u3002\n\n    :param dwg: ``svgwrite.Drawing`` \u5185\u90e8\u7684\u753b\u5e03\u5bf9\u8c61\uff08\u901a\u5e38\u662f ``drawing[1]``\uff09\n    :param fill: \u586b\u5145\u8272\uff0c``\"transparent\"`` \u8868\u793a\u4e0d\u586b\u5145\n    :param fill_opacity: \u586b\u5145\u900f\u660e\u5ea6\n    :param outline: \u63cf\u8fb9\u8272\n    :param outline2: \u6e10\u53d8\u63cf\u8fb9\u7684\u7b2c\u4e8c\u4e2a\u989c\u8272\uff1b\u4e3a\u7a7a\u5219\u7528\u7eaf\u8272\u63cf\u8fb9\n    :param outline_opacity: \u63cf\u8fb9\u900f\u660e\u5ea6\n    :param outline2_opacity: \u6e10\u53d8\u63cf\u8fb9\u7b2c\u4e8c\u4e2a\u989c\u8272\u7684\u900f\u660e\u5ea6\n    :param width: \u63cf\u8fb9\u5bbd\u5ea6\uff08\u63cf\u8fb9\u4ee5\u8def\u5f84\u4e3a\u4e2d\u5fc3\u7ebf\uff0c\u51e0\u4f55\u4f1a\u81ea\u52a8\u5185\u7f29\u534a\u4e2a\u7ebf\u5bbd\uff09\n    :param gradient: \u5141\u8bb8\u4f7f\u7528\u6e10\u53d8\u63cf\u8fb9\uff1b\u7f6e ``False`` \u53ef\u5f3a\u5236\u7eaf\u8272\n    :param gradient_id: \u6e10\u53d8\u5b9a\u4e49\u7684 id\n    :param gradient_stop1: \u7b2c\u4e00\u4e2a stop \u7684\u4f4d\u7f6e\uff080-1\uff09\n    :param gradient_stop2: \u7b2c\u4e8c\u4e2a stop \u7684\u4f4d\u7f6e\uff080-1\uff09\n    :param extra: \u5176\u4f59\u5173\u952e\u5b57\u76f4\u63a5\u900f\u4f20\u7ed9 ``rect()``\uff08\u4f8b\u5982 ``id=\".Badge\"``\uff09\n\n    :returns: ``(insert, size, rx, ry)``\n    \"\"\"\n    insert, size, rx, ry = roundrect_geometry(\n        x1, y1, x2, y2, radius, radiusy, width\n    )\n\n    if gradient and outline2:\n        border = dwg.linearGradient(\n            start=(insert[0], insert[1]),\n            end=(insert[0], insert[1] + size[1]),\n            id=gradient_id,\n            gradientUnits=\"userSpaceOnUse\",\n        )\n        border.add_stop_color(gradient_stop1, outline, outline_opacity)\n        border.add_stop_color(gradient_stop2, outline2, outline2_opacity)\n        dwg.defs.add(border)\n        stroke = f\"url(#{border.get_id()})\"\n        stroke_opacity = 1\n    else:\n        stroke = outline\n        stroke_opacity = outline_opacity\n\n    dwg.add(\n        dwg.rect(\n            insert,\n            size,\n            rx,\n            ry,\n            fill=fill,\n            fill_opacity=fill_opacity,\n            stroke=stroke,\n            stroke_width=width,\n            stroke_opacity=stroke_opacity,\n            **extra,\n        )\n    )\n    return insert, size, rx, ry\n</code></pre>"},{"location":"api/tkdeft.svg.html#tkdeft.svg.roundrect_geometry","title":"<code>roundrect_geometry(x1, y1, x2, y2, radius, radiusy=None, stroke_width=1)</code>","text":"<p>\u6309\"\u63cf\u8fb9\u5c45\u4e2d\"\u89c4\u5219\u628a\u5706\u89d2\u77e9\u5f62\u51e0\u4f55\u5185\u7f29\u3002</p> <p>\u5bf9\u9000\u5316\u5c3a\u5bf8\u505a\u4e86\u4fdd\u62a4\uff1a\u63a7\u4ef6\u5728\u5e03\u5c40\u5b8c\u6210\u4e4b\u524d\u5bbd\u9ad8\u53ef\u80fd\u662f 0\u30011 \u751a\u81f3\u8d1f\u6570 \uff08<code>FluSlider</code> \u6784\u9020\u65f6 <code>winfo_width()</code> \u5c31\u662f 1\uff09\u3002SVG \u91cc <code>width</code> / <code>height</code> \u4e00\u65e6 <code>&lt;= 0</code>\uff0ctksvg \u4f1a\u76f4\u63a5\u629b <code>couldn't recognize image data</code>\uff0c\u6240\u4ee5\u8fd9\u91cc\u628a\u8fb9\u957f\u548c\u5185\u7f29\u91cf\u90fd\u5939\u5230\u5b89\u5168\u8303\u56f4\u3002</p> <p>\u8fd4\u56de\uff1a</p> \u7c7b\u578b \u63cf\u8ff0 <code>Geometry</code> <p><code>(insert, size, rx, ry)</code>\uff0c\u53ef\u76f4\u63a5\u5582\u7ed9 <code>svgwrite</code> \u7684 <code>rect()</code>\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\svg.py</code> <pre><code>def roundrect_geometry(\n    x1, y1, x2, y2, radius, radiusy=None, stroke_width=1\n) -&gt; Geometry:\n    \"\"\"\u6309\"\u63cf\u8fb9\u5c45\u4e2d\"\u89c4\u5219\u628a\u5706\u89d2\u77e9\u5f62\u51e0\u4f55\u5185\u7f29\u3002\n\n    \u5bf9\u9000\u5316\u5c3a\u5bf8\u505a\u4e86\u4fdd\u62a4\uff1a\u63a7\u4ef6\u5728\u5e03\u5c40\u5b8c\u6210\u4e4b\u524d\u5bbd\u9ad8\u53ef\u80fd\u662f 0\u30011 \u751a\u81f3\u8d1f\u6570\n    \uff08``FluSlider`` \u6784\u9020\u65f6 ``winfo_width()`` \u5c31\u662f 1\uff09\u3002SVG \u91cc\n    ``width`` / ``height`` \u4e00\u65e6 ``&lt;= 0``\uff0ctksvg \u4f1a\u76f4\u63a5\u629b\n    ``couldn't recognize image data``\uff0c\u6240\u4ee5\u8fd9\u91cc\u628a\u8fb9\u957f\u548c\u5185\u7f29\u91cf\u90fd\u5939\u5230\u5b89\u5168\u8303\u56f4\u3002\n\n    Returns:\n        ``(insert, size, rx, ry)``\uff0c\u53ef\u76f4\u63a5\u5582\u7ed9 ``svgwrite`` \u7684 ``rect()``\u3002\n    \"\"\"\n    # \u8fb9\u957f\u4e0b\u9650 0.5\uff1a\u65e2\u80fd\u88ab tksvg \u63a5\u53d7\uff0c\u89c6\u89c9\u4e0a\u4e5f\u4e0d\u53ef\u89c1\n    w = max(0.5, float(x2) - float(x1))\n    h = max(0.5, float(y2) - float(y1))\n\n    inset = (float(stroke_width) / 2.0) if stroke_width else 0.0\n    # \u5185\u7f29\u91cf\u6700\u591a\u7528\u6389\u4e00\u534a\u53ef\u7528\u7a7a\u95f4\uff0c\u5426\u5219\u540c\u6837\u4f1a\u9000\u5316\u6210\u975e\u6b63\u5c3a\u5bf8\n    inset = min(inset, max(0.0, (w - 0.5) / 2.0), max(0.0, (h - 0.5) / 2.0))\n\n    rx = max(0.0, float(radius or 0) - inset)\n    ry = max(0.0, float(radiusy if radiusy else radius or 0) - inset)\n    insert = (x1 + inset, y1 + inset)\n    size = (w - 2 * inset, h - 2 * inset)\n    return insert, size, rx, ry\n</code></pre>"},{"location":"api/tkdeft.utility.html","title":"utility \u00b7 \u5b57\u4f53\u7b49\u5de5\u5177","text":""},{"location":"api/tkdeft.windows.canvas.html","title":"windows.canvas \u00b7 \u5e26\u7ed8\u5236\u7684\u753b\u5e03","text":"<p>\u5e26\u7ed8\u5236\u80fd\u529b\u7684 Canvas\u3002</p> <p>\u672c\u6a21\u5757\u63d0\u4f9b\u4e24\u6761\u5e76\u5b58\u7684\u7ed8\u5236\u8def\u5f84\uff1a</p> <ul> <li>\u6805\u683c\u5feb\u901f\u8def\u5f84\uff08:meth:<code>DCanvas.create_roundrect_raster</code>\uff09\uff1a\u5f53\u5f53\u524d\u5f15\u64ce\u662f   skia / pillow / cairo \u65f6\uff0c\u76f4\u63a5\u62ff\u8fdb\u7a0b\u5185\u6e32\u67d3\u51fa\u7684\u4f4d\u56fe\u5efa canvas item\uff0c   \u4e0d\u5199\u4e34\u65f6\u6587\u4ef6\u3001\u4e0d\u89e3\u6790 SVG\uff0c\u5e76\u4e14\u7ed3\u679c\u6309 spec \u7f13\u5b58\u3001\u53ef\u88ab\u591a\u4e2a\u63a7\u4ef6\u5171\u4eab\u3002</li> <li>SVG \u517c\u5bb9\u8def\u5f84\uff08:meth:<code>DCanvas.create_round_rectangle</code>\uff09\uff1a\u4fdd\u6301\u539f\u6837\uff0c   \u4f9b tksvg / wand \u5f15\u64ce\u548c\u81ea\u5b9a\u4e49\u7ed8\u5236\u4ee3\u7801\u4f7f\u7528\u3002</li> </ul> <p>\u53e6\u5916\u4fee\u6389\u4e86\u4e00\u4e2a\u7ecf\u5178\u9677\u9631\uff1a<code>PhotoImage</code> \u5fc5\u987b\u7531 Python \u4fa7\u6301\u6709\u5f15\u7528\uff0c \u5426\u5219\u4e00\u65e6\u88ab\u5783\u573e\u56de\u6536\uff0c\u753b\u5e03\u4e0a\u5bf9\u5e94\u7684 item \u4f1a\u53d8\u6210\u7a7a\u767d\u3002\u65e7\u4ee3\u7801\u53ea\u7528 <code>self._tkimg</code> \u4fdd\u5b58\"\u6700\u540e\u4e00\u5f20\"\uff0c\u540c\u4e00\u753b\u5e03\u4e0a\u6709\u591a\u5f20\u56fe\u7247\u65f6\u5176\u4f59\u90fd\u4f1a\u53d8\u7a7a\u767d\u3002</p>"},{"location":"api/tkdeft.windows.canvas.html#tkdeft.windows.canvas.DCanvas","title":"<code>DCanvas</code>","text":"<p>               Bases: <code>Canvas</code></p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\windows\\canvas.py</code> <pre><code>class DCanvas(Canvas):\n    from .draw import DSvgDraw\n\n    draw = DSvgDraw\n\n    def __init__(self, *args, border=0, highlightthickness=0, **kwargs):\n        super().__init__(*args, border=border, highlightthickness=0, **kwargs)\n\n        self.svgdraw = self.draw()\n        # \u628a\u672c\u753b\u5e03\u4f5c\u4e3a master \u4ea4\u7ed9\u7ed8\u56fe\u540e\u7aef\uff0c\u907f\u514d\u56fe\u7247\u6302\u5230\u522b\u7684 Tk \u89e3\u91ca\u5668\u4e0a\n        if hasattr(self.svgdraw, \"master\"):\n            self.svgdraw.master = self\n        #: canvas item id -&gt; PhotoImage\uff0c\u9632\u6b62\u56fe\u7247\u88ab GC \u540e\u753b\u9762\u53d8\u7a7a\u767d\n        self._photo_refs = {}\n\n        self.bind(\"&lt;Destroy&gt;\", self._event_destroy_draw, add=\"+\")\n\n    # ------------------------------------------------------------------\n    # \u56fe\u7247\u5f15\u7528\u7ba1\u7406\n    # ------------------------------------------------------------------\n    def _keep_photo(self, item, photo):\n        \"\"\"\u6301\u6709 ``PhotoImage`` \u5f15\u7528\uff0c\u5e76\u5728\u5fc5\u8981\u65f6\u6e05\u7406\u5df2\u5220\u9664 item \u7684\u5f15\u7528\u3002\"\"\"\n        self._photo_refs[item] = photo\n        if len(self._photo_refs) &gt; _PHOTO_PRUNE_THRESHOLD:\n            self._prune_photo_refs()\n        return item\n\n    def _prune_photo_refs(self):\n        stale = []\n        for item in self._photo_refs:\n            try:\n                self.type(item)\n            except Exception:\n                stale.append(item)\n        for item in stale:\n            self._photo_refs.pop(item, None)\n\n    def _event_destroy_draw(self, event=None):\n        if event is not None and getattr(event, \"widget\", None) is not self:\n            return\n        self._photo_refs.clear()\n        cleanup = getattr(self.svgdraw, \"cleanup\", None)\n        if callable(cleanup):\n            cleanup()\n\n    # ------------------------------------------------------------------\n    # \u6805\u683c\u5feb\u901f\u8def\u5f84\n    # ------------------------------------------------------------------\n    def create_roundrect_raster(\n        self,\n        x1,\n        y1,\n        x2,\n        y2,\n        r1,\n        r2=None,\n        *args,\n        fill=\"transparent\",\n        fill_opacity=1,\n        outline=\"black\",\n        outline2=None,\n        outline_opacity=1,\n        outline2_opacity=1,\n        width=1,\n        gradient_stop1=0.9,\n        gradient_stop2=1.0,\n        **image_kwargs,\n    ) -&gt; Optional[int]:\n        \"\"\"\u5c1d\u8bd5\u7528\u5f53\u524d\u6805\u683c\u5f15\u64ce\u76f4\u63a5\u7ed8\u5236\u5706\u89d2\u77e9\u5f62\u3002\n\n        :returns: \u6210\u529f\u65f6\u8fd4\u56de canvas item id\uff1b\u5f53\u524d\u5f15\u64ce\u662f SVG \u7cfb\u3001\u5c3a\u5bf8\u975e\u6cd5\u6216\n            \u6e32\u67d3\u5931\u8d25\u65f6\u8fd4\u56de ``None``\uff0c\u8c03\u7528\u65b9\u5e94\u56de\u9000\u5230\u539f\u6709\u7684 SVG \u8def\u5f84\u3002\n        \"\"\"\n        if not get_engine().is_raster:\n            return None\n\n        w = int(round(x2 - x1))\n        h = int(round(y2 - y1))\n        if w &lt;= 0 or h &lt;= 0:\n            return None\n\n        spec = RoundRectSpec(\n            width=w,\n            height=h,\n            rx=float(r1 or 0),\n            ry=None if r2 is None else float(r2),\n            fill=fill,\n            fill_opacity=parse_opacity(fill_opacity),\n            outline=outline,\n            outline_opacity=parse_opacity(outline_opacity),\n            outline2=outline2,\n            outline2_opacity=parse_opacity(outline2_opacity),\n            outline_width=float(width or 0),\n            gradient_stop1=float(gradient_stop1),\n            gradient_stop2=float(gradient_stop2),\n        )\n        photo = render_roundrect(spec, self)\n        if photo is None:\n            return None\n\n        item = self.create_image(x1, y1, anchor=\"nw\", image=photo, *args, **image_kwargs)\n        return self._keep_photo(item, photo)\n\n    # ------------------------------------------------------------------\n    # \u6ed1\u5757\u4e13\u7528\u56fe\u5143\u7684\u6805\u683c\u5feb\u901f\u8def\u5f84\n    # ------------------------------------------------------------------\n    def create_track_raster(\n        self,\n        x1,\n        y1,\n        width,\n        height,\n        width2,\n        radius=3,\n        track_fill=\"transparent\",\n        track_opacity=1,\n        rail_fill=\"transparent\",\n        rail_opacity=1,\n        **image_kwargs,\n    ):\n        \"\"\"\u6ed1\u5757\u7684\u8fdb\u5ea6\u6761\u69fd\uff1b\u4e0d\u652f\u6301\u65f6\u8fd4\u56de ``None``\u3002\"\"\"\n        if not get_engine().is_raster:\n            return None\n\n        w = int(round(width))\n        h = int(round(height))\n        if w &lt;= 0 or h &lt;= 0:\n            return None\n\n        spec = TrackSpec(\n            width=w,\n            height=h,\n            width2=float(width2),\n            radius=float(radius or 0),\n            track_fill=track_fill,\n            track_opacity=parse_opacity(track_opacity),\n            rail_fill=rail_fill,\n            rail_opacity=parse_opacity(rail_opacity),\n        )\n        photo = render_track(spec, self)\n        if photo is None:\n            return None\n        item = self.create_image(x1, y1, anchor=\"nw\", image=photo, **image_kwargs)\n        return self._keep_photo(item, photo)\n\n    def create_thumb_raster(\n        self,\n        x1,\n        y1,\n        width,\n        height,\n        r1,\n        r2,\n        fill=\"transparent\",\n        fill_opacity=1,\n        outline=\"transparent\",\n        outline_opacity=1,\n        outline2=\"transparent\",\n        outline2_opacity=1,\n        inner_fill=\"transparent\",\n        inner_fill_opacity=1,\n        **image_kwargs,\n    ):\n        \"\"\"\u6ed1\u5757\u7684\u5706\u5f62\u628a\u624b\uff1b\u4e0d\u652f\u6301\u65f6\u8fd4\u56de ``None``\u3002\"\"\"\n        if not get_engine().is_raster:\n            return None\n\n        w = int(round(width))\n        h = int(round(height))\n        if w &lt;= 0 or h &lt;= 0:\n            return None\n\n        spec = ThumbSpec(\n            width=w,\n            height=h,\n            r1=float(r1),\n            r2=float(r2),\n            fill=fill,\n            fill_opacity=parse_opacity(fill_opacity),\n            outline=outline,\n            outline_opacity=parse_opacity(outline_opacity),\n            outline2=outline2,\n            outline2_opacity=parse_opacity(outline2_opacity),\n            inner_fill=inner_fill,\n            inner_fill_opacity=parse_opacity(inner_fill_opacity),\n        )\n        photo = render_thumb(spec, self)\n        if photo is None:\n            return None\n        item = self.create_image(x1, y1, anchor=\"nw\", image=photo, **image_kwargs)\n        return self._keep_photo(item, photo)\n\n    # ------------------------------------------------------------------\n    # SVG \u517c\u5bb9\u8def\u5f84\n    # ------------------------------------------------------------------\n    def create_round_rectangle(\n        self, x1, y1, x2, y2, r1, r2=None, fill=\"transparent\",\n        outline=\"black\", width=1,\n    ):\n        self._img = self.svgdraw.create_roundrect(\n            x1, y1, x2, y2, r1, r2, fill=fill, outline=outline, width=width\n        )\n        self._tkimg = self.svgdraw.create_svg_image(self._img)\n        item = self.create_image(x1, y1, anchor=\"nw\", image=self._tkimg)\n        return self._keep_photo(item, self._tkimg)\n\n    create_roundrect = create_round_rectangle\n</code></pre>"},{"location":"api/tkdeft.windows.canvas.html#tkdeft.windows.canvas.DCanvas.create_roundrect_raster","title":"<code>create_roundrect_raster(x1, y1, x2, y2, r1, r2=None, *args, fill='transparent', fill_opacity=1, outline='black', outline2=None, outline_opacity=1, outline2_opacity=1, width=1, gradient_stop1=0.9, gradient_stop2=1.0, **image_kwargs)</code>","text":"<p>\u5c1d\u8bd5\u7528\u5f53\u524d\u6805\u683c\u5f15\u64ce\u76f4\u63a5\u7ed8\u5236\u5706\u89d2\u77e9\u5f62\u3002</p> <p>:returns: \u6210\u529f\u65f6\u8fd4\u56de canvas item id\uff1b\u5f53\u524d\u5f15\u64ce\u662f SVG \u7cfb\u3001\u5c3a\u5bf8\u975e\u6cd5\u6216     \u6e32\u67d3\u5931\u8d25\u65f6\u8fd4\u56de <code>None</code>\uff0c\u8c03\u7528\u65b9\u5e94\u56de\u9000\u5230\u539f\u6709\u7684 SVG \u8def\u5f84\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\windows\\canvas.py</code> <pre><code>def create_roundrect_raster(\n    self,\n    x1,\n    y1,\n    x2,\n    y2,\n    r1,\n    r2=None,\n    *args,\n    fill=\"transparent\",\n    fill_opacity=1,\n    outline=\"black\",\n    outline2=None,\n    outline_opacity=1,\n    outline2_opacity=1,\n    width=1,\n    gradient_stop1=0.9,\n    gradient_stop2=1.0,\n    **image_kwargs,\n) -&gt; Optional[int]:\n    \"\"\"\u5c1d\u8bd5\u7528\u5f53\u524d\u6805\u683c\u5f15\u64ce\u76f4\u63a5\u7ed8\u5236\u5706\u89d2\u77e9\u5f62\u3002\n\n    :returns: \u6210\u529f\u65f6\u8fd4\u56de canvas item id\uff1b\u5f53\u524d\u5f15\u64ce\u662f SVG \u7cfb\u3001\u5c3a\u5bf8\u975e\u6cd5\u6216\n        \u6e32\u67d3\u5931\u8d25\u65f6\u8fd4\u56de ``None``\uff0c\u8c03\u7528\u65b9\u5e94\u56de\u9000\u5230\u539f\u6709\u7684 SVG \u8def\u5f84\u3002\n    \"\"\"\n    if not get_engine().is_raster:\n        return None\n\n    w = int(round(x2 - x1))\n    h = int(round(y2 - y1))\n    if w &lt;= 0 or h &lt;= 0:\n        return None\n\n    spec = RoundRectSpec(\n        width=w,\n        height=h,\n        rx=float(r1 or 0),\n        ry=None if r2 is None else float(r2),\n        fill=fill,\n        fill_opacity=parse_opacity(fill_opacity),\n        outline=outline,\n        outline_opacity=parse_opacity(outline_opacity),\n        outline2=outline2,\n        outline2_opacity=parse_opacity(outline2_opacity),\n        outline_width=float(width or 0),\n        gradient_stop1=float(gradient_stop1),\n        gradient_stop2=float(gradient_stop2),\n    )\n    photo = render_roundrect(spec, self)\n    if photo is None:\n        return None\n\n    item = self.create_image(x1, y1, anchor=\"nw\", image=photo, *args, **image_kwargs)\n    return self._keep_photo(item, photo)\n</code></pre>"},{"location":"api/tkdeft.windows.canvas.html#tkdeft.windows.canvas.DCanvas.create_thumb_raster","title":"<code>create_thumb_raster(x1, y1, width, height, r1, r2, fill='transparent', fill_opacity=1, outline='transparent', outline_opacity=1, outline2='transparent', outline2_opacity=1, inner_fill='transparent', inner_fill_opacity=1, **image_kwargs)</code>","text":"<p>\u6ed1\u5757\u7684\u5706\u5f62\u628a\u624b\uff1b\u4e0d\u652f\u6301\u65f6\u8fd4\u56de <code>None</code>\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\windows\\canvas.py</code> <pre><code>def create_thumb_raster(\n    self,\n    x1,\n    y1,\n    width,\n    height,\n    r1,\n    r2,\n    fill=\"transparent\",\n    fill_opacity=1,\n    outline=\"transparent\",\n    outline_opacity=1,\n    outline2=\"transparent\",\n    outline2_opacity=1,\n    inner_fill=\"transparent\",\n    inner_fill_opacity=1,\n    **image_kwargs,\n):\n    \"\"\"\u6ed1\u5757\u7684\u5706\u5f62\u628a\u624b\uff1b\u4e0d\u652f\u6301\u65f6\u8fd4\u56de ``None``\u3002\"\"\"\n    if not get_engine().is_raster:\n        return None\n\n    w = int(round(width))\n    h = int(round(height))\n    if w &lt;= 0 or h &lt;= 0:\n        return None\n\n    spec = ThumbSpec(\n        width=w,\n        height=h,\n        r1=float(r1),\n        r2=float(r2),\n        fill=fill,\n        fill_opacity=parse_opacity(fill_opacity),\n        outline=outline,\n        outline_opacity=parse_opacity(outline_opacity),\n        outline2=outline2,\n        outline2_opacity=parse_opacity(outline2_opacity),\n        inner_fill=inner_fill,\n        inner_fill_opacity=parse_opacity(inner_fill_opacity),\n    )\n    photo = render_thumb(spec, self)\n    if photo is None:\n        return None\n    item = self.create_image(x1, y1, anchor=\"nw\", image=photo, **image_kwargs)\n    return self._keep_photo(item, photo)\n</code></pre>"},{"location":"api/tkdeft.windows.canvas.html#tkdeft.windows.canvas.DCanvas.create_track_raster","title":"<code>create_track_raster(x1, y1, width, height, width2, radius=3, track_fill='transparent', track_opacity=1, rail_fill='transparent', rail_opacity=1, **image_kwargs)</code>","text":"<p>\u6ed1\u5757\u7684\u8fdb\u5ea6\u6761\u69fd\uff1b\u4e0d\u652f\u6301\u65f6\u8fd4\u56de <code>None</code>\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\windows\\canvas.py</code> <pre><code>def create_track_raster(\n    self,\n    x1,\n    y1,\n    width,\n    height,\n    width2,\n    radius=3,\n    track_fill=\"transparent\",\n    track_opacity=1,\n    rail_fill=\"transparent\",\n    rail_opacity=1,\n    **image_kwargs,\n):\n    \"\"\"\u6ed1\u5757\u7684\u8fdb\u5ea6\u6761\u69fd\uff1b\u4e0d\u652f\u6301\u65f6\u8fd4\u56de ``None``\u3002\"\"\"\n    if not get_engine().is_raster:\n        return None\n\n    w = int(round(width))\n    h = int(round(height))\n    if w &lt;= 0 or h &lt;= 0:\n        return None\n\n    spec = TrackSpec(\n        width=w,\n        height=h,\n        width2=float(width2),\n        radius=float(radius or 0),\n        track_fill=track_fill,\n        track_opacity=parse_opacity(track_opacity),\n        rail_fill=rail_fill,\n        rail_opacity=parse_opacity(rail_opacity),\n    )\n    photo = render_track(spec, self)\n    if photo is None:\n        return None\n    item = self.create_image(x1, y1, anchor=\"nw\", image=photo, **image_kwargs)\n    return self._keep_photo(item, photo)\n</code></pre>"},{"location":"api/tkdeft.windows.draw.html","title":"windows.draw \u00b7 \u7ed8\u5236\u540e\u7aef","text":"<p>tkdeft \u7684\u7ed8\u5236\u540e\u7aef\u3002</p> <p>\u672c\u6a21\u5757\u540c\u65f6\u627f\u62c5\u4e24\u4ef6\u4e8b\uff1a</p> <ol> <li> <p>SVG \u540e\u7aef\uff08<code>DSvgDraw</code>\uff09\uff1a\u6cbf\u7528 svgwrite \u751f\u6210 SVG\u3001\u518d\u7528 tksvg / Wand \u6805\u683c\u5316\u3002    \u8fd9\u6761\u8def\u5f84\u4fdd\u6301\u5411\u540e\u517c\u5bb9\uff0c\u4f46\u4fee\u6389\u4e86\u4e24\u4e2a\u771f\u5b9e\u7f3a\u9677\uff1a</p> </li> <li> <p><code>temppath()</code> \u65e7\u5b9e\u73b0\u6bcf\u6b21\u90fd <code>mkstemp()</code> \u4e00\u4e2a\u65b0\u6587\u4ef6\u4e14 \u4ece\u4e0d\u5173\u95ed\u8fd4\u56de\u7684 fd\uff0c      \u4e8e\u662f\u6bcf\u7ed8\u5236\u4e00\u5e27\u5c31\u6cc4\u6f0f\u4e00\u4e2a\u6587\u4ef6\u63cf\u8ff0\u7b26\u3001\u5e76\u5728\u7cfb\u7edf\u4e34\u65f6\u76ee\u5f55\u91cc\u7559\u4e0b\u4e00\u4e2a\u6b8b\u7559\u6587\u4ef6\u3002      \u73b0\u5728\u6539\u4e3a\"\u6bcf\u4e2a\u7ed8\u5236\u5bf9\u8c61\u590d\u7528\u4e00\u4e2a scratch \u6587\u4ef6\"\uff0c\u5e76\u652f\u6301 :meth:<code>DDraw.cleanup</code> \u56de\u6536\u3002</p> </li> <li> <p>tksvg \u73b0\u5728\u4f18\u5148\u7528 <code>data=</code> \u76f4\u63a5\u5403 SVG \u6e90\u7801\uff0c\u907f\u514d\"\u5199\u76d8\u518d\u8bfb\u56de\u6765\"\u3002</p> </li> <li> <p>\u6805\u683c\u5f15\u64ce\u5165\u53e3\uff1a\u771f\u6b63\u7684\u52a0\u901f\u5728 :mod:<code>tkdeft.engines</code>\u3002</p> </li> </ol>"},{"location":"api/tkdeft.windows.draw.html#tkdeft.windows.draw.DDraw","title":"<code>DDraw</code>","text":"<p>               Bases: <code>object</code></p> <p>\u6700\u57fa\u7840\u7684\u7ed8\u5236\u540e\u7aef\uff1a\u628a SVG/\u5176\u5b83\u77e2\u91cf\u7d20\u6750\u53d8\u6210 tkinter \u53ef\u7528\u7684\u56fe\u7247\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\windows\\draw.py</code> <pre><code>class DDraw(object):\n    \"\"\"\u6700\u57fa\u7840\u7684\u7ed8\u5236\u540e\u7aef\uff1a\u628a SVG/\u5176\u5b83\u77e2\u91cf\u7d20\u6750\u53d8\u6210 tkinter \u53ef\u7528\u7684\u56fe\u7247\u3002\"\"\"\n\n    #: \u521b\u5efa\u56fe\u7247\u65f6\u4f7f\u7528\u7684 Tk \u4e3b\u63a7\u4ef6\uff08\u7531 :class:`~tkdeft.windows.canvas.DCanvas` \u6ce8\u5165\uff09\u3002\n    #: \u65e7\u5b9e\u73b0\u4e0d\u4f20 master\uff0c\u591a Tk \u89e3\u91ca\u5668\u573a\u666f\u4e0b\u56fe\u7247\u4f1a\u6302\u5230\u9519\u8bef\u7684\u89e3\u91ca\u5668\u4e0a\u3002\n    master = None\n\n    def create_svg_image(self, path, path2=None, way=0):\n        \"\"\"\u628a SVG\uff08\u8def\u5f84\u6216\u6e90\u7801\uff09\u6805\u683c\u5316\u6210 ``PhotoImage``\u3002\n\n        ``way`` \u6cbf\u7528\u5386\u53f2\u8bed\u4e49\uff1a``1`` \u8d70 Wand\uff0c**\u5176\u4f59\u4efb\u4f55\u53d6\u503c\u90fd\u8868\u793a tksvg**\u3002\n\n        \u8fd9\u91cc\u523b\u610f\u4e0d\u505a\u4e25\u683c\u6821\u9a8c\uff1a\u8c03\u7528\u65b9\u666e\u904d\u5199\u4f5c\n        ``create_svg_image(img, tmp, way=get_renderer())``\uff0c\u800c\u5f53\u542f\u7528\n        skia / pillow / cairo \u7b49\u6805\u683c\u5f15\u64ce\u65f6 ``get_renderer()`` \u4f1a\u8fd4\u56de 2/3/4\u3002\n        \u8fd9\u6761\u56de\u9000\u8def\u5f84\u53ea\u5728\u6805\u683c\u5f15\u64ce\u5a49\u62d2\u7ed8\u5236\u65f6\u624d\u4f1a\u8d70\u5230\uff08\u4f8b\u5982\u63a7\u4ef6\u5c3a\u5bf8\u5c1a\u672a\u786e\u5b9a\uff09\uff0c\n        \u6b64\u65f6\u7528\u4e00\u4e2a\u53ef\u7528\u7684\u540e\u7aef\u628a\u4e8b\u60c5\u505a\u5b8c\uff0c\u8fdc\u597d\u8fc7\u629b\u5f02\u5e38\u8ba9\u6574\u4e2a\u63a7\u4ef6\u6784\u9020\u5931\u8d25\u3002\n        \"\"\"\n        if way == 1:\n            return self.create_wand_image(path, path2)\n        return self.create_tksvg_image(path)\n\n    def create_tksvg_image(self, path):\n        \"\"\"\u628a SVG \u53d8\u6210 ``PhotoImage``\u3002\n\n        ``path`` \u65e2\u53ef\u4ee5\u662f SVG \u6587\u4ef6\u8def\u5f84\uff0c\u4e5f\u53ef\u4ee5\u76f4\u63a5\u662f SVG \u6e90\u7801\u5b57\u7b26\u4e32\n        \uff08\u4ee5 ``&lt;`` \u5f00\u5934\uff09\u2014\u2014\u540e\u8005\u8d70 tksvg \u7684 ``data=`` \u901a\u9053\uff0c**\u5b8c\u5168\u4e0d\u78b0\u78c1\u76d8**\u3002\n        \"\"\"\n        from tksvg import SvgImage\n\n        if isinstance(path, str) and path.lstrip().startswith(\"&lt;\"):\n            if self.master is not None:\n                return SvgImage(data=path, master=self.master)\n            return SvgImage(data=path)\n        if self.master is not None:\n            return SvgImage(file=path, master=self.master)\n        return SvgImage(file=path)\n\n    def create_tk_image(self, path):\n        from PIL.Image import open as pil_open\n        from PIL.ImageTk import PhotoImage\n\n        image = pil_open(path)\n        self.tkimage = PhotoImage(image=image, master=self.master)\n        return self.tkimage\n\n    def create_wand_image(self, input_path, output_path=None):\n        from tkinter import PhotoImage\n\n        from wand.exceptions import ImageError\n        from wand.image import Image\n\n        # \u5386\u53f2\u4e0a wand \u8def\u5f84\u8981\u6c42\u8c03\u7528\u65b9\u5fc5\u987b\u4f20 temppath2\uff08\u8f93\u51fa PNG \u8def\u5f84\uff09\uff0c\n        # \u6f0f\u4f20\u65f6\u4f1a\u5728 img.save(filename=None) \u629b\u51fa\u96be\u4ee5\u7406\u89e3\u7684\n        # \"TypeError: expected an argument\"\u3002\u8fd9\u91cc\u8865\u4e00\u4e2a\u81ea\u7ba1\u7684\u4e34\u65f6\u8f93\u51fa\u8def\u5f84\u3002\n        if not output_path:\n            scratch = getattr(self, \"scratch_path\", None)\n            if callable(scratch):\n                output_path = scratch(\".png\")\n            else:  # pragma: no cover - \u6781\u7b80\u5b50\u7c7b\u515c\u5e95\n                from os import close\n                from tempfile import mkstemp\n\n                fd, output_path = mkstemp(suffix=\".png\", prefix=\"tkdeft.wand.\")\n                close(fd)\n\n        try:\n            with Image(filename=input_path, background=\"transparent\") as img:\n                img.format = \"png\"\n                img.save(filename=output_path)\n\n            if self.master is not None:\n                photoimg = PhotoImage(file=output_path, master=self.master)\n            else:\n                photoimg = PhotoImage(file=output_path)\n        except ImageError:\n            return None\n        else:\n            return photoimg\n</code></pre>"},{"location":"api/tkdeft.windows.draw.html#tkdeft.windows.draw.DDraw.create_svg_image","title":"<code>create_svg_image(path, path2=None, way=0)</code>","text":"<p>\u628a SVG\uff08\u8def\u5f84\u6216\u6e90\u7801\uff09\u6805\u683c\u5316\u6210 <code>PhotoImage</code>\u3002</p> <p><code>way</code> \u6cbf\u7528\u5386\u53f2\u8bed\u4e49\uff1a<code>1</code> \u8d70 Wand\uff0c\u5176\u4f59\u4efb\u4f55\u53d6\u503c\u90fd\u8868\u793a tksvg\u3002</p> <p>\u8fd9\u91cc\u523b\u610f\u4e0d\u505a\u4e25\u683c\u6821\u9a8c\uff1a\u8c03\u7528\u65b9\u666e\u904d\u5199\u4f5c <code>create_svg_image(img, tmp, way=get_renderer())</code>\uff0c\u800c\u5f53\u542f\u7528 skia / pillow / cairo \u7b49\u6805\u683c\u5f15\u64ce\u65f6 <code>get_renderer()</code> \u4f1a\u8fd4\u56de 2/3/4\u3002 \u8fd9\u6761\u56de\u9000\u8def\u5f84\u53ea\u5728\u6805\u683c\u5f15\u64ce\u5a49\u62d2\u7ed8\u5236\u65f6\u624d\u4f1a\u8d70\u5230\uff08\u4f8b\u5982\u63a7\u4ef6\u5c3a\u5bf8\u5c1a\u672a\u786e\u5b9a\uff09\uff0c \u6b64\u65f6\u7528\u4e00\u4e2a\u53ef\u7528\u7684\u540e\u7aef\u628a\u4e8b\u60c5\u505a\u5b8c\uff0c\u8fdc\u597d\u8fc7\u629b\u5f02\u5e38\u8ba9\u6574\u4e2a\u63a7\u4ef6\u6784\u9020\u5931\u8d25\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\windows\\draw.py</code> <pre><code>def create_svg_image(self, path, path2=None, way=0):\n    \"\"\"\u628a SVG\uff08\u8def\u5f84\u6216\u6e90\u7801\uff09\u6805\u683c\u5316\u6210 ``PhotoImage``\u3002\n\n    ``way`` \u6cbf\u7528\u5386\u53f2\u8bed\u4e49\uff1a``1`` \u8d70 Wand\uff0c**\u5176\u4f59\u4efb\u4f55\u53d6\u503c\u90fd\u8868\u793a tksvg**\u3002\n\n    \u8fd9\u91cc\u523b\u610f\u4e0d\u505a\u4e25\u683c\u6821\u9a8c\uff1a\u8c03\u7528\u65b9\u666e\u904d\u5199\u4f5c\n    ``create_svg_image(img, tmp, way=get_renderer())``\uff0c\u800c\u5f53\u542f\u7528\n    skia / pillow / cairo \u7b49\u6805\u683c\u5f15\u64ce\u65f6 ``get_renderer()`` \u4f1a\u8fd4\u56de 2/3/4\u3002\n    \u8fd9\u6761\u56de\u9000\u8def\u5f84\u53ea\u5728\u6805\u683c\u5f15\u64ce\u5a49\u62d2\u7ed8\u5236\u65f6\u624d\u4f1a\u8d70\u5230\uff08\u4f8b\u5982\u63a7\u4ef6\u5c3a\u5bf8\u5c1a\u672a\u786e\u5b9a\uff09\uff0c\n    \u6b64\u65f6\u7528\u4e00\u4e2a\u53ef\u7528\u7684\u540e\u7aef\u628a\u4e8b\u60c5\u505a\u5b8c\uff0c\u8fdc\u597d\u8fc7\u629b\u5f02\u5e38\u8ba9\u6574\u4e2a\u63a7\u4ef6\u6784\u9020\u5931\u8d25\u3002\n    \"\"\"\n    if way == 1:\n        return self.create_wand_image(path, path2)\n    return self.create_tksvg_image(path)\n</code></pre>"},{"location":"api/tkdeft.windows.draw.html#tkdeft.windows.draw.DDraw.create_tksvg_image","title":"<code>create_tksvg_image(path)</code>","text":"<p>\u628a SVG \u53d8\u6210 <code>PhotoImage</code>\u3002</p> <p><code>path</code> \u65e2\u53ef\u4ee5\u662f SVG \u6587\u4ef6\u8def\u5f84\uff0c\u4e5f\u53ef\u4ee5\u76f4\u63a5\u662f SVG \u6e90\u7801\u5b57\u7b26\u4e32 \uff08\u4ee5 <code>&lt;</code> \u5f00\u5934\uff09\u2014\u2014\u540e\u8005\u8d70 tksvg \u7684 <code>data=</code> \u901a\u9053\uff0c\u5b8c\u5168\u4e0d\u78b0\u78c1\u76d8\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\windows\\draw.py</code> <pre><code>def create_tksvg_image(self, path):\n    \"\"\"\u628a SVG \u53d8\u6210 ``PhotoImage``\u3002\n\n    ``path`` \u65e2\u53ef\u4ee5\u662f SVG \u6587\u4ef6\u8def\u5f84\uff0c\u4e5f\u53ef\u4ee5\u76f4\u63a5\u662f SVG \u6e90\u7801\u5b57\u7b26\u4e32\n    \uff08\u4ee5 ``&lt;`` \u5f00\u5934\uff09\u2014\u2014\u540e\u8005\u8d70 tksvg \u7684 ``data=`` \u901a\u9053\uff0c**\u5b8c\u5168\u4e0d\u78b0\u78c1\u76d8**\u3002\n    \"\"\"\n    from tksvg import SvgImage\n\n    if isinstance(path, str) and path.lstrip().startswith(\"&lt;\"):\n        if self.master is not None:\n            return SvgImage(data=path, master=self.master)\n        return SvgImage(data=path)\n    if self.master is not None:\n        return SvgImage(file=path, master=self.master)\n    return SvgImage(file=path)\n</code></pre>"},{"location":"api/tkdeft.windows.draw.html#tkdeft.windows.draw.DSvgDraw","title":"<code>DSvgDraw</code>","text":"<p>               Bases: <code>DDraw</code></p> <p>svgwrite \u7ed8\u56fe\u540e\u7aef\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\windows\\draw.py</code> <pre><code>class DSvgDraw(DDraw):\n    \"\"\"svgwrite \u7ed8\u56fe\u540e\u7aef\u3002\"\"\"\n\n    #: \u590d\u7528\u7684\u4e34\u65f6\u6587\u4ef6\uff1a``{\u540e\u7f00: \u8def\u5f84}``\n    _scratch_paths: \"dict[str, str]\"\n\n    def temppath(self, path=None, suffix=\".svg\"):\n        \"\"\"\u53d6\u5f97\u4e00\u4e2a\u53ef\u7528\u4e8e\u5199 SVG \u7684\u8def\u5f84\u3002\n\n        .. note::\n           \u4f20\u5165 ``path`` \u65f6\u539f\u6837\u8fd4\u56de\u3002\u672a\u4f20\u5165\u65f6 **\u590d\u7528** \u672c\u5bf9\u8c61\u81ea\u5df1\u7684 scratch \u6587\u4ef6\uff0c\n           \u800c\u4e0d\u662f\u6bcf\u6b21 ``mkstemp()``\u3002\u65e7\u884c\u4e3a\u6bcf\u5e27\u90fd\u4f1a\u65b0\u5efa\u6587\u4ef6\u5e76\u6cc4\u6f0f fd\uff0c\n           \u662f\u957f\u671f\u8fd0\u884c\u7a0b\u5e8f\u7684\u7a33\u5b9a\u6027\u9690\u60a3\uff1b\u6240\u6709\u8c03\u7528\u65b9\u90fd\u4f1a\u6574\u6587\u4ef6\u8986\u76d6\u5199\uff0c\n           \u56e0\u6b64\u590d\u7528\u540c\u4e00\u4e2a\u8def\u5f84\u662f\u5b89\u5168\u7684\u3002\n        \"\"\"\n        if path:\n            return path\n        return self.scratch_path(suffix)\n\n    def scratch_path(self, suffix=\".svg\", slot=0):\n        \"\"\"\u53d6\uff08\u5fc5\u8981\u65f6\u521b\u5efa\uff09\u4e00\u4e2a\u53ef\u590d\u7528\u7684\u4e34\u65f6\u6587\u4ef6\u8def\u5f84\u3002\n\n        ``slot`` \u7528\u4e8e\u8ba9\u540c\u4e00\u4e2a\u7ed8\u5236\u5bf9\u8c61\u6301\u6709\u591a\u4e2a\u4e92\u4e0d\u5e72\u6270\u7684 scratch \u6587\u4ef6\n        \uff08\u5bf9\u5e94\u65e7 API \u91cc\u7684 ``temppath`` / ``temppath2`` / ``temppath3`` / ``temppath4``\uff09\u3002\n        \"\"\"\n        paths = self.__dict__.setdefault(\"_scratch_paths\", {})\n        key = (suffix, slot)\n        cached = paths.get(key)\n        if cached is None:\n            from tempfile import mkstemp\n\n            fd, cached = mkstemp(suffix=suffix, prefix=\"tkdeft.temp.\")\n            _close_fd(fd)  # mkstemp \u8fd4\u56de\u7684 fd \u5fc5\u987b\u663e\u5f0f\u5173\u95ed\uff0c\u5426\u5219\u6cc4\u6f0f\n            paths[key] = cached\n        return cached\n\n    def cleanup(self):\n        \"\"\"\u5220\u9664\u672c\u5bf9\u8c61\u521b\u5efa\u7684 scratch \u4e34\u65f6\u6587\u4ef6\u3002\"\"\"\n        from os import remove\n        from os.path import exists\n\n        removed = 0\n        for suffix_path in self.__dict__.get(\"_scratch_paths\", {}).values():\n            try:\n                if exists(suffix_path):\n                    remove(suffix_path)\n                    removed += 1\n            except OSError:\n                pass\n        self.__dict__.pop(\"_scratch_paths\", None)\n        return removed\n\n    def create_drawing(self, width, height, temppath=None, **kwargs):\n        path = self.temppath(temppath)\n        import svgwrite\n\n        dwg = svgwrite.Drawing(path, width=width, height=height, **kwargs)\n\n        return path, dwg\n</code></pre>"},{"location":"api/tkdeft.windows.draw.html#tkdeft.windows.draw.DSvgDraw.cleanup","title":"<code>cleanup()</code>","text":"<p>\u5220\u9664\u672c\u5bf9\u8c61\u521b\u5efa\u7684 scratch \u4e34\u65f6\u6587\u4ef6\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\windows\\draw.py</code> <pre><code>def cleanup(self):\n    \"\"\"\u5220\u9664\u672c\u5bf9\u8c61\u521b\u5efa\u7684 scratch \u4e34\u65f6\u6587\u4ef6\u3002\"\"\"\n    from os import remove\n    from os.path import exists\n\n    removed = 0\n    for suffix_path in self.__dict__.get(\"_scratch_paths\", {}).values():\n        try:\n            if exists(suffix_path):\n                remove(suffix_path)\n                removed += 1\n        except OSError:\n            pass\n    self.__dict__.pop(\"_scratch_paths\", None)\n    return removed\n</code></pre>"},{"location":"api/tkdeft.windows.draw.html#tkdeft.windows.draw.DSvgDraw.scratch_path","title":"<code>scratch_path(suffix='.svg', slot=0)</code>","text":"<p>\u53d6\uff08\u5fc5\u8981\u65f6\u521b\u5efa\uff09\u4e00\u4e2a\u53ef\u590d\u7528\u7684\u4e34\u65f6\u6587\u4ef6\u8def\u5f84\u3002</p> <p><code>slot</code> \u7528\u4e8e\u8ba9\u540c\u4e00\u4e2a\u7ed8\u5236\u5bf9\u8c61\u6301\u6709\u591a\u4e2a\u4e92\u4e0d\u5e72\u6270\u7684 scratch \u6587\u4ef6 \uff08\u5bf9\u5e94\u65e7 API \u91cc\u7684 <code>temppath</code> / <code>temppath2</code> / <code>temppath3</code> / <code>temppath4</code>\uff09\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\windows\\draw.py</code> <pre><code>def scratch_path(self, suffix=\".svg\", slot=0):\n    \"\"\"\u53d6\uff08\u5fc5\u8981\u65f6\u521b\u5efa\uff09\u4e00\u4e2a\u53ef\u590d\u7528\u7684\u4e34\u65f6\u6587\u4ef6\u8def\u5f84\u3002\n\n    ``slot`` \u7528\u4e8e\u8ba9\u540c\u4e00\u4e2a\u7ed8\u5236\u5bf9\u8c61\u6301\u6709\u591a\u4e2a\u4e92\u4e0d\u5e72\u6270\u7684 scratch \u6587\u4ef6\n    \uff08\u5bf9\u5e94\u65e7 API \u91cc\u7684 ``temppath`` / ``temppath2`` / ``temppath3`` / ``temppath4``\uff09\u3002\n    \"\"\"\n    paths = self.__dict__.setdefault(\"_scratch_paths\", {})\n    key = (suffix, slot)\n    cached = paths.get(key)\n    if cached is None:\n        from tempfile import mkstemp\n\n        fd, cached = mkstemp(suffix=suffix, prefix=\"tkdeft.temp.\")\n        _close_fd(fd)  # mkstemp \u8fd4\u56de\u7684 fd \u5fc5\u987b\u663e\u5f0f\u5173\u95ed\uff0c\u5426\u5219\u6cc4\u6f0f\n        paths[key] = cached\n    return cached\n</code></pre>"},{"location":"api/tkdeft.windows.draw.html#tkdeft.windows.draw.DSvgDraw.temppath","title":"<code>temppath(path=None, suffix='.svg')</code>","text":"<p>\u53d6\u5f97\u4e00\u4e2a\u53ef\u7528\u4e8e\u5199 SVG \u7684\u8def\u5f84\u3002</p> <p>.. note::    \u4f20\u5165 <code>path</code> \u65f6\u539f\u6837\u8fd4\u56de\u3002\u672a\u4f20\u5165\u65f6 \u590d\u7528 \u672c\u5bf9\u8c61\u81ea\u5df1\u7684 scratch \u6587\u4ef6\uff0c    \u800c\u4e0d\u662f\u6bcf\u6b21 <code>mkstemp()</code>\u3002\u65e7\u884c\u4e3a\u6bcf\u5e27\u90fd\u4f1a\u65b0\u5efa\u6587\u4ef6\u5e76\u6cc4\u6f0f fd\uff0c    \u662f\u957f\u671f\u8fd0\u884c\u7a0b\u5e8f\u7684\u7a33\u5b9a\u6027\u9690\u60a3\uff1b\u6240\u6709\u8c03\u7528\u65b9\u90fd\u4f1a\u6574\u6587\u4ef6\u8986\u76d6\u5199\uff0c    \u56e0\u6b64\u590d\u7528\u540c\u4e00\u4e2a\u8def\u5f84\u662f\u5b89\u5168\u7684\u3002</p> \u6e90\u4ee3\u7801\u4f4d\u4e8e\uff1a <code>tkdeft\\windows\\draw.py</code> <pre><code>def temppath(self, path=None, suffix=\".svg\"):\n    \"\"\"\u53d6\u5f97\u4e00\u4e2a\u53ef\u7528\u4e8e\u5199 SVG \u7684\u8def\u5f84\u3002\n\n    .. note::\n       \u4f20\u5165 ``path`` \u65f6\u539f\u6837\u8fd4\u56de\u3002\u672a\u4f20\u5165\u65f6 **\u590d\u7528** \u672c\u5bf9\u8c61\u81ea\u5df1\u7684 scratch \u6587\u4ef6\uff0c\n       \u800c\u4e0d\u662f\u6bcf\u6b21 ``mkstemp()``\u3002\u65e7\u884c\u4e3a\u6bcf\u5e27\u90fd\u4f1a\u65b0\u5efa\u6587\u4ef6\u5e76\u6cc4\u6f0f fd\uff0c\n       \u662f\u957f\u671f\u8fd0\u884c\u7a0b\u5e8f\u7684\u7a33\u5b9a\u6027\u9690\u60a3\uff1b\u6240\u6709\u8c03\u7528\u65b9\u90fd\u4f1a\u6574\u6587\u4ef6\u8986\u76d6\u5199\uff0c\n       \u56e0\u6b64\u590d\u7528\u540c\u4e00\u4e2a\u8def\u5f84\u662f\u5b89\u5168\u7684\u3002\n    \"\"\"\n    if path:\n        return path\n    return self.scratch_path(suffix)\n</code></pre>"},{"location":"api/tkdeft.windows.drawwidget.html","title":"windows.drawwidget \u00b7 \u4ea4\u4e92\u63a7\u4ef6\u57fa\u7c7b","text":"<p>\u53ef\u4ea4\u4e92\u7684\u7ed8\u5236\u63a7\u4ef6\u57fa\u7c7b\u3002</p> <p><code>DDrawWidget</code> \u662f\u4e00\u4e2a\"\u7528\u753b\u5e03\u753b\u51fa\u6765\u7684\u63a7\u4ef6\"\uff1a\u5b83\u628a\u81ea\u8eab\u56db\u4e2a\u4e34\u65f6\u6587\u4ef6\u8def\u5f84 \uff08<code>temppath</code> / <code>temppath2</code> / <code>temppath3</code> / <code>temppath4</code>\uff09\u4ee5 \u60f0\u6027\u5c5e\u6027 \u7684\u5f62\u5f0f\u66b4\u9732\u51fa\u6765\uff0c\u517c\u5bb9\u65e2\u6709\u5b50\u7c7b\u4ee3\u7801\u3002</p> <p>\u65e7\u5b9e\u73b0\u5728 <code>__init__</code> \u91cc\u5bf9\u8fd9\u56db\u4e2a\u8def\u5f84\u4e00\u5f8b <code>mkstemp()</code>\uff0c\u4e14\u4ece\u4e0d\u5173\u95ed\u8fd4\u56de\u7684 fd\uff1a</p> <ul> <li>\u6bcf\u4e2a\u63a7\u4ef6\u4e00\u521b\u5efa\u5c31 \u6cc4\u6f0f 4 \u4e2a\u6587\u4ef6\u63cf\u8ff0\u7b26\uff0820 \u4e2a\u6309\u94ae = 80 \u4e2a\uff09\uff0c   \u957f\u8dd1\u7a0b\u5e8f\u4f1a\u649e\u4e0a Windows \u7684\u53e5\u67c4\u4e0a\u9650\uff1b</li> <li>\u5373\u4f7f\u968f\u540e\u6539\u7528\u4e86 tksvg / skia \u5f15\u64ce\uff0c\u90a3 4 \u4e2a\u4e34\u65f6\u6587\u4ef6\u4f9d\u7136\u8eba\u5728\u5730\u76d8\u4e0a\u3002</li> </ul> <p>\u73b0\u5728\u6539\u4e3a\u6309\u9700\u521b\u5efa\uff1a\u53ea\u6709\u5728\u771f\u6b63\u7528\u5230\u67d0\u4e2a\u8def\u5f84\u65f6\u624d\u5efa\u6587\u4ef6\uff0c\u5e76\u4e14\u6bcf\u4e2a\u63a7\u4ef6 \u7684\u751f\u547d\u5468\u671f\u7ed3\u675f\u65f6\u7531 :meth:<code>~tkdeft.windows.draw.DSvgDraw.cleanup</code> \u56de\u6536\u3002</p>"},{"location":"blog/index.html","title":"\u535a\u5ba2","text":"<p>\u8bb0\u5f55</p>"},{"location":"blog/2024/01/23/%E5%BC%80%E5%A7%8B%E5%88%B6%E4%BD%9C%E6%96%87%E6%A1%A3.html","title":"\u5f00\u59cb\u5236\u4f5c\u6587\u6863","text":"<p>\u5f00\u59cb\u5236\u4f5c\u6587\u6863</p>"},{"location":"blog/2024/01/25/%E5%8F%91%E5%B8%83002-003-004%E7%89%88%E6%9C%AC.html","title":"\u53d1\u5e03<code>0.0.2</code> <code>0.0.3</code> <code>0.0.4</code>\u7248\u672c","text":"<p>\u8865\u5145\u8bbe\u8ba1\u6a21\u677f<code>Fluent</code>\u7684\u7ec4\u4ef6<code>DEntry</code>\u3001<code>DText</code>\u3001<code>DFrame</code>\u3001<code>DBadge</code>\uff08\u76f8\u5bf9\u5e94\u4f1a\u6709\u6df1\u8272\u8bbe\u8ba1\uff0c\u5982<code>DDarkEntry</code>\u7b49\uff09</p> <p></p>"},{"location":"template/index.html","title":"\u4ec0\u4e48\u662f\u6a21\u677f\uff1f","text":"<p>\u6211\u4eec\u90fd\u77e5\u9053\u77e2\u91cf\u4f5c\u56fe\uff0c\u80fd\u505a\u51fa\u8bb8\u591a\u9ad8\u7ea7\u7684\u6548\u679c\uff0c\u800c\u5982\u679c\u505a\u6210\u4e00\u4e2a\u4e3b\u9898\u5e93\uff0c\u9700\u8981\u8003\u8651\u5f88\u591a\u60c5\u51b5\uff0c\u6548\u679c\u5b9e\u73b0\u5355\u4e00\u3002</p> <p>\u6240\u4ee5\u6211\u4eec\u53ea\u80fd\u81ea\u5b9a\u4e49\u7ec4\u4ef6\u5b9e\u73b0</p> <p>\u8fd9\u91cc\u6211\u81ea\u5df1\u505a\u4e86\u4e00\u4e2a\u7ec4\u4ef6\u5e93\uff0c\u4f9b\u5927\u5bb6\u5f53\u505a\u6a21\u677f\u53c2\u8003\uff1atkfluent</p>"},{"location":"usage/index.html","title":"\u5b89\u88c5\u4e0e\u4f7f\u7528","text":""},{"location":"usage/index.html#_2","title":"\u5b89\u88c5","text":"<pre><code>pip install -U tkdeft\n</code></pre> <p><code>tkdeft</code> \u5e95\u5c42\u4f9d\u8d56\u8fd9\u4e9b\u5e93\uff0c\u901a\u5e38\u4f1a\u81ea\u52a8\u88c5\u597d\uff1a</p> <ul> <li><code>tksvg</code> \u2014\u2014 \u8ba9 Tkinter \u80fd\u663e\u793a SVG\uff08\u540c\u65f6\u4e5f\u8d1f\u8d23\u77e2\u91cf\u7ed8\u5236\uff09\uff1b</li> <li><code>tkextrafont</code> \u2014\u2014 \u52a0\u8f7d\u5185\u5d4c\u5b57\u4f53\uff0c\u4fdd\u8bc1\u8de8\u5e73\u53f0\u5916\u89c2\u4e00\u81f4\uff1b</li> <li><code>svgwrite</code> \u2014\u2014 \u751f\u6210\u77e2\u91cf\u56fe\uff1b</li> <li><code>pillow</code> \u2014\u2014 \u4f4d\u56fe\u5904\u7406\u4e0e <code>PhotoImage</code> \u8f6c\u6362\uff1b</li> <li><code>easydict</code> \u2014\u2014 \u7ec4\u4ef6\u5c5e\u6027\u5bb9\u5668\u3002</li> </ul> <p>\u5982\u679c\u5b89\u88c5\u8fc7\u7a0b\u4e2d\u9047\u5230\u95ee\u9898\uff0c\u8bf7\u5148\u53c2\u9605\u8fd9\u4e9b\u9879\u76ee\u5404\u81ea\u7684\u8bf4\u660e\u3002</p>"},{"location":"usage/index.html#_3","title":"\u53ef\u9009\uff1a\u66f4\u5feb\u7684\u7ed8\u5236\u5f15\u64ce","text":"<p>\u9ed8\u8ba4\u5f15\u64ce <code>tksvg</code> \u7684\u5de5\u4f5c\u65b9\u5f0f\u662f\"\u751f\u6210 SVG \u2192 \u5199\u4e34\u65f6\u6587\u4ef6 \u2192 \u518d\u8bfb\u56de\u6765\u6805\u683c\u5316\"\uff0c \u6bcf\u6b21\u91cd\u7ed8\u90fd\u8981\u78b0\u78c1\u76d8\u3002\u60f3\u66f4\u5feb\u53ef\u4ee5\u88c5\u4e00\u4e2a\u8fdb\u7a0b\u5185\u6805\u683c\u5f15\u64ce\uff1a</p> <pre><code>pip install \"tkdeft[skia]\"     # skia-python\uff0c\u901f\u5ea6\u4e0e\u753b\u8d28\u6700\u597d\npip install \"tkdeft[cairo]\"    # pycairo\npip install \"tkdeft[raster]\"   # \u4e0a\u9762\u4e24\u4e2a\u90fd\u88c5\n</code></pre> <p>\u4e0d\u88c5\u4e5f\u80fd\u7528\u2014\u2014<code>Pillow</code> \u5f15\u64ce\uff08\u7f16\u53f7 3\uff09\u96f6\u989d\u5916\u4f9d\u8d56\uff0c\u4e00\u76f4\u5728\u3002</p> <pre><code>from tkdeft.engines import set_engine, list_engines\n\nprint(list_engines())\nset_engine(\"skia\")       # \u6216 set_engine(2)\n</code></pre> <p>\u8be6\u89c1 \u7ed8\u5236\u5f15\u64ce\u3002</p>"},{"location":"usage/index.html#tkdeft","title":"tkdeft \u662f\u4ec0\u4e48","text":"<p>\u4e00\u53e5\u8bdd\uff1a\u628a\u77e2\u91cf\u7ed8\u56fe\u53d8\u6210 Tkinter \u7ec4\u4ef6\u7684\u5e95\u5ea7\u3002</p> <p>\u5b83\u4e0d\u542b\u4efb\u4f55\u5177\u4f53\u7ec4\u4ef6\uff08\u6309\u94ae\u3001\u8f93\u5165\u6846\u90fd\u6ca1\u6709\uff09\uff0c\u53ea\u63d0\u4f9b\u96f6\u4ef6\uff1a</p> \u6a21\u5757 \u5185\u5bb9 <code>tkdeft.engines</code> \u53ef\u63d2\u62d4\u7684\u7ed8\u5236\u5f15\u64ce\uff08tksvg / wand / skia / pillow / cairo\uff09\u4e0e\u56fe\u7247\u7f13\u5b58 <code>tkdeft.svg</code> \u4fee\u6b63\u8fc7\u7684 SVG \u5f62\u72b6\u52a9\u624b <code>tkdeft.windows</code> <code>DCanvas</code> / <code>DDraw</code> / <code>DDrawWidget</code> <code>tkdeft.object</code> <code>DObject</code> \u914d\u7f6e\u5bb9\u5668 <p>\u60f3\u76f4\u63a5\u4f53\u9a8c\"\u7528\u8fd9\u5957\u96f6\u4ef6\u642d\u51fa\u6765\u7684\u754c\u9762\u5e93\"\uff0c\u8bf7\u53bb\u770b tkfluent\u3002</p>"},{"location":"usage/index.html#_4","title":"\u76ee\u5f55","text":"<ul> <li>\u7ed8\u5236\u5f15\u64ce \u2014\u2014 \u5f15\u64ce\u5217\u8868\u3001\u5207\u6362\u65b9\u5f0f\u3001\u7f13\u5b58\u673a\u5236\u3001\u81ea\u5df1\u5199\u5f15\u64ce</li> <li>\u81ea\u5b9a\u4e49\u7ec4\u4ef6 \u2014\u2014 \u7528 <code>DObject</code> + <code>DDrawWidget</code> \u505a\u4e00\u4e2a\u63a7\u4ef6</li> <li>\u4ec0\u4e48\u662f\u6a21\u677f \u2014\u2014 \u4e3a\u4ec0\u4e48\u8fd9\u4e2a\u5e93\u4e0d\u76f4\u63a5\u505a\u6210\u4e3b\u9898\u5e93</li> </ul>"},{"location":"usage/custom-drawing.html","title":"\u7ed8\u5236\u5f15\u64ce","text":"<p><code>tkdeft</code> \u628a\"\u753b\u4ec0\u4e48\"\u548c\"\u7528\u4ec0\u4e48\u753b\"\u5206\u5f00\u4e86\u3002</p> <p>\u7ec4\u4ef6\u4e0d\u518d\u76f4\u63a5\u62fc SVG\uff0c\u800c\u662f\u63cf\u8ff0\u4e00\u4e2a \u7ed8\u5236\u89c4\u683c\uff08spec\uff09\u2014\u2014\u5c3a\u5bf8\u3001\u5706\u89d2\u3001\u586b\u5145\u8272\u3001 \u63cf\u8fb9\u8272\u4e0e\u900f\u660e\u5ea6\u2026\u2026\u7136\u540e\u628a\u5b83\u4ea4\u7ed9\u5f53\u524d\u5f15\u64ce\u53bb\u6805\u683c\u5316\u3002\u6362\u5f15\u64ce\u4e0d\u9700\u8981\u6539\u4e00\u884c\u4e1a\u52a1\u4ee3\u7801\u3002</p>"},{"location":"usage/custom-drawing.html#_2","title":"\u5185\u7f6e\u5f15\u64ce","text":"\u5f15\u64ce \u7c7b\u578b \u8bf4\u660e \u989d\u5916\u4f9d\u8d56 <code>tksvg</code> SVG \u9ed8\u8ba4\u3002<code>svgwrite</code> \u751f\u6210 SVG \u2192 <code>tksvg</code> \u6805\u683c\u5316\uff0c\u4fdd\u6301\u5386\u53f2\u884c\u4e3a \u65e0 <code>wand</code> SVG \u7ecf Wand(ImageMagick) \u8f6c PNG <code>Wand</code> <code>skia</code> \u6805\u683c <code>skia-python</code>\uff0c\u8fdb\u7a0b\u5185\u76f4\u63a5\u51fa\u4f4d\u56fe\uff0c\u901f\u5ea6\u4e0e\u753b\u8d28\u6700\u597d <code>pip install tkdeft[skia]</code> <code>pillow</code> \u6805\u683c Pillow \u8d85\u91c7\u6837\u6297\u952f\u9f7f\uff0c\u6c38\u8fdc\u53ef\u7528 \u65e0\uff08Pillow \u662f\u786c\u4f9d\u8d56\uff09 <code>cairo</code> \u6805\u683c <code>pycairo</code> <code>pip install tkdeft[cairo]</code>"},{"location":"usage/custom-drawing.html#_3","title":"\u5207\u6362\u5f15\u64ce","text":"<pre><code>from tkdeft.engines import set_engine, get_engine, list_engines\n\nprint(list_engines())\n# {'tksvg': True, 'wand': True, 'skia': True, 'pillow': True, 'cairo': True}\n\nset_engine(\"skia\")     # \u6309\u540d\u5b57\nset_engine(2)          # \u6216\u6309\u7f16\u53f7\uff1a0=tksvg 1=wand 2=skia 3=pillow 4=cairo\n\nprint(get_engine().name)\n</code></pre> <p>\u5f15\u64ce\u4e0d\u53ef\u7528\u65f6 <code>set_engine</code> \u4f1a\u629b <code>ValueError</code>\uff08\u800c\u4e0d\u662f\u9759\u9ed8\u9000\u56de\u6162\u8def\u5f84\uff09\uff0c \u514d\u5f97\u4f60\u4ee5\u4e3a\u5f00\u4e86 <code>skia</code>\u3001\u5176\u5b9e\u8fd8\u5728\u8d70\u78c1\u76d8\u3002</p>"},{"location":"usage/custom-drawing.html#_4","title":"\u76f4\u63a5\u6e32\u67d3\u4e00\u5f20\u56fe","text":"<pre><code>from tkdeft.engines import RoundRectSpec, render_roundrect\n\nspec = RoundRectSpec(\n    width=120, height=32, rx=6,\n    fill=\"#ffffff\", fill_opacity=1,\n    outline=\"#000000\", outline_opacity=0.2,\n    outline_width=1,\n)\n\nphoto = render_roundrect(spec, master=widget)   # -&gt; tkinter.PhotoImage\n</code></pre> <p>\u5f53\u524d\u5f15\u64ce\u662f SVG \u7cfb\u65f6\u8fd4\u56de <code>None</code>\uff0c\u8868\u793a\"\u8fd9\u6761\u8def\u5f84\u6211\u4e0d\u53c2\u4e0e\"\uff0c \u8c03\u7528\u65b9\u5e94\u5f53\u56de\u9000\u5230\u65e2\u6709\u7684 <code>svgwrite</code> + <code>tksvg</code> \u6d41\u7a0b\u3002</p> <p>\u53ef\u7528\u7684\u89c4\u683c\u6709\u4e09\u7c7b\uff1a<code>RoundRectSpec</code>\uff08\u5706\u89d2\u77e9\u5f62\uff09\u3001<code>TrackSpec</code>\uff08\u6ed1\u5757\u8fdb\u5ea6\u6761\u69fd\uff09\u3001 <code>ThumbSpec</code>\uff08\u6ed1\u5757\u5706\u5f62\u628a\u624b\uff09\u3002</p>"},{"location":"usage/custom-drawing.html#_5","title":"\u7f13\u5b58","text":"<p>\u6e32\u67d3\u7ed3\u679c\u6309 <code>(\u5f15\u64ce\u540d, \u56fe\u5143\u7c7b\u578b, spec)</code> \u7f13\u5b58\u3002\u56e0\u4e3a spec \u662f\u4e0d\u53ef\u53d8\u7684\uff0c \u540c\u5c3a\u5bf8\u540c\u914d\u8272\u7684\u4e00\u7ec4\u63a7\u4ef6\u4f1a\u5171\u7528\u540c\u4e00\u5f20 <code>PhotoImage</code>\u3002</p> <pre><code>from tkdeft.engines import cache_stats, set_cache_budget, clear_cache\n\nprint(cache_stats())\n# {'interpreters': 1, 'entries': 62, 'pixels': 169244, 'budget': 8000000,\n#  'hits': 178, 'misses': 99, 'hit_rate': 0.642, 'overflow': 0}\n\nset_cache_budget(16_000_000)   # \u8c03\u5927\u50cf\u7d20\u9884\u7b97\nclear_cache()                  # \u6e05\u7a7a\uff08\u6ce8\u610f\uff1a\u4f1a\u6e05\u6389\u5df2\u53d1\u51fa\u7684\u56fe\u7247\u5f15\u7528\uff09\n</code></pre> <p>\u7f13\u5b58\u4e0d\u505a LRU \u6dd8\u6c70\u3002\u539f\u56e0\u662f <code>PhotoImage</code> \u4e00\u65e6\u88ab\u56de\u6536\uff0c \u5f15\u7528\u5b83\u7684 canvas item \u4f1a\u53d8\u6210\u7a7a\u767d\u2014\u2014\u8fd9\u662f Tkinter \u7684\u7ecf\u5178\u9677\u9631\u3002 \u6240\u4ee5\u8fd9\u91cc\u91c7\u7528\"\u50cf\u7d20\u9884\u7b97 + \u6ee1\u4e86\u5c31\u4e0d\u518d\u5199\u5165\"\uff1a\u5df2\u7ecf\u53d1\u51fa\u53bb\u7684\u56fe\u7247\u6c38\u8fdc\u4fdd\u6301\u5b58\u6d3b\uff0c \u7f13\u5b58\u4e0d\u4e0b\u7684\u89c4\u683c\u9000\u5316\u4e3a\"\u6bcf\u6b21\u91cd\u65b0\u6e32\u67d3\"\uff0c\u53ea\u635f\u5931\u901f\u5ea6\uff0c\u7edd\u4e0d\u635f\u574f\u753b\u9762\u3002</p>"},{"location":"usage/custom-drawing.html#_6","title":"\u81ea\u5df1\u5199\u4e00\u4e2a\u5f15\u64ce","text":"<p>\u7ee7\u627f <code>DrawEngine</code>\uff0c\u5b9e\u73b0\u9700\u8981\u7684\u6e32\u67d3\u65b9\u6cd5\uff0c\u7136\u540e\u6ce8\u518c\uff1a</p> <pre><code>from tkdeft.engines import DrawEngine, register_engine\n\n\nclass MyEngine(DrawEngine):\n    name = \"myengine\"\n    kind = \"raster\"                  # \u53ea\u6709 raster \u4f1a\u8d70\u5feb\u901f\u8def\u5f84\n    requires = (\"mylib\",)            # \u7528\u4e8e available() \u63a2\u6d4b\n\n    def render_roundrect(self, spec):\n        # \u8fd4\u56de PIL.Image\uff08RGBA\uff09\u5373\u53ef\n        ...\n\n\nregister_engine(MyEngine())\n</code></pre> <p><code>requirements</code> \u91cc\u7684\u6a21\u5757\u63a2\u6d4b\u4e0d\u5230\u65f6\uff0c<code>set_engine(\"myengine\")</code> \u4f1a\u62a5\u9519\u5e76\u8bf4\u660e\u7f3a\u4ec0\u4e48\u3002</p>"},{"location":"usage/custom-drawing.html#_7","title":"\u5750\u6807\u4e0e\u63cf\u8fb9\u7ea6\u5b9a","text":"<p>\u6240\u6709 spec \u7684\u5750\u6807\u90fd\u4ee5\u81ea\u8eab\u5de6\u4e0a\u89d2\u4e3a <code>(0, 0)</code>\uff0c\u5e76\u4e14\u63cf\u8fb9\u662f\u5c45\u4e2d\u7684\uff1a \u51e0\u4f55\u4f1a\u88ab\u5411\u5185\u6536\u7f29\u534a\u4e2a\u7ebf\u5bbd\uff0c\u4f7f\u63cf\u8fb9\u7684\u5916\u6cbf\u6b63\u597d\u8d34\u5408\u56fe\u7247\u8fb9\u7f18\u3002</p> <p>\u8fd9\u6b63\u662f\u5386\u53f2\u4e0a\u51fa\u95ee\u9898\u7684\u5730\u65b9\u2014\u2014\u65e7\u4ee3\u7801\u628a\u77e9\u5f62\u653e\u5728 <code>(0.5, 0.5)</code> \u5374\u4ecd\u7528\u6574\u5bbd\u6574\u9ad8\uff0c \u63cf\u8fb9\u4e2d\u5fc3\u7ebf\u6b63\u597d\u538b\u5728\u753b\u5e03\u8fb9\u754c\u4e0a\uff0c\u4e8e\u662f\u4e0b\u8fb9\u6846\u548c\u53f3\u8fb9\u6846\u88ab\u6574\u4e2a\u88c1\u6389\u3002 <code>tkdeft.svg.roundrect_geometry()</code> \u7528\u540c\u4e00\u5957\u89c4\u5219\u8ba1\u7b97 SVG \u51e0\u4f55\uff0c \u4fdd\u8bc1 SVG \u5f15\u64ce\u4e0e\u6805\u683c\u5f15\u64ce\u753b\u9762\u4e00\u81f4\u3002</p>"},{"location":"usage/custom-widget.html","title":"\u81ea\u5b9a\u4e49\u7ec4\u4ef6","text":"<p><code>tkdeft</code> \u672c\u8eab\u4e0d\u5e26\u4efb\u4f55\u5177\u4f53\u7ec4\u4ef6\u2014\u2014\u5b83\u63d0\u4f9b\u7684\u662f\"\u628a\u77e2\u91cf\u56fe\u5f62\u53d8\u6210 Tkinter \u63a7\u4ef6\" \u6240\u9700\u7684\u90a3\u5957\u96f6\u4ef6\u3002\u60f3\u505a\u4e00\u4e2a\u81ea\u5df1\u7684\u7ec4\u4ef6\uff0c\u901a\u5e38\u53ea\u8981\u7ec4\u5408\u8fd9\u56db\u6837\u4e1c\u897f\uff1a</p> \u96f6\u4ef6 \u4f5c\u7528 <code>DObject</code> \u7edf\u4e00\u7684\u5c5e\u6027\u914d\u7f6e\u63a5\u53e3\uff08<code>dconfigure</code> / <code>dcget</code>\uff09 <code>DCanvas</code> \u5e26\u7ed8\u5236\u80fd\u529b\u7684\u753b\u5e03 <code>DDraw</code> \u628a SVG / \u4f4d\u56fe\u53d8\u6210 <code>PhotoImage</code> <code>DDrawWidget</code> \u4e8b\u4ef6 \u2192 \u72b6\u6001 \u2192 \u91cd\u7ed8 \u7684\u4ea4\u4e92\u9aa8\u67b6 <p>\u914d\u5957\u7684\u5b8c\u6574\u793a\u4f8b\u53ef\u4ee5\u53c2\u8003 tkfluent\u2014\u2014 \u5b83\u5c31\u662f\u7528\u8fd9\u51e0\u4e2a\u96f6\u4ef6\u642d\u51fa\u6765\u7684\u7ec4\u4ef6\u5e93\u3002</p>"},{"location":"usage/custom-widget.html#dobject","title":"DObject\uff1a\u914d\u7f6e\u5bb9\u5668","text":"<p><code>DObject</code> \u7ed9\u7ec4\u4ef6\u4e00\u4e2a\u7edf\u4e00\u8bfb\u5199\u5c5e\u6027\u7684\u63a5\u53e3\uff0c\u907f\u514d\u5230\u5904\u5199 <code>self.xxx = ...</code>\uff1a</p> <pre><code>from easydict import EasyDict\n\nfrom tkdeft.object import DObject\n\n\nclass MyWidget(DObject):\n    def __init__(self):\n        self.attributes = EasyDict({\n            \"text\": \"\",\n            \"text_color\": \"#000000\",\n            \"state\": \"normal\",\n        })\n\n    def set_text(self, text):\n        self.dconfigure(text=text)\n\n\nwidget = MyWidget()\nwidget.set_text(\"\u4f60\u597d\")\nprint(widget.dcget(\"text\"))      # \u4f60\u597d\nprint(widget.dcget(\"\u6ca1\u8fd9\u4e2a\u952e\"))   # None\n</code></pre> <p>\u8981\u70b9\uff1a</p> <ul> <li><code>dconfigure(**kwargs)</code> \u53ea\u63a5\u53d7\u5df2\u7ecf\u5b58\u5728\u4e8e <code>attributes</code> \u91cc\u7684\u952e\uff0c   \u5199\u9519\u7684\u952e\u4f1a\u88ab\u9759\u9ed8\u5ffd\u7565\u2014\u2014\u8fd9\u662f\u6709\u610f\u7684\uff0c\u9632\u6b62\u7b14\u8bef\u6c61\u67d3\u7ec4\u4ef6\u72b6\u6001\u3002</li> <li>\u6240\u4ee5\u8981\u65b0\u589e\u4e00\u4e2a\u53ef\u914d\u7f6e\u9879\uff0c\u5fc5\u987b\u5148\u628a\u952e\u653e\u8fdb <code>attributes</code>\u3002</li> <li><code>dcget(key)</code> \u8bfb\u4e0d\u5230\u65f6\u8fd4\u56de <code>None</code>\uff0c\u4e0d\u629b\u5f02\u5e38\u3002</li> </ul>"},{"location":"usage/custom-widget.html#ddrawwidget","title":"DDrawWidget\uff1a\u4ea4\u4e92\u9aa8\u67b6","text":"<p><code>DDrawWidget</code> \u662f\"\u7528\u753b\u5e03\u753b\u51fa\u6765\u7684\u63a7\u4ef6\"\u7684\u57fa\u7c7b\uff0c\u5b83\u66ff\u4f60\u5904\u7406\u597d\u4e86 \u9f20\u6807/\u7126\u70b9\u4e8b\u4ef6 \u2192 \u5185\u90e8\u72b6\u6001 \u2192 \u91cd\u7ed8 \u8fd9\u6761\u94fe\u8def\uff1a</p> <pre><code>from tkdeft.svg import add_roundrect\nfrom tkdeft.windows.canvas import DCanvas\nfrom tkdeft.windows.draw import DSvgDraw\nfrom tkdeft.windows.drawwidget import DDrawWidget\n\n\nclass MyDraw(DSvgDraw):\n    def create_roundrect(self, x1, y1, x2, y2, radius, radiusy=None,\n                         temppath=None, fill=\"transparent\", outline=\"black\",\n                         width=1):\n        drawing = self.create_drawing(x2 - x1, y2 - y1, temppath=temppath)\n        add_roundrect(drawing[1], x1, y1, x2, y2, radius, radiusy,\n                      fill=fill, outline=outline, width=width)\n        drawing[1].save()\n        return drawing[0]\n\n\nclass MyCanvas(DCanvas):\n    draw = MyDraw\n\n\nclass MyWidget(MyCanvas, DDrawWidget):\n    def _draw(self, event=None):\n        super()._draw(event)              # \u5904\u7406\u80cc\u666f\u8272\u7b49\u516c\u5171\u90e8\u5206\n        if not self.winfo_ismapped():\n            return\n\n        width, height = self.winfo_width(), self.winfo_height()\n        if hasattr(self, \"element\"):\n            self.delete(self.element)\n\n        if self.button1:\n            color = \"#cccccc\"\n        elif self.enter:\n            color = \"#ffffff\"\n        else:\n            color = \"#f3f3f3\"\n\n        self.element = self.create_roundrect(\n            0, 0, width, height, 6,\n            temppath=self.temppath,\n            fill=color, outline=\"#000000\", width=1,\n        )\n</code></pre> <p><code>DDrawWidget</code> \u5df2\u7ecf\u7ed1\u597d\u5e76\u7ef4\u62a4\u4e86\u8fd9\u4e9b\u72b6\u6001\uff0c\u4f9b <code>_draw</code> \u76f4\u63a5\u8bfb\u53d6\uff1a</p> \u5c5e\u6027 \u542b\u4e49 <code>self.enter</code> \u9f20\u6807\u662f\u5426\u5728\u63a7\u4ef6\u5185 <code>self.button1</code> \u5de6\u952e\u662f\u5426\u6309\u4e0b <code>self.isfocus</code> \u662f\u5426\u6301\u6709\u7126\u70b9 <code>self.temppath</code> ~ <code>temppath4</code> \u53ef\u590d\u7528\u7684\u4e34\u65f6\u6587\u4ef6\u8def\u5f84\uff08\u60f0\u6027\u521b\u5efa\uff09 <p>\u89e6\u53d1\u91cd\u7ed8\u7684\u4e8b\u4ef6\uff1a<code>&lt;Configure&gt;</code> <code>&lt;Enter&gt;</code> <code>&lt;Leave&gt;</code> <code>&lt;Button-1&gt;</code> <code>&lt;ButtonRelease-1&gt;</code> <code>&lt;FocusIn&gt;</code> <code>&lt;FocusOut&gt;</code>\u3002</p> <p>\u677e\u5f00\u5de6\u952e\u4e14\u9f20\u6807\u4ecd\u5728\u63a7\u4ef6\u5185\u65f6\uff0c\u4f1a\u751f\u6210\u4e00\u4e2a <code>&lt;&lt;Clicked&gt;&gt;</code> \u865a\u62df\u4e8b\u4ef6\uff1a</p> <pre><code>widget.bind(\"&lt;&lt;Clicked&gt;&gt;\", lambda event: print(\"clicked\"))\n</code></pre> <p>\u4e0d\u8981\u81ea\u5df1 mkstemp</p> <p><code>self.temppath</code> \u8fd9\u7c7b\u5c5e\u6027\u662f\u60f0\u6027\u7684\uff1a\u771f\u6b63\u7528\u5230\u65f6\u624d\u521b\u5efa\u6587\u4ef6\uff0c \u7531\u7ed8\u56fe\u5bf9\u8c61\u6301\u6709\u3001\u5e76\u5728\u63a7\u4ef6\u9500\u6bc1\u65f6\u56de\u6536\u3002</p> <p>\u5386\u53f2\u7248\u672c\u5728 <code>__init__</code> \u91cc\u4e00\u6b21\u6027 <code>mkstemp()</code> \u56db\u4e2a\u4e34\u65f6\u6587\u4ef6\u4e14\u4ece\u4e0d\u5173\u95ed \u8fd4\u56de\u7684 fd\u2014\u201420 \u4e2a\u6309\u94ae\u5c31\u4f1a\u6cc4\u6f0f 80 \u4e2a\u6587\u4ef6\u63cf\u8ff0\u7b26 + 80 \u4e2a\u6b8b\u7559\u6587\u4ef6\u3002 \u8bf7\u76f4\u63a5\u4f7f\u7528 <code>self.temppath</code>\u3002</p>"},{"location":"usage/custom-widget.html#_2","title":"\u4e00\u6b21\u70b9\u51fb\u7684\u5b8c\u6574\u987a\u5e8f","text":"<pre><code>&lt;Button-1&gt;        \u2192  button1 = True   \u2192 _draw()\n&lt;ButtonRelease-1&gt; \u2192  button1 = False  \u2192 _draw()\n                          \u2193\n                   \u9f20\u6807\u4ecd\u5728\u63a7\u4ef6\u5185 \u2192 \u751f\u6210 &lt;&lt;Clicked&gt;&gt;\n</code></pre> <p>\u6240\u4ee5\"\u6309\u4f4f\u540e\u628a\u9f20\u6807\u62d6\u51fa\u53bb\u518d\u677e\u5f00\"\u4e0d\u4f1a\u89e6\u53d1\u70b9\u51fb\uff0c\u4e0e\u7cfb\u7edf\u63a7\u4ef6\u884c\u4e3a\u4e00\u81f4\u3002</p>"},{"location":"usage/custom-widget.html#_3","title":"\u6362\u4e00\u4e2a\u7ed8\u5236\u5f15\u64ce","text":"<p>\u4f60\u7684\u7ec4\u4ef6\u4e0d\u9700\u8981\u5173\u5fc3\u5e95\u5c42\u662f SVG \u8fd8\u662f skia\u3002\u53ea\u8981\u5728 <code>_draw</code> \u91cc\u4f18\u5148\u8d70\u6805\u683c \u5feb\u901f\u8def\u5f84\uff0c\u5c31\u80fd\u81ea\u52a8\u83b7\u5f97\"\u8fdb\u7a0b\u5185\u51fa\u56fe + \u7ed3\u679c\u7f13\u5b58\"\u7684\u6536\u76ca\uff1a</p> <pre><code>item = self.create_roundrect_raster(\n    0, 0, width, height, 6,\n    fill=\"#ffffff\", outline=\"#000000\", outline_opacity=0.2,\n)\nif item is None:\n    item = self.create_roundrect(...)      # \u56de\u9000\u5230 SVG\n</code></pre> <p><code>create_roundrect_raster</code> \u5728\u5f53\u524d\u5f15\u64ce\u662f SVG \u7cfb\uff08tksvg / wand\uff09\u65f6\u8fd4\u56de <code>None</code>\uff0c \u8868\u793a\"\u8fd9\u6761\u8def\u5f84\u6211\u4e0d\u53c2\u4e0e\"\uff0c\u4e8e\u662f\u5e73\u7a33\u56de\u9000\u5230\u4f60\u81ea\u5df1\u7684 SVG \u5b9e\u73b0\u3002 \u7ec6\u8282\u89c1 \u7ed8\u5236\u5f15\u64ce\u3002</p>"},{"location":"usage/custom-widget.html#_4","title":"\u522b\u5fd8\u4e86\u4fdd\u6d3b\u56fe\u7247","text":"<p>Tkinter \u7684\u753b\u5e03\u5143\u7d20\u4e0d\u4f1a\u66ff Python \u4fa7\u6301\u6709 <code>PhotoImage</code> \u5f15\u7528\u3002 \u4e00\u65e6\u56fe\u7247\u88ab\u5783\u573e\u56de\u6536\uff0c\u5bf9\u5e94\u7684\u753b\u5e03\u5143\u7d20\u4f1a\u53d8\u6210\u7a7a\u767d\uff1a</p> <pre><code># \u2717 \u540c\u4e00\u753b\u5e03\u4e0a\u591a\u5f20\u56fe\u7247\u65f6\uff0c\u53ea\u6709\u6700\u540e\u4e00\u5f20\u80fd\u6d3b\u4e0b\u6765\nself._img = self.svgdraw.create_svg_image(path)\nself.create_image(0, 0, anchor=\"nw\", image=self._img)\n\n# \u2713 \u4ea4\u7ed9\u753b\u5e03\u4fdd\u7ba1\nself._img = self.svgdraw.create_svg_image(path)\nitem = self.create_image(0, 0, anchor=\"nw\", image=self._img)\nself._keep_photo(item, self._img)\n</code></pre> <p><code>DCanvas._keep_photo(item, photo)</code> \u6309\u753b\u5e03\u5143\u7d20 id \u8bb0\u5f55\u5f15\u7528\uff0c \u5e76\u5728\u5143\u7d20\u5931\u6548\u540e\u81ea\u52a8\u6e05\u7406\u3002</p>"},{"location":"blog/archive/2024.html","title":"2024","text":""},{"location":"blog/category/%E6%A8%A1%E5%9D%97.html","title":"\u6a21\u5757","text":""},{"location":"blog/category/%E6%A8%A1%E6%9D%BF.html","title":"\u6a21\u677f","text":""},{"location":"blog/category/%E6%96%87%E6%A1%A3.html","title":"\u6587\u6863","text":""}]}